window.HSK_TEXTS = [{"l": 1, "texts": [{"n": 1, "zh": "对话：阿玲和小雪聊阿玲的男朋友", "vi": "Hội thoại: A Linh và Tiểu Tuyết nói về bạn trai của A Linh", "en": "Dialogue: A Linh and Xiaoxue talk about A Linh's boyfriend", "kw": ["法律", "俩", "印象", "深", "熟悉", "不仅", "性格"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "阿玲，听说你男朋友周南跟你一个学校，他是你同学吗？", "p": ["ā", "líng", "", "tīng", "shuō", "nǐ", "nán", "péng", "you", "zhōu", "nán", "gēn", "nǐ", "yí", "gè", "xué", "xiào", "", "tā", "shì", "nǐ", "tóng", "xué", "ma", ""], "vi": "A Linh, nghe nói bạn trai cậu là Châu Nam học cùng trường với cậu, anh ấy là bạn cùng lớp à?", "en": "A Linh, I heard your boyfriend Zhou Nan goes to the same university as you. Is he in your class?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "他学的是法律，我学的是汉语。我们俩不是一个班的。", "p": ["tā", "xué", "de", "shì", "fǎ", "lǜ", "", "wǒ", "xué", "de", "shì", "hàn", "yǔ", "", "wǒ", "men", "liǎ", "bú", "shì", "yí", "gè", "bān", "de", ""], "vi": "Anh ấy học luật, mình học tiếng Trung. Hai đứa không cùng lớp.", "en": "He studies law, and I study Chinese. The two of us aren't in the same class."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你们是在什么场合认识的？", "p": ["nǐ", "men", "shì", "zài", "shén", "me", "chǎng", "hé", "rèn", "shí", "de", ""], "vi": "Hai người quen nhau trong hoàn cảnh nào?", "en": "Where did you two meet?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "上个月学校去郊外拍照，我的相机突然不能用了。他帮我弄了很久，我对他印象很深。后来我们常在图书馆见面，才慢慢熟悉起来。", "p": ["shàng", "gè", "yuè", "xué", "xiào", "qù", "jiāo", "wài", "pāi", "zhào", "", "wǒ", "de", "xiàng", "jī", "tū", "rán", "bù", "néng", "yòng", "le", "", "tā", "bāng", "wǒ", "nòng", "le", "hěn", "jiǔ", "", "wǒ", "duì", "tā", "yìn", "xiàng", "hěn", "shēn", "", "hòu", "lái", "wǒ", "men", "cháng", "zài", "tú", "shū", "guǎn", "jiàn", "miàn", "", "cái", "màn", "màn", "shú", "xī", "qǐ", "lái", ""], "vi": "Tháng trước trường tổ chức đi ngoại ô chụp ảnh, máy ảnh của mình đột nhiên hỏng. Anh ấy giúp mình sửa rất lâu, mình có ấn tượng rất sâu về anh ấy. Sau đó bọn mình thường gặp nhau ở thư viện, rồi mới dần quen thuộc.", "en": "Last month the school went to the countryside to take photos, and my camera suddenly stopped working. He spent a long time helping me with it, and that left a deep impression on me. After that we often met in the library, and slowly got to know each other."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你喜欢他，是因为这件事吗？", "p": ["nǐ", "xǐ", "huān", "tā", "", "shì", "yīn", "wèi", "zhè", "jiàn", "shì", "ma", ""], "vi": "Cậu thích anh ấy là vì chuyện đó sao?", "en": "Is that why you like him?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "不只是这样。他不仅能把很难的法律讲清楚，性格也很稳，跟他在一起我很放心。", "p": ["bù", "zhǐ", "shì", "zhè", "yàng", "", "tā", "bù", "jǐn", "néng", "bǎ", "hěn", "nán", "de", "fǎ", "lǜ", "jiǎng", "qīng", "chǔ", "", "xìng", "gé", "yě", "hěn", "wěn", "", "gēn", "tā", "zài", "yì", "qǐ", "wǒ", "hěn", "fàng", "xīn", ""], "vi": "Không chỉ vậy. Anh ấy không những giảng được luật khó một cách rõ ràng, tính cách cũng rất điềm tĩnh, ở bên anh ấy mình cảm thấy yên tâm.", "en": "It's not just that. He can not only explain difficult points of law clearly, he also has a steady character, and I feel at ease with him."}]}, {"n": 2, "zh": "对话：阿玲告诉小雪她准备结婚", "vi": "Hội thoại: A Linh nói với Tiểu Tuyết là mình định kết hôn", "en": "Dialogue: A Linh tells Xiaoxue she plans to get married", "kw": ["开玩笑", "从来", "最好", "共同", "适合", "幸福"], "lines": [{"s": "阿玲", "sp": ["ā", "líng"], "t": "小雪，我想先告诉你一件事：我和周南准备今年冬天结婚。", "p": ["xiǎo", "xuě", "", "wǒ", "xiǎng", "xiān", "gào", "sù", "nǐ", "yí", "jiàn", "shì", "", "wǒ", "hé", "zhōu", "nán", "zhǔn", "bèi", "jīn", "nián", "dōng", "tiān", "jié", "hūn", ""], "vi": "Tiểu Tuyết, mình muốn nói trước với cậu một chuyện: mình và Châu Nam định kết hôn vào mùa đông năm nay.", "en": "Xiaoxue, I want to tell you something first: Zhou Nan and I are planning to get married this winter."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你别开玩笑了！才半年，就谈结婚？", "p": ["nǐ", "bié", "kāi", "wán", "xiào", "le", "", "cái", "bàn", "nián", "", "jiù", "tán", "jié", "hūn", ""], "vi": "Cậu đừng có nói đùa! Mới có nửa năm đã bàn đến chuyện kết hôn?", "en": "Don't joke around! You've only known each other half a year, and you're already talking about marriage?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "我是认真的。认识的时间不长，可我从来没这么确定过。", "p": ["wǒ", "shì", "rèn", "zhēn", "de", "", "rèn", "shí", "de", "shí", "jiān", "bù", "cháng", "", "kě", "wǒ", "cóng", "lái", "méi", "zhè", "me", "què", "dìng", "guò", ""], "vi": "Mình nói nghiêm túc đó. Thời gian quen nhau chưa dài, nhưng mình chưa bao giờ chắc chắn như vậy.", "en": "I'm serious. We haven't known each other long, but I've never been this sure."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "要一起过一辈子，最好先看看有没有共同的习惯，不然以后会很累。", "p": ["yào", "yì", "qǐ", "guò", "yí", "bèi", "zi", "", "zuì", "hǎo", "xiān", "kàn", "kàn", "yǒu", "méi", "yǒu", "gòng", "tóng", "de", "xí", "guàn", "", "bù", "rán", "yǐ", "hòu", "huì", "hěn", "lèi", ""], "vi": "Muốn sống cùng nhau cả đời thì tốt nhất hãy xem đã có những thói quen chung chưa, nếu không sau này sẽ rất mệt.", "en": "If you want to spend a lifetime together, you'd better first see whether you share habits; otherwise it will be tiring later."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "我们都喜欢一大早去湖边走路，也喜欢在旧书店里一站一下午。我觉得我们很适合对方。", "p": ["wǒ", "men", "dōu", "xǐ", "huān", "yí", "dà", "zǎo", "qù", "hú", "biān", "zǒu", "lù", "", "yě", "xǐ", "huān", "zài", "jiù", "shū", "diàn", "lǐ", "yí", "zhàn", "yí", "xià", "wǔ", "", "wǒ", "jué", "de", "wǒ", "men", "hěn", "shì", "hé", "duì", "fāng", ""], "vi": "Bọn mình đều thích sáng sớm ra hồ đi bộ, cũng thích đứng cả buổi chiều trong hiệu sách cũ. Mình thấy hai đứa rất hợp nhau.", "en": "We both like walking by the lake early in the morning, and we can stand in a second-hand bookshop all afternoon. I think we suit each other well."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "听你讲这些，我倒真替你高兴。希望你们一直这么幸福。", "p": ["tīng", "nǐ", "jiǎng", "zhè", "xiē", "", "wǒ", "dào", "zhēn", "tì", "nǐ", "gāo", "xìng", "", "xī", "wàng", "nǐ", "men", "yì", "zhí", "zhè", "me", "xìng", "fú", ""], "vi": "Nghe cậu kể vậy, mình đúng là mừng cho cậu. Mong hai người mãi hạnh phúc như vậy.", "en": "Hearing you say this, I'm genuinely happy for you. I hope you two stay this happy."}]}, {"n": 3, "zh": "对话：林阿姨和赵阿姨聊婚后的日子", "vi": "Hội thoại: Thím Lâm và thím Triệu nói về cuộc sống sau khi cưới", "en": "Dialogue: Aunt Lin and Aunt Zhao talk about married life", "kw": ["生活", "刚", "浪漫", "够", "缺点", "接受"], "lines": [{"s": "林阿姨", "sp": ["lín", "ā", "yí"], "t": "赵阿姨，听说您结婚快十五年了？", "p": ["zhào", "ā", "yí", "", "tīng", "shuō", "nín", "jié", "hūn", "kuài", "shí", "wǔ", "nián", "le", ""], "vi": "Thím Triệu, nghe nói thím kết hôn gần mười lăm năm rồi phải không?", "en": "Aunt Zhao, I heard you've been married for almost fifteen years?"}, {"s": "赵阿姨", "sp": ["zhào", "ā", "yí"], "t": "到春节就满十五年了。这些年生活不算热闹，可一直很踏实。", "p": ["dào", "chūn", "jié", "jiù", "mǎn", "shí", "wǔ", "nián", "le", "", "zhè", "xiē", "nián", "shēng", "huó", "bú", "suàn", "rè", "nao", "", "kě", "yì", "zhí", "hěn", "tā", "shi", ""], "vi": "Đến Tết là tròn mười lăm năm. Mấy năm nay cuộc sống không ồn ào, nhưng luôn rất vững vàng.", "en": "By Spring Festival it will be a full fifteen years. These years our life hasn't been lively, but it has always been steady."}, {"s": "林阿姨", "sp": ["lín", "ā", "yí"], "t": "我刚结婚那两年，周末总想换一条路走走，试试新的小馆。可最近工作一忙，回家只想休息，话也少了。", "p": ["wǒ", "gāng", "jié", "hūn", "nà", "liǎng", "nián", "", "zhōu", "mò", "zǒng", "xiǎng", "huàn", "yì", "tiáo", "lù", "zǒu", "zǒu", "", "shì", "shì", "xīn", "de", "xiǎo", "guǎn", "", "kě", "zuì", "jìn", "gōng", "zuò", "yì", "máng", "", "huí", "jiā", "zhǐ", "xiǎng", "xiū", "xī", "", "huà", "yě", "shǎo", "le", ""], "vi": "Hai năm mình vừa mới cưới, cuối tuần nào cũng muốn đổi đường đi dạo, thử quán nhỏ mới. Nhưng dạo này việc một bận, về nhà chỉ muốn nghỉ, nói chuyện cũng ít đi.", "en": "In the two years after I had just got married, at weekends I always wanted to try a new path for a walk, or a new little restaurant. But lately work has been busy, I only want to rest when I get home, and we talk less."}, {"s": "赵阿姨", "sp": ["zhào", "ā", "yí"], "t": "两个人过日子，不能只靠那一点浪漫，那是不够的。", "p": ["liǎng", "gè", "rén", "guò", "rì", "zi", "", "bù", "néng", "zhǐ", "kào", "nà", "yì", "diǎn", "làng", "màn", "", "nà", "shì", "bú", "gòu", "de", ""], "vi": "Hai người sống với nhau không thể chỉ dựa vào chút lãng mạn ấy, như thế là không đủ.", "en": "When two people share a life, you can't rely on that bit of romance alone — it isn't enough."}, {"s": "林阿姨", "sp": ["lín", "ā", "yí"], "t": "您说得对。我现在有时候会把他的缺点看得很重，然后自己也不痛快。", "p": ["nín", "shuō", "de", "duì", "", "wǒ", "xiàn", "zài", "yǒu", "shí", "hòu", "huì", "bǎ", "tā", "de", "quē", "diǎn", "kàn", "de", "hěn", "zhòng", "", "rán", "hòu", "zì", "jǐ", "yě", "bú", "tòng", "kuai", ""], "vi": "Thím nói đúng. Giờ đôi lúc mình nhìn khuyết điểm của anh ấy quá nặng, rồi bản thân cũng không vui.", "en": "You're right. Sometimes now I dwell on his shortcomings, and then I feel unhappy myself."}, {"s": "赵阿姨", "sp": ["zhào", "ā", "yí"], "t": "一起的时间长了，谁都会有让对方不舒服的地方。接受这些，把日子往平静里过，才会轻松一些。", "p": ["yì", "qǐ", "de", "shí", "jiān", "cháng", "le", "", "shéi", "dōu", "huì", "yǒu", "ràng", "duì", "fāng", "bù", "shū", "fú", "de", "dì", "fāng", "", "jiē", "shòu", "zhè", "xiē", "", "bǎ", "rì", "zi", "wǎng", "píng", "jìng", "lǐ", "guò", "", "cái", "huì", "qīng", "sōng", "yì", "xiē", ""], "vi": "Ở bên nhau lâu, ai cũng có chỗ làm đối phương không dễ chịu. Chấp nhận những điều đó, sống ngày tháng cho bình lặng, sẽ nhẹ nhàng hơn.", "en": "When you've been together a long time, everyone has something that makes the other uncomfortable. Accept that, and live the days more calmly, and it will feel easier."}]}, {"n": 4, "zh": "短文：生活里的小浪漫", "vi": "Đoạn văn: Chút lãng mạn trong đời thường", "en": "Passage: The small romances in everyday life", "kw": ["羡慕", "爱情", "星星", "即使", "加班", "亮", "感动"], "lines": [{"s": "", "sp": [], "t": "很多人羡慕电影里的爱情，总觉得那才够浪漫。可我现在慢慢发现，真正留下来的往往是很小的事。有一次停电，爸爸指着窗外的星星给弟弟讲故事；还有一天，我即使加班到很晚，回到家也还能看见桌上那碗热汤。最让我感动的，是父母晚饭后去散步，路灯已经亮了，他们还是走得很慢，像是要把一天里没说完的话，慢慢补回来。", "p": ["hěn", "duō", "rén", "xiàn", "mù", "diàn", "yǐng", "lǐ", "de", "ài", "qíng", "", "zǒng", "jué", "de", "nà", "cái", "gòu", "làng", "màn", "", "kě", "wǒ", "xiàn", "zài", "màn", "màn", "fā", "xiàn", "", "zhēn", "zhèng", "liú", "xià", "lái", "de", "wǎng", "wǎng", "shì", "hěn", "xiǎo", "de", "shì", "", "yǒu", "yí", "cì", "tíng", "diàn", "", "bà", "bà", "zhǐ", "zhe", "chuāng", "wài", "de", "xīng", "xīng", "gěi", "dì", "di", "jiǎng", "gù", "shì", "", "hái", "yǒu", "yì", "tiān", "", "wǒ", "jí", "shǐ", "jiā", "bān", "dào", "hěn", "wǎn", "", "huí", "dào", "jiā", "yě", "hái", "néng", "kàn", "jiàn", "zhuō", "shàng", "nà", "wǎn", "rè", "tāng", "", "zuì", "ràng", "wǒ", "gǎn", "dòng", "de", "", "shì", "fù", "mǔ", "wǎn", "fàn", "hòu", "qù", "sàn", "bù", "", "lù", "dēng", "yǐ", "jīng", "liàng", "le", "", "tā", "men", "hái", "shì", "zǒu", "de", "hěn", "màn", "", "xiàng", "shì", "yào", "bǎ", "yì", "tiān", "lǐ", "méi", "shuō", "wán", "de", "huà", "", "màn", "màn", "bǔ", "huí", "lái", ""], "vi": "Nhiều người ngưỡng mộ tình yêu trong phim, cứ nghĩ thế mới đủ lãng mạn. Nhưng giờ tôi dần nhận ra, những gì thật sự còn lại thường là chuyện rất nhỏ. Có lần mất điện, bố chỉ lên những ngôi sao ngoài cửa sổ kể chuyện cho em trai; còn có một ngày, dù tôi tăng ca đến rất muộn, về nhà vẫn thấy trên bàn bát canh nóng ấy. Điều khiến tôi cảm động nhất là bố mẹ đi dạo sau bữa tối, đèn đường đã sáng họ vẫn đi rất chậm, như muốn lấy lại những câu cả ngày chưa kịp nói.", "en": "Many people envy the love in films and always feel that is what counts as romance. But I have slowly come to see that what really lasts is often something very small. Once, during a power cut, Dad pointed at the stars outside the window and told my little brother a story; and one day, even though I worked late, I could still see that bowl of hot soup on the table when I got home. What moves me most is my parents' walk after dinner: the street lights are already on, yet they still walk very slowly, as if they want to slowly make up the words they had no time for during the day."}]}, {"n": 5, "zh": "短文：走进婚姻的理由", "vi": "Đoạn văn: Lý do bước vào hôn nhân", "en": "Passage: Reasons for walking into marriage", "kw": ["自然", "原因", "互相", "吸引", "幽默", "脾气"], "lines": [{"s": "", "sp": [], "t": "提起结婚，有人会想得很远，也有人觉得这件事很自然。在我看来，两个人走进婚姻，原因不只是喜欢，还要能在想法上互相吸引。我姐姐的丈夫是中学老师，上课很幽默，学生们都爱听。他脾气很软，家里意见不一样的时候，他总是先听完再慢慢说。看着他们，我才明白，这样的相处，比甜言蜜语更让人放心。", "p": ["tí", "qǐ", "jié", "hūn", "", "yǒu", "rén", "huì", "xiǎng", "de", "hěn", "yuǎn", "", "yě", "yǒu", "rén", "jué", "de", "zhè", "jiàn", "shì", "hěn", "zì", "rán", "", "zài", "wǒ", "kàn", "lái", "", "liǎng", "gè", "rén", "zǒu", "jìn", "hūn", "yīn", "", "yuán", "yīn", "bù", "zhǐ", "shì", "xǐ", "huān", "", "hái", "yào", "néng", "zài", "xiǎng", "fǎ", "shàng", "hù", "xiāng", "xī", "yǐn", "", "wǒ", "jiě", "jiě", "de", "zhàng", "fū", "shì", "zhōng", "xué", "lǎo", "shī", "", "shàng", "kè", "hěn", "yōu", "mò", "", "xué", "shēng", "men", "dōu", "ài", "tīng", "", "tā", "pí", "qì", "hěn", "ruǎn", "", "jiā", "lǐ", "yì", "jiàn", "bù", "yí", "yàng", "de", "shí", "hòu", "", "tā", "zǒng", "shì", "xiān", "tīng", "wán", "zài", "màn", "màn", "shuō", "", "kàn", "zhe", "tā", "men", "", "wǒ", "cái", "míng", "bái", "", "zhè", "yàng", "de", "xiāng", "chǔ", "", "bǐ", "tián", "yán", "mì", "yǔ", "gèng", "ràng", "rén", "fàng", "xīn", ""], "vi": "Nhắc đến kết hôn, có người nghĩ rất xa, cũng có người thấy việc ấy rất tự nhiên. Với tôi, hai người bước vào hôn nhân, lý do không chỉ là thích nhau, mà còn phải thu hút lẫn nhau về mặt suy nghĩ. Chồng chị gái tôi là giáo viên trung học, dạy học rất hài hước, học sinh nào cũng thích nghe. Tính khí anh ấy rất dịu, khi ở nhà có ý kiến khác nhau, anh ấy luôn nghe hết rồi mới nói chậm rãi. Nhìn họ, tôi mới hiểu, cách sống bên nhau như vậy khiến người ta yên tâm hơn những lời đường mật.", "en": "When people mention marriage, some think far ahead, while others feel it is a very natural step. To me, when two people enter marriage, the reason is not only that they like each other — they also need to attract each other in the way they think. My elder sister's husband is a secondary-school teacher. He is very humorous in class, and the students love listening to him. He has a gentle temper: when they disagree at home, he always listens to the end before speaking slowly. Watching them, I finally understand that this way of being together is more reassuring than sweet words."}]}]}, {"l": 2, "texts": [{"n": 1, "zh": "对话：阿玲和阮明聊刚到中国的日子", "vi": "Hội thoại: A Linh và Nguyễn Minh nói về những ngày mới đến Trung Quốc", "en": "Dialogue: A Linh and Nguyen Minh talk about his first days in China", "kw": ["适应", "逛", "交", "平时", "短信", "正好"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "阿玲，新来的同学阮明还习惯这儿吗？", "p": ["ā", "líng", "", "xīn", "lái", "de", "tóng", "xué", "ruǎn", "míng", "hái", "xí", "guàn", "zhè", "r", "ma", ""], "vi": "A Linh, bạn mới Nguyễn Minh đã quen ở đây chưa?", "en": "A Linh, has the new classmate Nguyen Minh got used to it here yet?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "他刚来的那两周，吃饭、坐车都不太适应。后来我带他去交了几个朋友，情况才好起来。", "p": ["tā", "gāng", "lái", "de", "nà", "liǎng", "zhōu", "", "chī", "fàn", "", "zuò", "chē", "dōu", "bú", "tài", "shì", "yìng", "", "hòu", "lái", "wǒ", "dài", "tā", "qù", "jiāo", "le", "jǐ", "gè", "péng", "you", "", "qíng", "kuàng", "cái", "hǎo", "qǐ", "lái", ""], "vi": "Hai tuần đầu anh ấy mới đến, ăn uống và đi xe đều không được thích nghi lắm. Sau đó mình đưa anh ấy đi kết thêm vài người bạn, mọi thứ mới khá hơn.", "en": "In the first two weeks after he arrived, meals and buses were hard to adapt to. Then I took him out to make a few friends, and things got better."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你们平时都做些什么？", "p": ["nǐ", "men", "píng", "shí", "dōu", "zuò", "xiē", "shén", "me", ""], "vi": "Bình thường các bạn làm gì?", "en": "What do you usually do?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "周末我们喜欢去逛附近的小市场，看看水果，听听大家说话。他有问题，也会给我发短信。", "p": ["zhōu", "mò", "wǒ", "men", "xǐ", "huān", "qù", "guàng", "fù", "jìn", "de", "xiǎo", "shì", "chǎng", "", "kàn", "kàn", "shuǐ", "guǒ", "", "tīng", "tīng", "dà", "jiā", "shuō", "huà", "", "tā", "yǒu", "wèn", "tí", "", "yě", "huì", "gěi", "wǒ", "fā", "duǎn", "xìn", ""], "vi": "Cuối tuần bọn mình thích đi dạo chợ nhỏ gần đó, xem trái cây, nghe mọi người nói chuyện. Có việc gì anh ấy cũng nhắn tin cho mình.", "en": "At weekends we like to stroll around the little market nearby, look at the fruit and listen to people talking. If he has a question, he also texts me."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "这个周六正好有个校园音乐会，要不要叫上他？", "p": ["zhè", "ge", "zhōu", "liù", "zhèng", "hǎo", "yǒu", "gè", "xiào", "yuán", "yīn", "yuè", "huì", "", "yào", "bú", "yào", "jiào", "shàng", "tā", ""], "vi": "Thứ bảy này đúng lúc có hòa nhạc trong trường, có gọi anh ấy không?", "en": "There's a campus concert this Saturday, as it happens — shall we ask him along?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "好啊。他正想多认识点儿人，去了一定高兴。", "p": ["hǎo", "a", "", "tā", "zhèng", "xiǎng", "duō", "rèn", "shí", "diǎn", "r", "rén", "", "qù", "le", "yí", "dìng", "gāo", "xìng", ""], "vi": "Được chứ. Anh ấy đang muốn quen thêm người, đi thì chắc vui.", "en": "Yes. He wants to meet more people, so he'll be glad to come."}]}, {"n": 2, "zh": "对话：小雪为同学聚会发愁", "vi": "Hội thoại: Tiểu Tuyết lo chuyện họp lớp", "en": "Dialogue: Xiaoxue worries about a class reunion", "kw": ["聚会", "毕业", "差不多", "联系", "专门", "麻烦"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "阿玲，下个月班里要办一场同学聚会，我有点儿发愁。", "p": ["ā", "líng", "", "xià", "gè", "yuè", "bān", "lǐ", "yào", "bàn", "yì", "cháng", "tóng", "xué", "jù", "huì", "", "wǒ", "yǒu", "diǎn", "r", "fā", "chóu", ""], "vi": "A Linh, tháng sau lớp mình tổ chức họp lớp, mình hơi lo.", "en": "A Linh, the class is holding a reunion next month, and I'm a bit worried."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "发愁什么？大家毕业才差不多一年，应该都还记得路吧？", "p": ["fā", "chóu", "shén", "me", "", "dà", "jiā", "bì", "yè", "cái", "chà", "bu", "duō", "yì", "nián", "", "yīng", "gāi", "dōu", "hái", "jì", "de", "lù", "ba", ""], "vi": "Lo gì? Mọi người tốt nghiệp mới được khoảng một năm, chắc vẫn nhớ đường chứ?", "en": "Why? It's only been about a year since everyone graduated — they should still remember the way, shouldn't they?"}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "问题是有几个人不太好联系。有的换了号码，我专门问了老师，还是没问到。", "p": ["wèn", "tí", "shì", "yǒu", "jǐ", "gè", "rén", "bú", "tài", "hǎo", "lián", "xì", "", "yǒu", "de", "huàn", "le", "hào", "mǎ", "", "wǒ", "zhuān", "mén", "wèn", "le", "lǎo", "shī", "", "hái", "shì", "méi", "wèn", "dào", ""], "vi": "Vấn đề là có vài người khá khó liên lạc. Có người đổi số, mình còn hỏi riêng giáo viên, vẫn chưa ra.", "en": "The problem is that a few people are hard to contact. Some have changed numbers. I even went out of my way to ask the teacher, and I still didn't get them."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "那就先请到的人来。你已经尽力了，别把这件事变成麻烦。", "p": ["nà", "jiù", "xiān", "qǐng", "dào", "de", "rén", "lái", "", "nǐ", "yǐ", "jīng", "jìn", "lì", "le", "", "bié", "bǎ", "zhè", "jiàn", "shì", "biàn", "chéng", "má", "fan", ""], "vi": "Vậy thì mời trước những người liên lạc được. Cậu đã cố rồi, đừng biến việc này thành chuyện phiền phức.", "en": "Then just invite the people you can reach first. You've already tried your best — don't turn it into a hassle."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "说得对。我今晚先把通知发给大家，地点还是那家常去的小馆。", "p": ["shuō", "de", "duì", "", "wǒ", "jīn", "wǎn", "xiān", "bǎ", "tōng", "zhī", "fā", "gěi", "dà", "jiā", "", "dì", "diǎn", "hái", "shì", "nà", "jiā", "cháng", "qù", "de", "xiǎo", "guǎn", ""], "vi": "Đúng đó. Tối nay mình gửi thông báo trước, địa điểm vẫn là quán nhỏ mọi người hay đến.", "en": "That's right. I'll send the notice out tonight. The place can still be that little restaurant we often go to."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "需要我帮忙联系谁，你就说一声。", "p": ["xū", "yào", "wǒ", "bāng", "máng", "lián", "xì", "shuí", "", "nǐ", "jiù", "shuō", "yì", "shēng", ""], "vi": "Cần mình giúp liên lạc ai thì cậu nói một tiếng.", "en": "If you need me to help contact anyone, just say."}]}, {"n": 3, "zh": "对话：阿玲和小雪翻看夏令营的照片", "vi": "Hội thoại: A Linh và Tiểu Tuyết xem ảnh trại hè", "en": "Dialogue: A Linh and Xiaoxue look through summer-camp photos", "kw": ["好像", "重新", "尽管", "真正", "友谊", "当"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你看这张，当我们在山里教孩子们写汉字的时候，你的帽子都歪了。", "p": ["nǐ", "kàn", "zhè", "zhāng", "", "dāng", "wǒ", "men", "zài", "shān", "lǐ", "jiào", "hái", "zi", "men", "xiě", "hàn", "zì", "de", "shí", "hòu", "", "nǐ", "de", "mào", "zi", "dōu", "wāi", "le", ""], "vi": "Cậu nhìn tấm này, khi chúng mình đang dạy bọn trẻ viết chữ Hán trên núi, mũ cậu còn lệch nữa.", "en": "Look at this one — when we were teaching the children to write characters in the mountains, your hat was even crooked."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "真的好像是昨天的事。我倒想重新再去一次，再听他们喊我们“老师”。", "p": ["zhēn", "de", "hǎo", "xiàng", "shì", "zuó", "tiān", "de", "shì", "", "wǒ", "dào", "xiǎng", "chóng", "xīn", "zài", "qù", "yí", "cì", "", "zài", "tīng", "tā", "men", "hǎn", "wǒ", "men", "", "lǎo", "shī", "", ""], "vi": "Thật giống như chuyện hôm qua. Mình lại muốn đi lại một lần nữa, nghe các em gọi mình bằng «cô giáo».", "en": "It really seems like yesterday. I'd love to go again, and hear them call us \"teacher\" once more."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "尽管现在各忙各的，我还是会想起那时大家一起做饭、一起笑的晚上。", "p": ["jǐn", "guǎn", "xiàn", "zài", "gè", "máng", "gè", "de", "", "wǒ", "hái", "shì", "huì", "xiǎng", "qǐ", "nà", "shí", "dà", "jiā", "yì", "qǐ", "zuò", "fàn", "", "yì", "qǐ", "xiào", "de", "wǎn", "shàng", ""], "vi": "Dù giờ ai cũng bận việc của mình, mình vẫn nhớ những tối cả nhóm cùng nấu ăn, cùng cười.", "en": "Even though we're each busy with our own things now, I still think of those evenings when we cooked and laughed together."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "所以我说，真正让人记得住的，不是风景，是那段友谊。", "p": ["suǒ", "yǐ", "wǒ", "shuō", "", "zhēn", "zhèng", "ràng", "rén", "jì", "de", "zhù", "de", "", "bú", "shì", "fēng", "jǐng", "", "shì", "nà", "duàn", "yǒu", "yì", ""], "vi": "Nên mình mới nói, điều thật sự khiến người ta nhớ không phải phong cảnh, mà là tình bạn ấy.", "en": "That's why I say what you really remember isn't the scenery, it's that friendship."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "明年要是再办这样的活动，咱们还去，当一回“大姐姐”。", "p": ["míng", "nián", "yào", "shi", "zài", "bàn", "zhè", "yàng", "de", "huó", "dòng", "", "zán", "men", "hái", "qù", "", "dāng", "yì", "huí", "", "dà", "jiě", "jiě", "", ""], "vi": "Năm sau nếu lại tổ chức hoạt động thế này, mình vẫn đi, làm một chuyến «chị lớn».", "en": "If they run something like this again next year, let's go and be \"big sisters\" once more."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "一言为定。到时候我把这些照片再翻出来给大家看。", "p": ["yī", "yán", "wéi", "dìng", "", "dào", "shí", "hòu", "wǒ", "bǎ", "zhè", "xiē", "zhào", "piān", "zài", "fān", "chū", "lái", "gěi", "dà", "jiā", "kàn", ""], "vi": "Được, nói trước đã. Lúc ấy mình sẽ lại lấy mấy tấm ảnh này ra cho mọi người xem.", "en": "It's a deal. When the time comes, I'll bring these photos out again to show everyone."}]}, {"n": 4, "zh": "短文：宿舍里的那一小时", "vi": "Đoạn văn: Một giờ trong ký túc xá", "en": "Passage: That one hour in the dorm", "kw": ["周围", "交", "丰富", "交流", "讨厌", "无聊", "却"], "lines": [{"s": "", "sp": [], "t": "我刚住进宿舍的时候，周围很安静，晚上只听得见楼下的车。那时我觉得日子有点儿无聊，也讨厌一个人吃饭。后来慢慢交了几个朋友，晚饭后大家坐在走廊里交流家乡的小吃和上课的笑话，晚上忽然变得丰富起来。可我却还给自己留出一小时：关上门，写写日记，听听自己喜欢的歌。有朋友在身边很好，有一段属于自己的时间，也同样重要。", "p": ["wǒ", "gāng", "zhù", "jìn", "sù", "shè", "de", "shí", "hòu", "", "zhōu", "wéi", "hěn", "ān", "jìng", "", "wǎn", "shàng", "zhǐ", "tīng", "de", "jiàn", "lóu", "xià", "de", "chē", "", "nà", "shí", "wǒ", "jué", "de", "rì", "zi", "yǒu", "diǎn", "r", "wú", "liáo", "", "yě", "tǎo", "yàn", "yí", "gè", "rén", "chī", "fàn", "", "hòu", "lái", "màn", "màn", "jiāo", "le", "jǐ", "gè", "péng", "you", "", "wǎn", "fàn", "hòu", "dà", "jiā", "zuò", "zài", "zǒu", "láng", "lǐ", "jiāo", "liú", "jiā", "xiāng", "de", "xiǎo", "chī", "hé", "shàng", "kè", "de", "xiào", "hua", "", "wǎn", "shàng", "hū", "rán", "biàn", "de", "fēng", "fù", "qǐ", "lái", "", "kě", "wǒ", "què", "huán", "gěi", "zì", "jǐ", "liú", "chū", "yì", "xiǎo", "shí", "", "guān", "shàng", "mén", "", "xiě", "xiě", "rì", "jì", "", "tīng", "tīng", "zì", "jǐ", "xǐ", "huān", "de", "gē", "", "yǒu", "péng", "you", "zài", "shēn", "biān", "hěn", "hǎo", "", "yǒu", "yí", "duàn", "shǔ", "yú", "zì", "jǐ", "de", "shí", "jiān", "", "yě", "tóng", "yàng", "zhòng", "yào", ""], "vi": "Lúc mới ở ký túc xá, xung quanh rất yên, tối chỉ nghe tiếng xe dưới phố. Khi ấy tôi thấy ngày tháng hơi buồn chán, cũng ghét phải ăn một mình. Sau dần kết được vài người bạn, sau bữa tối cả nhóm ngồi ở hành lang trao đổi về món quê và chuyện vui trên lớp, buổi tối bỗng trở nên phong phú. Thế nhưng tôi vẫn để dành cho mình một giờ: đóng cửa, viết nhật ký, nghe bài mình thích. Có bạn bên cạnh thì tốt, có một khoảng thời gian thuộc về mình cũng quan trọng không kém.", "en": "When I first moved into the dorm, it was very quiet around me; at night I could only hear the cars downstairs. In those days I found life a bit dull, and I also hated eating alone. Later I slowly made a few friends. After dinner we would sit in the corridor and talk about hometown snacks and jokes from class, and the evenings suddenly became rich. And yet I still keep one hour for myself: I close the door, write in my diary, and listen to a song I like. It is good to have friends nearby, and a stretch of time that belongs only to you is just as important."}]}, {"n": 5, "zh": "短文：朋友不是只会说好话的人", "vi": "Đoạn văn: Bạn không phải chỉ biết nói lời hay", "en": "Passage: A friend is not only someone who says nice things", "kw": ["镜子", "理解", "困难", "及时", "陪", "而", "真正"], "lines": [{"s": "", "sp": [], "t": "有人把朋友比作镜子，觉得镜子里只会看见自己最好看的样子。可我想，真正的朋友更像一扇窗。当你遇到困难，他能理解你为什么走不动，也会及时过来敲敲门，陪你把心里的话说完。他高兴时会和你一起笑，而在你不想说话的时候，也愿意安静地坐在旁边。这样的人不必很多，但有一个，就够让人觉得自己不是一个人。", "p": ["yǒu", "rén", "bǎ", "péng", "you", "bǐ", "zuò", "jìng", "zi", "", "jué", "de", "jìng", "zi", "lǐ", "zhǐ", "huì", "kàn", "jiàn", "zì", "jǐ", "zuì", "hǎo", "kàn", "de", "yàng", "zi", "", "kě", "wǒ", "xiǎng", "", "zhēn", "zhèng", "de", "péng", "you", "gèng", "xiàng", "yí", "shàn", "chuāng", "", "dāng", "nǐ", "yù", "dào", "kùn", "nan", "", "tā", "néng", "lǐ", "jiě", "nǐ", "wèi", "shén", "me", "zǒu", "bú", "dòng", "", "yě", "huì", "jí", "shí", "guò", "lái", "qiāo", "qiāo", "mén", "", "péi", "nǐ", "bǎ", "xīn", "lǐ", "de", "huà", "shuō", "wán", "", "tā", "gāo", "xìng", "shí", "huì", "hé", "nǐ", "yì", "qǐ", "xiào", "", "ér", "zài", "nǐ", "bù", "xiǎng", "shuō", "huà", "de", "shí", "hòu", "", "yě", "yuàn", "yì", "ān", "jìng", "dì", "zuò", "zài", "páng", "biān", "", "zhè", "yàng", "de", "rén", "bú", "bì", "hěn", "duō", "", "dàn", "yǒu", "yí", "gè", "", "jiù", "gòu", "ràng", "rén", "jué", "de", "zì", "jǐ", "bú", "shì", "yí", "gè", "rén", ""], "vi": "Có người ví bạn bè như tấm gương, cho rằng trong gương chỉ thấy mình ở kiểu đẹp nhất. Nhưng tôi nghĩ, người bạn thật sự hơn giống một ô cửa sổ. Khi bạn gặp khó khăn, người ấy hiểu vì sao bạn bước không nổi, cũng kịp thời đến gõ cửa, ở bên để bạn nói hết những điều trong lòng. Lúc vui họ cười cùng bạn, còn khi bạn không muốn nói, họ cũng sẵn sàng ngồi yên cạnh đó. Người như vậy không cần nhiều, nhưng có một người thôi, cũng đủ để thấy mình không cô độc.", "en": "Some people compare a friend to a mirror, and feel that a mirror only shows you at your best. But I think a true friend is more like a window. When you run into difficulties, they can understand why you can't go on, and they will also come and knock in time, and sit with you until you've said what's on your mind. They will laugh with you when they're happy, and when you don't feel like talking, they are also willing to sit quietly beside you. You don't need many people like that, but even one is enough to make you feel you are not alone."}]}]}, {"l": 3, "texts": [{"n": 1, "zh": "对话：阿玲面试前有点儿紧张", "vi": "Hội thoại: A Linh hơi hồi hộp trước buổi phỏng vấn", "en": "Dialogue: A Linh is a little nervous before her interview", "kw": ["紧张", "能力", "提供", "信心", "招聘", "挺"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "明天那家语言中心招聘辅导老师，你还去吗？", "p": ["míng", "tiān", "nà", "jiā", "yǔ", "yán", "zhōng", "xīn", "zhāo", "pìn", "fǔ", "dǎo", "lǎo", "shī", "", "nǐ", "hái", "qù", "ma", ""], "vi": "Ngày mai trung tâm ngôn ngữ ấy tuyển giáo viên kèm, cậu vẫn đi chứ?", "en": "That language centre is recruiting tutors tomorrow — are you still going?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "去。可我一想到要开口介绍自己，就有点儿紧张。", "p": ["qù", "", "kě", "wǒ", "yì", "xiǎng", "dào", "yào", "kāi", "kǒu", "jiè", "shào", "zì", "jǐ", "", "jiù", "yǒu", "diǎn", "r", "jǐn", "zhāng", ""], "vi": "Đi chứ. Nhưng nghĩ đến lúc phải mở miệng giới thiệu mình là mình hơi hồi hộp.", "en": "Yes. But as soon as I think about having to introduce myself, I get a little nervous."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "他们要看的是你的能力，不是你讲得漂不漂亮。你带学生复习，一向很清楚。", "p": ["tā", "men", "yào", "kàn", "de", "shì", "nǐ", "de", "néng", "lì", "", "bú", "shì", "nǐ", "jiǎng", "de", "piāo", "bú", "piào", "liàng", "", "nǐ", "dài", "xué", "shēng", "fù", "xí", "", "yí", "xiàng", "hěn", "qīng", "chǔ", ""], "vi": "Họ nhìn năng lực của cậu, không phải nói hay hay không. Cậu kèm các bạn ôn bài vốn rất rõ ràng.", "en": "They'll be looking at your ability, not at how pretty your speech is. You're always very clear when you review with students."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "通知上说，他们会提供一周的培训。有培训，我心里才有信心一点儿。", "p": ["tōng", "zhī", "shàng", "shuō", "", "tā", "men", "huì", "tí", "gōng", "yì", "zhōu", "de", "péi", "xùn", "", "yǒu", "péi", "xùn", "", "wǒ", "xīn", "lǐ", "cái", "yǒu", "xìn", "xīn", "yì", "diǎn", "r", ""], "vi": "Trong giấy báo nói họ sẽ cung cấp một tuần tập huấn. Có tập huấn, mình mới có chút tự tin.", "en": "The notice said they would provide a week of training. With that, I feel a bit more confident."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "那就好好睡一觉。我看你挺适合这份工作的。", "p": ["nà", "jiù", "hǎo", "hǎo", "shuì", "yí", "jiào", "", "wǒ", "kàn", "nǐ", "tǐng", "shì", "hé", "zhè", "fèn", "gōng", "zuò", "de", ""], "vi": "Vậy thì ngủ một giấc cho ngon. Mình thấy cậu khá hợp với việc này.", "en": "Then get a good night's sleep. I think you're quite right for this job."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "好。明天我一出来，就给你发消息。", "p": ["hǎo", "", "míng", "tiān", "wǒ", "yì", "chū", "lái", "", "jiù", "gěi", "nǐ", "fā", "xiāo", "xi", ""], "vi": "Được. Ngày mai ra xong mình nhắn ngay cho cậu.", "en": "All right. I'll message you as soon as I come out tomorrow."}]}, {"n": 2, "zh": "对话：周姐和阿玲谈两份应聘材料", "vi": "Hội thoại: Chị Châu và A Linh bàn hai hồ sơ ứng tuyển", "en": "Dialogue: Sister Zhou and A Linh discuss two applications", "kw": ["本来", "材料", "符合", "负责", "通知", "应聘"], "lines": [{"s": "周姐", "sp": ["zhōu", "jiě"], "t": "阿玲，你帮我看看这两份应聘材料。前台这份工作，本来我们想找有经验的人。", "p": ["ā", "líng", "", "nǐ", "bāng", "wǒ", "kàn", "kàn", "zhè", "liǎng", "fèn", "yìng", "pìn", "cái", "liào", "", "qián", "tái", "zhè", "fèn", "gōng", "zuò", "", "běn", "lái", "wǒ", "men", "xiǎng", "zhǎo", "yǒu", "jīng", "yàn", "de", "rén", ""], "vi": "A Linh, em xem giúp chị hai hồ sơ ứng tuyển này. Việc lễ tân này, vốn dĩ chị muốn tìm người có kinh nghiệm.", "en": "A Linh, help me look at these two job applications. For this front-desk job, we originally wanted someone with experience."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "这份更符合要求：字写得清楚，也写过类似的工作。那一份经验少一些。", "p": ["zhè", "fèn", "gèng", "fú", "hé", "yāo", "qiú", "", "zì", "xiě", "de", "qīng", "chǔ", "", "yě", "xiě", "guò", "lèi", "sì", "de", "gōng", "zuò", "", "nà", "yí", "fèn", "jīng", "yàn", "shǎo", "yì", "xiē", ""], "vi": "Hồ sơ này hợp yêu cầu hơn: chữ viết rõ, cũng từng làm việc tương tự. Hồ sơ kia ít kinh nghiệm hơn.", "en": "This one fits the requirements better: the writing is clear, and they've done similar work. The other one has a little less experience."}, {"s": "周姐", "sp": ["zhōu", "jiě"], "t": "那我先通知第一位下周三来见面。来了以后，前台就由她负责试做一天。", "p": ["nà", "wǒ", "xiān", "tōng", "zhī", "dì", "yī", "wèi", "xià", "zhōu", "sān", "lái", "jiàn", "miàn", "", "lái", "le", "yǐ", "hòu", "", "qián", "tái", "jiù", "yóu", "tā", "fù", "zé", "shì", "zuò", "yì", "tiān", ""], "vi": "Vậy chị báo trước cho người thứ nhất thứ tư tuần sau đến gặp. Đến rồi thì để bạn ấy phụ trách lễ tân thử một ngày.", "en": "Then I'll notify the first person to come in next Wednesday. Once they're here, they can be responsible for the front desk on a one-day trial."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "要是她那天来不了呢？", "p": ["yào", "shi", "tā", "nà", "tiān", "lái", "bù", "liǎo", "ne", ""], "vi": "Nếu hôm đó bạn ấy không đến được thì sao?", "en": "What if she can't come that day?"}, {"s": "周姐", "sp": ["zhōu", "jiě"], "t": "再联系第二位。招聘不宜拖太久，咱们尽快定下来。", "p": ["zài", "lián", "xì", "dì", "èr", "wèi", "", "zhāo", "pìn", "bù", "yí", "tuō", "tài", "jiǔ", "", "zán", "men", "jǐn", "kuài", "dìng", "xià", "lái", ""], "vi": "Thì liên lạc người thứ hai. Việc tuyển dụng không nên kéo dài, mình quyết sớm thôi.", "en": "Then we'll contact the second one. We shouldn't let the hiring drag on — let's decide as soon as we can."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "好，我把时间记在本子上。", "p": ["hǎo", "", "wǒ", "bǎ", "shí", "jiān", "jì", "zài", "běn", "zi", "shàng", ""], "vi": "Được, em ghi thời gian vào sổ.", "en": "All right, I'll write the time down in the notebook."}]}, {"n": 3, "zh": "对话：陈晓跟阿玲说她的新工作", "vi": "Hội thoại: Trần Hiểu kể với A Linh về việc mới", "en": "Dialogue: Chen Xiao tells A Linh about her new job", "kw": ["安排", "另外", "律师", "收入", "咱们", "专业"], "lines": [{"s": "陈晓", "sp": ["chén", "xiǎo"], "t": "阿玲，我找到工作了，在一家律师事务所做助理。", "p": ["ā", "líng", "", "wǒ", "zhǎo", "dào", "gōng", "zuò", "le", "", "zài", "yì", "jiā", "lǜ", "shī", "shì", "wù", "suǒ", "zuò", "zhù", "lǐ", ""], "vi": "A Linh, mình tìm được việc rồi, làm trợ lý ở một văn phòng luật sư.", "en": "A Linh, I've found a job — as an assistant at a law firm."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "真好！你的专业就是法律，这不是正好用上了吗？", "p": ["zhēn", "hǎo", "", "nǐ", "de", "zhuān", "yè", "jiù", "shì", "fǎ", "lǜ", "", "zhè", "bú", "shì", "zhèng", "hǎo", "yòng", "shàng", "le", "ma", ""], "vi": "Hay quá! Chuyên ngành cậu là luật, thế thì chẳng đúng lúc dùng được sao?", "en": "That's wonderful! Your major is law — isn't that just the right use for it?"}, {"s": "陈晓", "sp": ["chén", "xiǎo"], "t": "对。收入不算特别高，可每个月都很稳定。另外，晚上还能继续上课。", "p": ["duì", "", "shōu", "rù", "bú", "suàn", "tè", "bié", "gāo", "", "kě", "měi", "gè", "yuè", "dōu", "hěn", "wěn", "dìng", "", "lìng", "wài", "", "wǎn", "shàng", "hái", "néng", "jì", "xù", "shàng", "kè", ""], "vi": "Đúng. Thu nhập không đặc biệt cao, nhưng tháng nào cũng ổn định. Ngoài ra, tối vẫn học tiếp được.", "en": "Yes. The income isn't especially high, but it's steady every month. Besides that, I can still go to class in the evenings."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "那时间够用吗？咱们以前晚上常一起去图书馆。", "p": ["nà", "shí", "jiān", "gòu", "yòng", "ma", "", "zán", "men", "yǐ", "qián", "wǎn", "shàng", "cháng", "yì", "qǐ", "qù", "tú", "shū", "guǎn", ""], "vi": "Vậy thời gian có đủ không? Trước giờ tối nào mình cũng hay cùng đi thư viện.", "en": "Will you have enough time? We used to go to the library together in the evenings."}, {"s": "陈晓", "sp": ["chén", "xiǎo"], "t": "我自己先把一周的安排写好。忙的那几天，可能只能周末再见了。", "p": ["wǒ", "zì", "jǐ", "xiān", "bǎ", "yì", "zhōu", "de", "ān", "pái", "xiě", "hǎo", "", "máng", "de", "nà", "jǐ", "tiān", "", "kě", "néng", "zhǐ", "néng", "zhōu", "mò", "zài", "jiàn", "le", ""], "vi": "Mình sẽ viết sẵn lịch một tuần. Những ngày bận, có lẽ chỉ cuối tuần mới gặp được.", "en": "I'll write out the week's schedule first. On the busy days, we may only be able to meet at the weekend."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "没关系。你先安顿好，我为你高兴。", "p": ["méi", "guān", "xì", "", "nǐ", "xiān", "ān", "dùn", "hǎo", "", "wǒ", "wèi", "nǐ", "gāo", "xìng", ""], "vi": "Không sao. Cậu an vị đã, mình mừng cho cậu.", "en": "That's all right. Get yourself settled first — I'm happy for you."}]}, {"n": 4, "zh": "短文：面试时我想着的两件事", "vi": "Đoạn văn: Hai điều tôi nhớ khi phỏng vấn", "en": "Passage: Two things I keep in mind in an interview", "kw": ["首先", "其次", "诚实", "正式", "留"], "lines": [{"s": "", "sp": [], "t": "第一次去参加正式面试的时候，我在门口站了很久。后来我只记住两件事。首先，要诚实：不会的不要装会，被问到也可以说“我想再学”。其次，要认真听完再回答，不要抢话。衣服不必很贵，但要干净、整齐。走出门的时候我还是有些不好意思，可我希望自己至少留下了一个清楚、认真的印象。", "p": ["dì", "yī", "cì", "qù", "cān", "jiā", "zhèng", "shì", "miàn", "shì", "de", "shí", "hòu", "", "wǒ", "zài", "mén", "kǒu", "zhàn", "le", "hěn", "jiǔ", "", "hòu", "lái", "wǒ", "zhǐ", "jì", "zhù", "liǎng", "jiàn", "shì", "", "shǒu", "xiān", "", "yào", "chéng", "shí", "", "bú", "huì", "de", "bú", "yào", "zhuāng", "huì", "", "bèi", "wèn", "dào", "yě", "kě", "yǐ", "shuō", "", "wǒ", "xiǎng", "zài", "xué", "", "", "qí", "cì", "", "yào", "rèn", "zhēn", "tīng", "wán", "zài", "huí", "dá", "", "bú", "yào", "qiǎng", "huà", "", "yī", "fú", "bú", "bì", "hěn", "guì", "", "dàn", "yào", "gān", "jìng", "", "zhěng", "qí", "", "zǒu", "chū", "mén", "de", "shí", "hòu", "wǒ", "hái", "shì", "yǒu", "xiē", "bù", "hǎo", "yì", "sī", "", "kě", "wǒ", "xī", "wàng", "zì", "jǐ", "zhì", "shǎo", "liú", "xià", "le", "yí", "gè", "qīng", "chǔ", "", "rèn", "zhēn", "de", "yìn", "xiàng", ""], "vi": "Lần đầu đi phỏng vấn chính thức, tôi đứng mãi ở cửa. Sau đó tôi chỉ nhớ hai điều. Trước hết, phải thành thật: không biết thì đừng giả vờ biết, bị hỏi cũng có thể nói «tôi muốn học thêm». Thứ hai, phải nghe hết rồi mới trả lời, đừng cướp lời. Áo quần không cần đắt, nhưng phải sạch và gọn. Lúc bước ra tôi vẫn hơi ngại, nhưng mong ít nhất mình đã để lại một ấn tượng rõ ràng, nghiêm túc.", "en": "The first time I went to a formal interview, I stood at the door for a long time. After that I only kept two things in mind. First, be honest: if you can't do something, don't pretend you can, and if you're asked, you can also say \"I'd like to learn more.\" Second, listen to the end before you answer, and don't interrupt. Your clothes don't have to be expensive, but they should be clean and tidy. I was still a little embarrassed when I walked out, but I hoped I had at least left a clear, careful impression."}]}, {"n": 5, "zh": "短文：把约定的时间放在心里", "vi": "Đoạn văn: Để thời gian đã hẹn trong lòng", "en": "Passage: Keep the appointed time in mind", "kw": ["不管", "改变", "感觉", "顾客", "判断", "约会", "准时", "与"], "lines": [{"s": "", "sp": [], "t": "我在一家小咖啡馆打工。每天要与顾客说话，先判断他们是想坐一下，还是打包就走，再按他们的需要去做。不管店里有多忙，我都提醒自己不要改变脸上的态度。有一次，一位老师与我约好下午三点来取蛋糕，那是我们的一次约会。我提前做好，准时放到柜台上。她进门时笑着说：“我就知道你们不会让人白等。”那句话让我感觉，准时其实是一种尊重。", "p": ["wǒ", "zài", "yì", "jiā", "xiǎo", "kā", "fēi", "guǎn", "dǎ", "gōng", "", "měi", "tiān", "yào", "yǔ", "gù", "kè", "shuō", "huà", "", "xiān", "pàn", "duàn", "tā", "men", "shì", "xiǎng", "zuò", "yí", "xià", "", "hái", "shì", "dǎ", "bāo", "jiù", "zǒu", "", "zài", "àn", "tā", "men", "de", "xū", "yào", "qù", "zuò", "", "bù", "guǎn", "diàn", "lǐ", "yǒu", "duō", "máng", "", "wǒ", "dōu", "tí", "xǐng", "zì", "jǐ", "bú", "yào", "gǎi", "biàn", "liǎn", "shàng", "de", "tài", "dù", "", "yǒu", "yí", "cì", "", "yí", "wèi", "lǎo", "shī", "yǔ", "wǒ", "yuē", "hǎo", "xià", "wǔ", "sān", "diǎn", "lái", "qǔ", "dàn", "gāo", "", "nà", "shì", "wǒ", "men", "de", "yí", "cì", "yuē", "huì", "", "wǒ", "tí", "qián", "zuò", "hǎo", "", "zhǔn", "shí", "fàng", "dào", "guì", "tái", "shàng", "", "tā", "jìn", "mén", "shí", "xiào", "zhe", "shuō", "", "", "wǒ", "jiù", "zhī", "dào", "nǐ", "men", "bú", "huì", "ràng", "rén", "bái", "děng", "", "", "nà", "jù", "huà", "ràng", "wǒ", "gǎn", "jué", "", "zhǔn", "shí", "qí", "shí", "shì", "yì", "zhǒng", "zūn", "zhòng", ""], "vi": "Tôi làm thêm ở một quán cà phê nhỏ. Mỗi ngày phải nói chuyện với khách, trước hết phán đoán họ muốn ngồi một chút hay lấy mang về, rồi làm theo nhu cầu của họ. Dù trong quán bận đến mấy, tôi cũng nhắc mình đừng đổi thái độ trên mặt. Có lần một cô giáo hẹn với tôi chiều ba giờ đến lấy bánh, đó là một cuộc hẹn của chúng tôi. Tôi làm sẵn, đúng giờ đặt lên quầy. Cô bước vào, cười nói: «Tôi biết các bạn sẽ không để người ta đợi phí.» Câu ấy khiến tôi cảm thấy, đúng giờ thật ra là một cách tôn trọng.", "en": "I work part-time in a little café. Every day I have to talk with the customers, first judge whether they want to sit for a moment or take their order away, and then do what they need. No matter how busy the shop is, I remind myself not to change the look on my face. Once a teacher arranged with me to pick up a cake at three in the afternoon — that was an appointment we had. I had it ready and put it on the counter on time. When she came in she smiled and said, \"I knew you wouldn't leave anyone waiting for nothing.\" That sentence made me feel that being on time is really a kind of respect."}]}]}, {"l": 4, "texts": [{"n": 1, "zh": "对话：小雪又想换工作", "vi": "Hội thoại: Tiểu Tuyết lại muốn đổi việc", "en": "Dialogue: Xiaoxue wants to change jobs again", "kw": ["完全", "以为", "份", "提", "赚"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "阿玲，我又想提换工作的事了。这份工作做了半年，我以为能学到很多，结果每天都差不多。", "p": ["ā", "líng", "", "wǒ", "yòu", "xiǎng", "tí", "huàn", "gōng", "zuò", "de", "shì", "le", "", "zhè", "fèn", "gōng", "zuò", "zuò", "le", "bàn", "nián", "", "wǒ", "yǐ", "wéi", "néng", "xué", "dào", "hěn", "duō", "", "jié", "guǒ", "měi", "tiān", "dōu", "chà", "bu", "duō", ""], "vi": "A Linh, mình lại muốn nêu chuyện đổi việc. Việc này làm đã nửa năm, mình tưởng học được nhiều, hóa ra ngày nào cũng gần như nhau.", "en": "A Linh, I want to bring up changing jobs again. I've done this job for half a year. I thought I would learn a lot, but every day is more or less the same."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "你不是才涨了一点儿工资吗？别完全否定它。", "p": ["nǐ", "bú", "shì", "cái", "zhǎng", "le", "yì", "diǎn", "r", "gōng", "zī", "ma", "", "bié", "wán", "quán", "fǒu", "dìng", "tā", ""], "vi": "Chẳng phải cậu vừa được tăng một chút lương sao? Đừng phủ nhận hoàn toàn.", "en": "Didn't you just get a small raise? Don't dismiss it completely."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "涨是涨了，可我看同学做别的，好像赚得更多。", "p": ["zhǎng", "shì", "zhǎng", "le", "", "kě", "wǒ", "kàn", "tóng", "xué", "zuò", "bié", "de", "", "hǎo", "xiàng", "zhuàn", "de", "gèng", "duō", ""], "vi": "Tăng thì có tăng, nhưng mình thấy bạn cùng lớp làm việc khác, hình như kiếm được nhiều hơn.", "en": "The raise happened, yes, but I see classmates in other jobs who seem to earn more."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "赚钱很重要，可一份工作好不好，不能只看这个月的数字。", "p": ["zhuàn", "qián", "hěn", "zhòng", "yào", "", "kě", "yí", "fèn", "gōng", "zuò", "hǎo", "bù", "hǎo", "", "bù", "néng", "zhǐ", "kàn", "zhè", "ge", "yuè", "de", "shù", "zì", ""], "vi": "Kiếm tiền thì quan trọng, nhưng một công việc có tốt hay không không thể chỉ nhìn con số tháng này.", "en": "Earning money is important, but whether a job is good or not can't be judged only by this month's number."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "那你说我该等等？", "p": ["nà", "nǐ", "shuō", "wǒ", "gāi", "děng", "děng", ""], "vi": "Vậy cậu bảo mình nên đợi thêm?", "en": "So you think I should wait a little longer?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "先把现在手边的事做好。真要走，也先想清楚下一份是什么，再提离开。", "p": ["xiān", "bǎ", "xiàn", "zài", "shǒu", "biān", "de", "shì", "zuò", "hǎo", "", "zhēn", "yào", "zǒu", "", "yě", "xiān", "xiǎng", "qīng", "chǔ", "xià", "yí", "fèn", "shì", "shén", "me", "", "zài", "tí", "lí", "kāi", ""], "vi": "Hãy làm tốt việc đang có đã. Thật sự muốn đi, cũng nghĩ rõ việc tiếp theo là gì rồi hãy nói đến chuyện rời đi.", "en": "Do the work in front of you well first. If you really want to leave, think clearly about what the next job is before you bring up going."}]}, {"n": 2, "zh": "对话：林主管请小雪把调查提前做完", "vi": "Hội thoại: Chủ quản Lâm nhờ Tiểu Tuyết hoàn thành khảo sát sớm", "en": "Dialogue: Supervisor Lin asks Xiaoxue to finish a survey early", "kw": ["保证", "调查", "计划", "提前", "提醒", "原来", "乱"], "lines": [{"s": "林主管", "sp": ["lín", "zhǔ", "guǎn"], "t": "小雪，上周那份调查，计划是这周五交。现在要提前到周三，你能保证完成吗？", "p": ["xiǎo", "xuě", "", "shàng", "zhōu", "nà", "fèn", "diào", "chá", "", "jì", "huà", "shì", "zhè", "zhōu", "wǔ", "jiāo", "", "xiàn", "zài", "yào", "tí", "qián", "dào", "zhōu", "sān", "", "nǐ", "néng", "bǎo", "zhèng", "wán", "chéng", "ma", ""], "vi": "Tiểu Tuyết, bản khảo sát tuần trước, kế hoạch là nộp thứ sáu này. Giờ phải làm sớm hơn vào thứ tư, em bảo đảm hoàn thành được không?", "en": "Xiaoxue, for that survey from last week, the plan was to hand it in this Friday. Now it has to be earlier, by Wednesday — can you guarantee you'll finish it?"}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "周三……时间是紧了些。我先把这几天的安排重新看一遍，免得改乱了。", "p": ["zhōu", "sān", "", "", "shí", "jiān", "shì", "jǐn", "le", "xiē", "", "wǒ", "xiān", "bǎ", "zhè", "jǐ", "tiān", "de", "ān", "pái", "chóng", "xīn", "kàn", "yí", "biàn", "", "miǎn", "de", "gǎi", "luàn", "le", ""], "vi": "Thứ tư… thời gian hơi căng. Em xem lại lịch mấy ngày này đã, để khỏi sửa cho rối.", "en": "Wednesday… that's a bit tight. I'll go through these days' schedule again first, so it doesn't get into a mess."}, {"s": "林主管", "sp": ["lín", "zhǔ", "guǎn"], "t": "原来截止日期改了，是因为后面还有一场会。我明天再提醒你一次。", "p": ["yuán", "lái", "jié", "zhǐ", "rì", "qī", "gǎi", "le", "", "shì", "yīn", "wèi", "hòu", "miàn", "hái", "yǒu", "yì", "cháng", "huì", "", "wǒ", "míng", "tiān", "zài", "tí", "xǐng", "nǐ", "yí", "cì", ""], "vi": "Hóa ra hạn chót đổi vì phía sau còn một cuộc họp. Ngày mai chị nhắc em thêm lần nữa.", "en": "It turns out the deadline was changed because there's a meeting after that. I'll remind you again tomorrow."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "好。今晚我先做完前半部分，明天一早就把后半部分接着做。", "p": ["hǎo", "", "jīn", "wǎn", "wǒ", "xiān", "zuò", "wán", "qián", "bàn", "bù", "fen", "", "míng", "tiān", "yì", "zǎo", "jiù", "bǎ", "hòu", "bàn", "bù", "fen", "jiē", "zhe", "zuò", ""], "vi": "Được. Tối nay em làm xong nửa đầu, sáng mai làm tiếp nửa sau.", "en": "All right. I'll finish the first half tonight, and carry on with the second half first thing tomorrow."}, {"s": "林主管", "sp": ["lín", "zhǔ", "guǎn"], "t": "有困难早点说，不要拖到最后。", "p": ["yǒu", "kùn", "nan", "zǎo", "diǎn", "shuō", "", "bú", "yào", "tuō", "dào", "zuì", "hòu", ""], "vi": "Có khó thì nói sớm, đừng để đến phút cuối.", "en": "If there's a difficulty, say so early — don't leave it until the last minute."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "知道了。我尽量在周二晚上给您。", "p": ["zhī", "dào", "le", "", "wǒ", "jǐn", "liàng", "zài", "zhōu", "èr", "wǎn", "shàng", "gěi", "nín", ""], "vi": "Em biết rồi. Em cố đưa chị vào tối thứ ba.", "en": "Understood. I'll try to get it to you by Tuesday evening."}]}, {"n": 3, "zh": "对话：赵叔叔跟阿玲谈做小生意", "vi": "Hội thoại: Chú Triệu nói với A Linh về làm ăn nhỏ", "en": "Dialogue: Uncle Zhao talks with A Linh about a small business", "kw": ["积累", "经验", "生意", "一切", "谈"], "lines": [{"s": "阿玲", "sp": ["ā", "líng"], "t": "赵叔叔，听说您在社区开了一家小文具店？", "p": ["zhào", "shū", "shu", "", "tīng", "shuō", "nín", "zài", "shè", "qū", "kāi", "le", "yì", "jiā", "xiǎo", "wén", "jù", "diàn", ""], "vi": "Chú Triệu, nghe nói chú mở một tiệm văn phòng phẩm nhỏ trong khu?", "en": "Uncle Zhao, I heard you opened a little stationery shop in the neighbourhood?"}, {"s": "赵叔叔", "sp": ["zhào", "shū", "shu"], "t": "是啊。说起来是生意，其实刚开头那几个月，一切都比我想的慢。", "p": ["shì", "a", "", "shuō", "qǐ", "lái", "shì", "shēng", "yi", "", "qí", "shí", "gāng", "kāi", "tóu", "nà", "jǐ", "gè", "yuè", "", "yí", "qiè", "dōu", "bǐ", "wǒ", "xiǎng", "de", "màn", ""], "vi": "Phải. Nói là làm ăn, nhưng mấy tháng đầu mọi thứ đều chậm hơn chú nghĩ.", "en": "That's right. You can call it a business, but in those first few months everything was slower than I had expected."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "您以前不是做过老师吗？开店跟教书差很多吧？", "p": ["nín", "yǐ", "qián", "bú", "shì", "zuò", "guò", "lǎo", "shī", "ma", "", "kāi", "diàn", "gēn", "jiāo", "shū", "chà", "hěn", "duō", "ba", ""], "vi": "Trước chú chẳng phải làm giáo viên sao? Mở tiệm khác dạy học nhiều chứ?", "en": "Weren't you a teacher before? Running a shop must be very different from teaching, surely?"}, {"s": "赵叔叔", "sp": ["zhào", "shū", "shu"], "t": "差很多。不过以前带学生，也让我积累了一些与人谈话的经验。客人来谈需要，我能听得比较耐心。", "p": ["chà", "hěn", "duō", "", "bú", "guò", "yǐ", "qián", "dài", "xué", "shēng", "", "yě", "ràng", "wǒ", "jī", "lěi", "le", "yì", "xiē", "yǔ", "rén", "tán", "huà", "de", "jīng", "yàn", "", "kè", "rén", "lái", "tán", "xū", "yào", "", "wǒ", "néng", "tīng", "de", "bǐ", "jiào", "nài", "xīn", ""], "vi": "Khác nhiều. Nhưng trước dẫn học sinh cũng giúp chú tích lũy ít kinh nghiệm nói chuyện với người. Khách đến bàn nhu cầu, chú nghe được kiên nhẫn hơn.", "en": "Very different. But taking students before also helped me build up some experience of talking with people. When customers come to discuss what they need, I can listen more patiently."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "那现在好一些了吗？", "p": ["nà", "xiàn", "zài", "hǎo", "yì", "xiē", "le", "ma", ""], "vi": "Vậy giờ đã khá hơn chưa?", "en": "Is it any better now?"}, {"s": "赵叔叔", "sp": ["zhào", "shū", "shu"], "t": "慢慢好了。别急着看这个月赚多少，先把店里的事一件一件做稳。", "p": ["màn", "màn", "hǎo", "le", "", "bié", "jí", "zhe", "kàn", "zhè", "ge", "yuè", "zhuàn", "duō", "shǎo", "", "xiān", "bǎ", "diàn", "lǐ", "de", "shì", "yí", "jiàn", "yí", "jiàn", "zuò", "wěn", ""], "vi": "Dần khá rồi. Đừng vội nhìn tháng này kiếm được bao nhiêu, hãy làm vững từng việc trong tiệm đã.", "en": "It's slowly getting better. Don't be in a hurry to look at how much this month earns — first get each thing in the shop on a steady footing."}]}, {"n": 4, "zh": "短文：一条让人放心的消息", "vi": "Đoạn văn: Một tin khiến người ta yên tâm", "en": "Passage: A piece of news that puts people at ease", "kw": ["按时", "按照", "成功", "感谢", "奖金", "顺利", "消息"], "lines": [{"s": "", "sp": [], "t": "今年部门的工作进行得很顺利。大家按照年初写好的计划，一件一件按时做完，最后成功地赶上了大活动的日期。活动结束那天，经理发来一条消息，感谢每一个加班的人，还说今年会有一笔小小的奖金。钱不多，可那条消息让人觉得：只要把该做的事做完，别人是看得见的。", "p": ["jīn", "nián", "bù", "mén", "de", "gōng", "zuò", "jìn", "xíng", "de", "hěn", "shùn", "lì", "", "dà", "jiā", "àn", "zhào", "nián", "chū", "xiě", "hǎo", "de", "jì", "huà", "", "yí", "jiàn", "yí", "jiàn", "àn", "shí", "zuò", "wán", "", "zuì", "hòu", "chéng", "gōng", "dì", "gǎn", "shàng", "le", "dà", "huó", "dòng", "de", "rì", "qī", "", "huó", "dòng", "jié", "shù", "nà", "tiān", "", "jīng", "lǐ", "fà", "lái", "yì", "tiáo", "xiāo", "xi", "", "gǎn", "xiè", "měi", "yí", "gè", "jiā", "bān", "de", "rén", "", "hái", "shuō", "jīn", "nián", "huì", "yǒu", "yì", "bǐ", "xiǎo", "xiǎo", "de", "jiǎng", "jīn", "", "qián", "bù", "duō", "", "kě", "nà", "tiáo", "xiāo", "xi", "ràng", "rén", "jué", "de", "", "zhǐ", "yào", "bǎ", "gāi", "zuò", "de", "shì", "zuò", "wán", "", "bié", "rén", "shì", "kàn", "de", "jiàn", "de", ""], "vi": "Năm nay việc của phòng diễn ra rất thuận lợi. Mọi người làm theo kế hoạch viết từ đầu năm, hoàn thành đúng hạn từng việc, cuối cùng thành công bắt kịp ngày sự kiện lớn. Ngày kết thúc, giám đốc gửi một tin, cảm ơn từng người tăng ca, còn nói năm nay sẽ có một khoản thưởng nhỏ. Tiền không nhiều, nhưng tin ấy khiến người ta thấy: chỉ cần làm xong việc phải làm, người khác sẽ nhìn thấy.", "en": "This year the department's work has gone smoothly. Everyone followed the plan written at the beginning of the year, finished each task on time, and in the end succeeded in meeting the date of the big event. On the day it ended, the manager sent a message thanking everyone who had worked extra hours, and also said there would be a small bonus this year. It was not a lot of money, but that message made people feel that if you finish what you're supposed to do, others will notice."}]}, {"n": 5, "zh": "短文：不愿做的那份工作", "vi": "Đoạn văn: Việc mình không muốn làm", "en": "Passage: The work you would rather not do", "kw": ["不得不", "方法", "工资", "甚至", "责任", "知识"], "lines": [{"s": "", "sp": [], "t": "工作里总会有人不愿意做的事：又慢，又看不出成绩。可有时你不得不把它做完，因为那是你的责任。我曾经把一份很烦的材料推了又推，甚至想：这又不会加工资，为什么要认真？后来还是坐下来，找到自己的方法，把材料一项一项做清楚。做完以后我才发现，自己又多懂了一点相关的知识。工资是生活的一部分，但把一件难事做完，也会让人踏实。", "p": ["gōng", "zuò", "lǐ", "zǒng", "huì", "yǒu", "rén", "bú", "yuàn", "yì", "zuò", "de", "shì", "", "yòu", "màn", "", "yòu", "kàn", "bù", "chū", "chéng", "jì", "", "kě", "yǒu", "shí", "nǐ", "bù", "dé", "bù", "bǎ", "tā", "zuò", "wán", "", "yīn", "wèi", "nà", "shì", "nǐ", "de", "zé", "rèn", "", "wǒ", "céng", "jīng", "bǎ", "yí", "fèn", "hěn", "fán", "de", "cái", "liào", "tuī", "le", "yòu", "tuī", "", "shèn", "zhì", "xiǎng", "", "zhè", "yòu", "bú", "huì", "jiā", "gōng", "zī", "", "wèi", "shén", "me", "yào", "rèn", "zhēn", "", "hòu", "lái", "hái", "shì", "zuò", "xià", "lái", "", "zhǎo", "dào", "zì", "jǐ", "de", "fāng", "fǎ", "", "bǎ", "cái", "liào", "yí", "xiàng", "yí", "xiàng", "zuò", "qīng", "chǔ", "", "zuò", "wán", "yǐ", "hòu", "wǒ", "cái", "fā", "xiàn", "", "zì", "jǐ", "yòu", "duō", "dǒng", "le", "yì", "diǎn", "xiāng", "guān", "de", "zhī", "shi", "", "gōng", "zī", "shì", "shēng", "huó", "de", "yí", "bù", "fen", "", "dàn", "bǎ", "yí", "jiàn", "nán", "shì", "zuò", "wán", "", "yě", "huì", "ràng", "rén", "tā", "shi", ""], "vi": "Trong việc luôn có chuyện người ta không muốn làm: vừa chậm, vừa không thấy thành tích. Nhưng đôi khi bạn buộc phải làm xong, vì đó là trách nhiệm. Tôi từng đẩy đi đẩy lại một bản tài liệu rất mệt, thậm chí nghĩ: cái này lại không tăng lương, cần gì nghiêm túc? Sau cùng vẫn ngồi xuống, tìm phương pháp của mình, làm rõ từng mục. Xong rồi tôi mới thấy mình hiểu thêm một chút kiến thức liên quan. Lương là một phần của đời sống, nhưng làm xong một việc khó cũng khiến người ta vững lòng.", "en": "In any job there are always things people would rather not do: they are slow, and they don't seem to show any results. But sometimes you have no choice but to finish them, because that is your responsibility. I once pushed a very tedious set of materials aside again and again, and even thought: this won't even raise my pay, so why take it seriously? In the end I still sat down, found my own method, and worked through the materials item by item. Only when I had finished did I realise I had learned a little more of the related knowledge. Pay is part of life, but finishing a hard task also leaves you feeling steady."}]}]}, {"l": 5, "texts": [{"n": 1, "zh": "对话：阿玲在家具店看沙发", "vi": "Hội thoại: A Linh xem ghế sofa ở cửa hàng nội thất", "en": "Dialogue: A Linh looks at sofas in a furniture shop", "kw": ["打折", "家具", "价格", "肯定", "流行", "沙发", "质量"], "lines": [{"s": "吴姐", "sp": ["wú", "jiě"], "t": "姑娘，想看沙发吗？这几款最近很流行，这周末还打折。", "p": ["gū", "niáng", "", "xiǎng", "kàn", "shā", "fā", "ma", "", "zhè", "jǐ", "kuǎn", "zuì", "jìn", "hěn", "liú", "xíng", "", "zhè", "zhōu", "mò", "hái", "dǎ", "zhé", ""], "vi": "Cô gái, muốn xem sofa không? Mấy mẫu này gần đây rất thịnh hành, cuối tuần này còn giảm giá.", "en": "Miss, would you like to look at sofas? These styles have been very popular lately, and they're also on sale this weekend."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "我想看质量好一点儿的。颜色不要太花，价格也希望能接受。", "p": ["wǒ", "xiǎng", "kàn", "zhì", "liàng", "hǎo", "yì", "diǎn", "r", "de", "", "yán", "sè", "bú", "yào", "tài", "huā", "", "jià", "gé", "yě", "xī", "wàng", "néng", "jiē", "shòu", ""], "vi": "Em muốn xem loại chất lượng khá hơn một chút. Màu đừng quá sặc sỡ, giá cũng mong chấp nhận được.", "en": "I'd like to see ones with a bit better quality. The colour shouldn't be too busy, and I hope the price is acceptable too."}, {"s": "吴姐", "sp": ["wú", "jiě"], "t": "那您看这一套。面料耐用，坐上去也舒服。现在的价格比上周低了不少。", "p": ["nà", "nín", "kàn", "zhè", "yí", "tào", "", "miàn", "liào", "nài", "yòng", "", "zuò", "shàng", "qù", "yě", "shū", "fú", "", "xiàn", "zài", "de", "jià", "gé", "bǐ", "shàng", "zhōu", "dī", "le", "bù", "shǎo", ""], "vi": "Vậy cô xem bộ này. Vải bền, ngồi cũng êm. Giá hiện tại thấp hơn tuần trước nhiều.", "en": "Then have a look at this set. The fabric is durable, and it's comfortable to sit on. The price now is quite a bit lower than last week."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "我再摸摸。买家具不是小事，我肯定要再比较一下。", "p": ["wǒ", "zài", "mō", "mō", "", "mǎi", "jiā", "jù", "bú", "shì", "xiǎo", "shì", "", "wǒ", "kěn", "dìng", "yào", "zài", "bǐ", "jiào", "yí", "xià", ""], "vi": "Em sờ thêm đã. Mua nội thất không phải việc nhỏ, em chắc chắn phải so nữa.", "en": "I'll feel it again. Buying furniture isn't a small thing — I definitely want to compare a bit more."}, {"s": "吴姐", "sp": ["wú", "jiě"], "t": "可以。您先拍个照片，想好了再来。", "p": ["kě", "yǐ", "", "nín", "xiān", "pāi", "gè", "zhào", "piān", "", "xiǎng", "hǎo", "le", "zài", "lái", ""], "vi": "Được. Cô chụp ảnh trước, nghĩ xong hãy đến.", "en": "Of course. Take a photo first, and come back when you've thought it over."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "好，谢谢您。我今天先看看别的店。", "p": ["hǎo", "", "xiè", "xiè", "nín", "", "wǒ", "jīn", "tiān", "xiān", "kàn", "kàn", "bié", "de", "diàn", ""], "vi": "Vâng, cảm ơn chị. Hôm nay em xem thêm vài cửa khác đã.", "en": "Thank you. I'll look at a few other shops today first."}]}, {"n": 2, "zh": "对话：阿玲和周南在商场", "vi": "Hội thoại: A Linh và Châu Nam ở trung tâm thương mại", "en": "Dialogue: A Linh and Zhou Nan at the mall", "kw": ["实在", "顺便", "现金", "效果", "光", "台"], "lines": [{"s": "周南", "sp": ["zhōu", "nán"], "t": "你不是来看台灯的吗？怎么站在冰箱前面了？", "p": ["nǐ", "bú", "shì", "lái", "kàn", "tái", "dēng", "de", "ma", "", "zěn", "me", "zhàn", "zài", "bīng", "xiāng", "qián", "miàn", "le", ""], "vi": "Chẳng phải cậu đến xem đèn bàn sao? Sao lại đứng trước tủ lạnh?", "en": "Weren't you here to look at desk lamps? Why are you standing in front of the fridges?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "我想顺便看看。这一台能耗低，可价钱实在不便宜。", "p": ["wǒ", "xiǎng", "shùn", "biàn", "kàn", "kàn", "", "zhè", "yì", "tái", "néng", "hào", "dī", "", "kě", "jià", "qián", "shí", "zài", "bú", "biàn", "yí", ""], "vi": "Mình muốn tiện thể xem. Cái này tiêu hao điện thấp, nhưng giá thực sự không rẻ.", "en": "I wanted to have a look while we're here. This one uses little electricity, but the price really isn't cheap."}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "你不能光看宣传上写的效果，最好再问问一个月大概要用多少电。", "p": ["nǐ", "bù", "néng", "guāng", "kàn", "xuān", "chuán", "shàng", "xiě", "de", "xiào", "guǒ", "", "zuì", "hǎo", "zài", "wèn", "wèn", "yí", "gè", "yuè", "dà", "gài", "yào", "yòng", "duō", "shǎo", "diàn", ""], "vi": "Cậu đừng chỉ nhìn hiệu quả viết trên tờ quảng cáo, tốt nhất hỏi thêm mỗi tháng tốn khoảng bao nhiêu điện.", "en": "You shouldn't only look at the results written in the ads. It'd be better to ask how much electricity it uses in a month."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "说得对。那台灯呢？我想找一盏光不会太刺眼的。", "p": ["shuō", "de", "duì", "", "nà", "tái", "dēng", "ne", "", "wǒ", "xiǎng", "zhǎo", "yì", "zhǎn", "guāng", "bú", "huì", "tài", "cì", "yǎn", "de", ""], "vi": "Đúng đó. Còn đèn bàn? Mình muốn tìm cái ánh sáng không quá chói.", "en": "That's true. And the lamp? I want one whose light isn't too harsh."}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "那两台都不错。你要是决定买，我可以用现金先付。", "p": ["nà", "liǎng", "tái", "dōu", "bú", "cuò", "", "nǐ", "yào", "shi", "jué", "dìng", "mǎi", "", "wǒ", "kě", "yǐ", "yòng", "xiàn", "jīn", "xiān", "fù", ""], "vi": "Hai cái kia cũng ổn. Nếu cậu quyết mua, mình có thể trả bằng tiền mặt trước.", "en": "Those two are both fine. If you decide to buy one, I can pay in cash first."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "先把说明书拍下来，回去再想一晚吧。", "p": ["xiān", "bǎ", "shuō", "míng", "shū", "pāi", "xià", "lái", "", "huí", "qù", "zài", "xiǎng", "yì", "wǎn", "ba", ""], "vi": "Chụp hướng dẫn đã, về nghĩ thêm một đêm.", "en": "Let's photograph the instructions first and think it over for a night at home."}]}, {"n": 3, "zh": "对话：给陈老师挑一份礼物", "vi": "Hội thoại: Chọn quà cho cô Trần", "en": "Dialogue: Choosing a gift for Teacher Chen", "kw": ["广告", "葡萄", "实际", "味道", "邀请", "艺术", "优点"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "周末想邀请陈老师来家里吃晚饭。礼物你说买什么好？", "p": ["zhōu", "mò", "xiǎng", "yāo", "qǐng", "chén", "lǎo", "shī", "lái", "jiā", "lǐ", "chī", "wǎn", "fàn", "", "lǐ", "wù", "nǐ", "shuō", "mǎi", "shén", "me", "hǎo", ""], "vi": "Cuối tuần muốn mời cô Trần đến nhà ăn tối. Quà cậu bảo nên mua gì?", "en": "I'd like to invite Teacher Chen home for dinner at the weekend. What do you think we should buy her as a gift?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "水果比较合适。那边在卖葡萄，广告上写“又甜又大”，可不知道实际味道怎么样。", "p": ["shuǐ", "guǒ", "bǐ", "jiào", "hé", "shì", "", "nà", "biān", "zài", "mài", "pú", "tao", "", "guǎng", "gào", "shàng", "xiě", "", "yòu", "tián", "yòu", "dà", "", "", "kě", "bù", "zhī", "dào", "shí", "jì", "wèi", "dao", "zěn", "me", "yàng", ""], "vi": "Trái cây thì hợp. Bên đó đang bán nho, quảng cáo viết «vừa ngọt vừa to», nhưng không biết vị thực tế ra sao.", "en": "Fruit would be suitable. They're selling grapes over there, and the advertisement says \"sweet and big\", but I don't know what they actually taste like."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "那我们先买一丁点儿尝尝。要是味道不行，再看别的。", "p": ["nà", "wǒ", "men", "xiān", "mǎi", "yì", "dīng", "diǎn", "r", "cháng", "cháng", "", "yào", "shi", "wèi", "dao", "bù", "xíng", "", "zài", "kàn", "bié", "de", ""], "vi": "Vậy mình mua một chút nếm trước. Nếu vị không ổn thì xem thứ khác.", "en": "Then let's buy a little to taste first. If the flavour isn't right, we'll look at something else."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "也可以送一本小画册。她喜欢艺术，这算是一个优点：不贵，又记得住。", "p": ["yě", "kě", "yǐ", "sòng", "yì", "běn", "xiǎo", "huà", "cè", "", "tā", "xǐ", "huān", "yì", "shù", "", "zhè", "suàn", "shì", "yí", "gè", "yōu", "diǎn", "", "bú", "guì", "", "yòu", "jì", "de", "zhù", ""], "vi": "Cũng có thể tặng một tập tranh nhỏ. Cô thích nghệ thuật, đó là một ưu điểm: không đắt mà lại dễ nhớ.", "en": "We could also give her a little book of pictures. She likes art, and that's one advantage: it isn't expensive, and she'll remember it."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "那就水果和画册都准备一点儿，让她选。", "p": ["nà", "jiù", "shuǐ", "guǒ", "hé", "huà", "cè", "dōu", "zhǔn", "bèi", "yì", "diǎn", "r", "", "ràng", "tā", "xuǎn", ""], "vi": "Vậy thì chuẩn bị cả trái cây lẫn tập tranh, để cô chọn.", "en": "Then let's get a little of both, the fruit and the picture book, and let her choose."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "好。广告再好看，我们也先看东西本身。", "p": ["hǎo", "", "guǎng", "gào", "zài", "hǎo", "kàn", "", "wǒ", "men", "yě", "xiān", "kàn", "dōng", "xi", "běn", "shēn", ""], "vi": "Được. Quảng cáo đẹp đến mấy, mình cũng xem bản thân món đồ đã.", "en": "All right. However nice the advertisement is, we'll look at the thing itself first."}]}, {"n": 4, "zh": "短文：买衣服时我给自己的几条标准", "vi": "Đoạn văn: Vài tiêu chuẩn tôi đặt khi mua áo", "en": "Passage: A few standards I set myself when I buy clothes", "kw": ["标准", "考虑", "浪费", "年龄", "样子", "质量"], "lines": [{"s": "", "sp": [], "t": "以前我买衣服，只看样子新不新，偶尔还跟着流行走。穿过两次就不想再穿，等于把钱浪费了。后来我给自己定了几条标准：先考虑质量，再看颜色和大小是否适合我现在的年龄。样子可以简单，但一定要舒服、耐穿。这样买，衣服虽然少了，可每一件都能穿很久。", "p": ["yǐ", "qián", "wǒ", "mǎi", "yī", "fú", "", "zhǐ", "kàn", "yàng", "zi", "xīn", "bù", "xīn", "", "ǒu", "ěr", "hái", "gēn", "zhe", "liú", "xíng", "zǒu", "", "chuān", "guò", "liǎng", "cì", "jiù", "bù", "xiǎng", "zài", "chuān", "", "děng", "yú", "bǎ", "qián", "làng", "fèi", "le", "", "hòu", "lái", "wǒ", "gěi", "zì", "jǐ", "dìng", "le", "jǐ", "tiáo", "biāo", "zhǔn", "", "xiān", "kǎo", "lǜ", "zhì", "liàng", "", "zài", "kàn", "yán", "sè", "hé", "dà", "xiǎo", "shì", "fǒu", "shì", "hé", "wǒ", "xiàn", "zài", "de", "nián", "líng", "", "yàng", "zi", "kě", "yǐ", "jiǎn", "dān", "", "dàn", "yí", "dìng", "yào", "shū", "fú", "", "nài", "chuān", "", "zhè", "yàng", "mǎi", "", "yī", "fú", "suī", "rán", "shǎo", "le", "", "kě", "měi", "yí", "jiàn", "dōu", "néng", "chuān", "hěn", "jiǔ", ""], "vi": "Trước kia tôi mua áo chỉ nhìn kiểu mới hay không, đôi lúc còn theo mốt. Mặc hai lần đã không muốn mặc nữa, chẳng khác nào lãng phí tiền. Sau tôi đặt cho mình vài tiêu chuẩn: trước hãy xem xét chất lượng, rồi mới nhìn màu và kích cỡ có hợp với tuổi hiện tại không. Kiểu có thể đơn giản, nhưng phải thoải mái, bền. Mua như vậy, áo tuy ít hơn, nhưng mỗi món mặc được rất lâu.", "en": "I used to buy clothes only by whether the look was new, and sometimes I even followed the fashion. After wearing something twice I wouldn't want it again, which really meant I was wasting money. Later I set myself a few standards: consider the quality first, and then see whether the colour and size suit my age now. The style can be simple, but it must be comfortable and long-lasting. Buying this way, I have fewer clothes, but I can wear each piece for a long time."}]}, {"n": 5, "zh": "短文：网上购物也要停一停", "vi": "Đoạn văn: Mua hàng online cũng cần dừng lại một chút", "en": "Passage: Even when shopping online, it helps to pause", "kw": ["购物", "任何", "受到", "尤其", "寄", "家具"], "lines": [{"s": "", "sp": [], "t": "现在网上购物很方便，图片好看，手指一点，过两天东西就寄到家。可任何便利的背后，都可能让人买多。我曾经受到几张漂亮图片的影响，尤其是家具，看着眼红就下了单，收到后才发现房间根本放不下。后来我给自己定了个习惯：想买的东西先放一天，再决定要不要点。购物是为了用，不是为了点得痛快。", "p": ["xiàn", "zài", "wǎng", "shàng", "gòu", "wù", "hěn", "fāng", "biàn", "", "tú", "piàn", "hǎo", "kàn", "", "shǒu", "zhǐ", "yì", "diǎn", "", "guò", "liǎng", "tiān", "dōng", "xi", "jiù", "jì", "dào", "jiā", "", "kě", "rèn", "hé", "biàn", "lì", "de", "bèi", "hòu", "", "dōu", "kě", "néng", "ràng", "rén", "mǎi", "duō", "", "wǒ", "céng", "jīng", "shòu", "dào", "jǐ", "zhāng", "piào", "liàng", "tú", "piàn", "de", "yǐng", "xiǎng", "", "yóu", "qí", "shì", "jiā", "jù", "", "kàn", "zhe", "yǎn", "hóng", "jiù", "xià", "le", "dān", "", "shōu", "dào", "hòu", "cái", "fā", "xiàn", "fáng", "jiān", "gēn", "běn", "fàng", "bú", "xià", "", "hòu", "lái", "wǒ", "gěi", "zì", "jǐ", "dìng", "le", "gè", "xí", "guàn", "", "xiǎng", "mǎi", "de", "dōng", "xi", "xiān", "fàng", "yì", "tiān", "", "zài", "jué", "dìng", "yào", "bú", "yào", "diǎn", "", "gòu", "wù", "shì", "wèi", "le", "yòng", "", "bú", "shì", "wèi", "le", "diǎn", "de", "tòng", "kuai", ""], "vi": "Giờ mua sắm trên mạng rất tiện, ảnh đẹp, một cái chạm tay, vài hôm sau đồ đã được gửi tới nhà. Nhưng đằng sau bất kỳ sự tiện nào cũng có thể khiến người ta mua nhiều. Tôi từng chịu ảnh hưởng của vài tấm ảnh đẹp, nhất là đồ nội thất, nhìn ham là đặt, nhận xong mới thấy phòng chẳng để vừa. Sau tôi đặt cho mình một thói quen: món muốn mua để đó một ngày, rồi mới quyết có bấm không. Mua sắm là để dùng, không phải để bấm cho đã.", "en": "Shopping online is very convenient now: the pictures look nice, you tap once, and in a couple of days the things are sent to your home. But behind any convenience there is a chance you'll buy too much. I was once influenced by a few attractive pictures, especially of furniture; I ordered while my eyes were still hungry for it, and only when it arrived did I find it wouldn't fit in the room at all. Later I gave myself a habit: I leave anything I want to buy for a day, and only then decide whether to click. You shop in order to use things, not in order to enjoy clicking."}]}]}, {"l": 6, "texts": [{"n": 1, "zh": "对话：小雪逛完小店回来", "vi": "Hội thoại: Tiểu Tuyết về sau khi ghé cửa hàng nhỏ", "en": "Dialogue: Xiaoxue comes back from a little shop", "kw": ["售货员", "打扰", "果汁", "竟然", "袜子"], "lines": [{"s": "阿玲", "sp": ["ā", "líng"], "t": "你怎么这么晚才回来？我还以为你在图书馆。", "p": ["nǐ", "zěn", "me", "zhè", "me", "wǎn", "cái", "huí", "lái", "", "wǒ", "hái", "yǐ", "wéi", "nǐ", "zài", "tú", "shū", "guǎn", ""], "vi": "Sao cậu về muộn thế? Mình còn tưởng cậu ở thư viện.", "en": "Why are you back so late? I thought you were at the library."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "我路过那家小店，进去看袜子。售货员一直跟着我介绍，有点儿打扰，可她态度很好。", "p": ["wǒ", "lù", "guò", "nà", "jiā", "xiǎo", "diàn", "", "jìn", "qù", "kàn", "wà", "zi", "", "shòu", "huò", "yuán", "yì", "zhí", "gēn", "zhe", "wǒ", "jiè", "shào", "", "yǒu", "diǎn", "r", "dǎ", "rǎo", "", "kě", "tā", "tài", "dù", "hěn", "hǎo", ""], "vi": "Mình đi ngang tiệm nhỏ, vào xem tất. Nhân viên bán hàng cứ đi theo giới thiệu, hơi làm phiền, nhưng thái độ chị ấy rất tốt.", "en": "I passed that little shop and went in to look at socks. The salesperson kept following me around to explain things, which was a bit of a disturbance, but her manner was very kind."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "那你买了吗？", "p": ["nà", "nǐ", "mǎi", "le", "ma", ""], "vi": "Vậy cậu có mua không?", "en": "So did you buy anything?"}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "买了两双深色的。排队付款的时候，我竟然还拿了一瓶果汁。走的时候，售货员还说欢迎再来。", "p": ["mǎi", "le", "liǎng", "shuāng", "shēn", "sè", "de", "", "pái", "duì", "fù", "kuǎn", "de", "shí", "hòu", "", "wǒ", "jìng", "rán", "hái", "ná", "le", "yì", "píng", "guǒ", "zhī", "", "zǒu", "de", "shí", "hòu", "", "shòu", "huò", "yuán", "hái", "shuō", "huān", "yíng", "zài", "lái", ""], "vi": "Mua hai đôi màu tối. Lúc xếp hàng trả tiền, mình không ngờ còn cầm thêm một chai nước ép. Lúc đi, nhân viên còn nói lần sau ghé lại.", "en": "I bought two dark pairs. While I was queuing to pay, I even picked up a bottle of juice, unexpectedly. As I left, the salesperson said I was welcome to come again."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "瓶子在包里吗？小心别洒了。", "p": ["píng", "zi", "zài", "bāo", "lǐ", "ma", "", "xiǎo", "xīn", "bié", "sǎ", "le", ""], "vi": "Chai trong túi chứ? Cẩn thận kẻo đổ.", "en": "Is the bottle in your bag? Be careful not to spill it."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "放稳了。你要不要尝一口？很甜。", "p": ["fàng", "wěn", "le", "", "nǐ", "yào", "bú", "yào", "cháng", "yì", "kǒu", "", "hěn", "tián", ""], "vi": "Để chắc rồi. Cậu có muốn nếm một ngụm không? Ngọt lắm.", "en": "It's sitting securely. Do you want a sip? It's very sweet."}]}, {"n": 2, "zh": "对话：阿玲和周南帮社区挑西红柿", "vi": "Hội thoại: A Linh và Châu Nam chọn cà chua giúp khu phố", "en": "Dialogue: A Linh and Zhou Nan pick tomatoes for the neighbourhood", "kw": ["百分之", "西红柿", "好处", "皮肤", "倍", "尝"], "lines": [{"s": "周南", "sp": ["zhōu", "nán"], "t": "吴姐托我们买西红柿，做明天社区的汤。你说买哪一种？", "p": ["wú", "jiě", "tuō", "wǒ", "men", "mǎi", "xī", "hóng", "shì", "", "zuò", "míng", "tiān", "shè", "qū", "de", "tāng", "", "nǐ", "shuō", "mǎi", "nǎ", "yì", "zhǒng", ""], "vi": "Chị Ngô nhờ mình mua cà chua, nấu canh cho khu phố ngày mai. Cậu bảo mua loại nào?", "en": "Sister Wu asked us to buy tomatoes for tomorrow's neighbourhood soup. Which kind do you think we should get?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "先尝一块。这边的更甜，表面也更光滑。", "p": ["xiān", "cháng", "yí", "kuài", "", "zhè", "biān", "de", "gèng", "tián", "", "biǎo", "miàn", "yě", "gèng", "guāng", "huá", ""], "vi": "Nếm một miếng đã. Bên này ngọt hơn, bề mặt cũng mượt hơn.", "en": "Let's taste a piece first. These are sweeter, and the skin is smoother too."}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "摊主说，常吃对皮肤有好处。我也不知道是不是真的。", "p": ["tān", "zhǔ", "shuō", "", "cháng", "chī", "duì", "pí", "fū", "yǒu", "hǎo", "chu", "", "wǒ", "yě", "bù", "zhī", "dào", "shì", "bú", "shì", "zhēn", "de", ""], "vi": "Chủ quán nói ăn thường thì có lợi cho da. Mình cũng không biết có thật không.", "en": "The stallholder said eating them often is good for the skin. I don't know whether that's true."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "好处先不说，你看这个牌子：熟的占百分之八十，比那边多了差不多一倍。做汤正合适。", "p": ["hǎo", "chu", "xiān", "bù", "shuō", "", "nǐ", "kàn", "zhè", "ge", "pái", "zi", "", "shú", "de", "zhàn", "bǎi", "fēn", "zhī", "bā", "shí", "", "bǐ", "nà", "biān", "duō", "le", "chà", "bu", "duō", "yí", "bèi", "", "zuò", "tāng", "zhèng", "hé", "shì", ""], "vi": "Lợi ích để đó đã, cậu nhìn tấm bảng này: quả chín chiếm tám mươi phần trăm, nhiều hơn bên kia gần một lần. Nấu canh thì đúng.", "en": "Leave the benefits aside for a moment. Look at this sign: eighty percent of them are ripe, almost twice as many as at the other stall. That'll be just right for soup."}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "那就这一筐。我再问一句能不能少拿几个青的。", "p": ["nà", "jiù", "zhè", "yì", "kuāng", "", "wǒ", "zài", "wèn", "yí", "jù", "néng", "bù", "néng", "shǎo", "ná", "jǐ", "gè", "qīng", "de", ""], "vi": "Vậy lấy rổ này. Mình hỏi thêm có thể bớt vài quả xanh không.", "en": "Then let's take this basket. I'll also ask whether we can leave out a few of the green ones."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "好。买完我们直接送到吴姐那儿。", "p": ["hǎo", "", "mǎi", "wán", "wǒ", "men", "zhí", "jiē", "sòng", "dào", "wú", "jiě", "nà", "r", ""], "vi": "Được. Mua xong mình đưa thẳng tới chỗ chị Ngô.", "en": "All right. When we've bought them we'll take them straight to Sister Wu."}]}, {"n": 3, "zh": "对话：周南要出远门买箱子", "vi": "Hội thoại: Châu Nam sắp đi xa, mua vali", "en": "Dialogue: Zhou Nan is going away and buys a suitcase", "kw": ["方面", "活动", "免费", "修理", "值得", "内", "轻"], "lines": [{"s": "阿玲", "sp": ["ā", "líng"], "t": "你不是下个月要去广州吗？怎么来看箱子了？", "p": ["nǐ", "bú", "shì", "xià", "gè", "yuè", "yào", "qù", "guǎng", "zhōu", "ma", "", "zěn", "me", "lái", "kàn", "xiāng", "zi", "le", ""], "vi": "Tháng sau chẳng phải cậu đi Quảng Châu sao? Sao lại xem vali?", "en": "Aren't you going to Guangzhou next month? Why are you looking at suitcases?"}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "我想买一个轻一点儿的。你看这只，提起来不费劲，内里还有一层小口袋。", "p": ["wǒ", "xiǎng", "mǎi", "yí", "gè", "qīng", "yì", "diǎn", "r", "de", "", "nǐ", "kàn", "zhè", "zhǐ", "", "tí", "qǐ", "lái", "bú", "fèi", "jìn", "", "nèi", "lǐ", "hái", "yǒu", "yì", "céng", "xiǎo", "kǒu", "dài", ""], "vi": "Mình muốn mua cái nhẹ hơn một chút. Cậu xem cái này, xách lên không mất sức, bên trong còn một lớp túi nhỏ.", "en": "I'd like one that's a bit lighter. Look at this one: it isn't hard to lift, and there is also a layer of small pockets inside."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "价格呢？这周末商场有活动，会不会便宜些？", "p": ["jià", "gé", "ne", "", "zhè", "zhōu", "mò", "shāng", "chǎng", "yǒu", "huó", "dòng", "", "huì", "bú", "huì", "pián", "yi", "xiē", ""], "vi": "Còn giá? Cuối tuần này trung tâm có hoạt động, liệu có rẻ hơn không?", "en": "What about the price? The mall has a promotion this weekend — might it be cheaper?"}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "问过了。现在买，一年内免费修理，我觉得值得。", "p": ["wèn", "guò", "le", "", "xiàn", "zài", "mǎi", "", "yì", "nián", "nèi", "miǎn", "fèi", "xiū", "lǐ", "", "wǒ", "jué", "de", "zhí", "de", ""], "vi": "Hỏi rồi. Mua bây giờ thì trong một năm sửa miễn phí, mình thấy đáng.", "en": "I've already asked. If I buy it now, repairs are free within a year. I think it's worth it."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "那在质量方面没问题就好。你再试试轮子转不转得稳。", "p": ["nà", "zài", "zhì", "liàng", "fāng", "miàn", "méi", "wèn", "tí", "jiù", "hǎo", "", "nǐ", "zài", "shì", "shì", "lún", "zi", "zhuǎn", "bù", "zhuǎn", "de", "wěn", ""], "vi": "Vậy về mặt chất lượng không vấn đề là được. Cậu thử bánh xe quay có vững không.", "en": "Then as long as there's no problem with the quality, that's fine. Try whether the wheels run steadily too."}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "还行。我就拿这只吧，省得再跑一趟。", "p": ["hái", "xíng", "", "wǒ", "jiù", "ná", "zhè", "zhǐ", "ba", "", "shěng", "de", "zài", "pǎo", "yí", "tàng", ""], "vi": "Cũng ổn. Mình lấy cái này vậy, khỏi phải chạy thêm chuyến.", "en": "It's all right. I'll take this one, so I don't have to come back again."}]}, {"n": 4, "zh": "短文：书店里的一场小活动", "vi": "Đoạn văn: Một hoạt động nhỏ trong hiệu sách", "en": "Passage: A little event in the bookshop", "kw": ["获得", "举行", "其中", "所有", "小说", "支持", "满"], "lines": [{"s": "", "sp": [], "t": "今天下午，学校书店举行了一场交换旧书的活动。座位很快就坐满了，过道里也站着人。所有带来书的同学，都可以获得一张小书签；其中带来三本以上的，还能再选一本小说带回家。我把两本看完的故事和一本词典放在桌上。虽然我没有多换到什么，可看到那么多人来支持这场活动，心里还是很高兴。晚上我坐在灯下，翻开那本刚换来的小说，倒觉得这一下午没有白来。", "p": ["jīn", "tiān", "xià", "wǔ", "", "xué", "xiào", "shū", "diàn", "jǔ", "xíng", "le", "yì", "cháng", "jiāo", "huàn", "jiù", "shū", "de", "huó", "dòng", "", "zuò", "wèi", "hěn", "kuài", "jiù", "zuò", "mǎn", "le", "", "guò", "dào", "lǐ", "yě", "zhàn", "zhe", "rén", "", "suǒ", "yǒu", "dài", "lái", "shū", "de", "tóng", "xué", "", "dōu", "kě", "yǐ", "huò", "de", "yì", "zhāng", "xiǎo", "shū", "qiān", "", "qí", "zhōng", "dài", "lái", "sān", "běn", "yǐ", "shàng", "de", "", "hái", "néng", "zài", "xuǎn", "yì", "běn", "xiǎo", "shuō", "dài", "huí", "jiā", "", "wǒ", "bǎ", "liǎng", "běn", "kàn", "wán", "de", "gù", "shì", "hé", "yì", "běn", "cí", "diǎn", "fàng", "zài", "zhuō", "shàng", "", "suī", "rán", "wǒ", "méi", "yǒu", "duō", "huàn", "dào", "shén", "me", "", "kě", "kàn", "dào", "nà", "me", "duō", "rén", "lái", "zhī", "chí", "zhè", "chǎng", "huó", "dòng", "", "xīn", "lǐ", "hái", "shì", "hěn", "gāo", "xìng", "", "wǎn", "shàng", "wǒ", "zuò", "zài", "dēng", "xià", "", "fān", "kāi", "nà", "běn", "gāng", "huàn", "lái", "de", "xiǎo", "shuō", "", "dào", "jué", "de", "zhè", "yí", "xià", "wǔ", "méi", "yǒu", "bái", "lái", ""], "vi": "Chiều nay hiệu sách trường tổ chức một hoạt động đổi sách cũ. Chỗ ngồi chẳng mấy chốc đã kín, lối đi cũng có người đứng. Tất cả bạn mang sách đến đều có thể nhận một tấm đánh dấu sách nhỏ; trong số đó ai mang từ ba quyển trở lên còn được chọn thêm một tiểu thuyết mang về. Tôi để hai tập truyện đã đọc xong và một quyển từ điển lên bàn. Tuy không đổi thêm được bao nhiêu, nhưng thấy nhiều người đến ủng hộ hoạt động ấy, trong lòng vẫn vui. Tối tôi ngồi dưới đèn, mở quyển tiểu thuyết mới đổi, lại thấy cả buổi chiều không uổng.", "en": "This afternoon the school bookshop held an event for exchanging old books. The seats were soon full, and people were standing in the aisles as well. All the students who brought books could obtain a little bookmark; among them, those who brought three or more could also choose a novel to take home. I put two stories I had finished and a dictionary on the table. Although I did not exchange much extra, I was still glad to see so many people come and support the event. In the evening I sat under the lamp, opened the novel I had just exchanged, and felt that the afternoon had not been wasted."}]}, {"n": 5, "zh": "短文：比的不只是价格", "vi": "Đoạn văn: So không chỉ mỗi cái giá", "en": "Passage: It is not only the price you compare", "kw": ["降低", "举办", "例如", "情况", "各"], "lines": [{"s": "", "sp": [], "t": "商场一举办促销，价格就会降低一些，这谁都知道。可各家的情况并不一样。例如上周校园超市减价，我看到两种外观差不多的笔记本：一种很便宜，写两天纸就起毛；另一种贵一点，却能用一个学期。后来我才明白，减价是让人走近货架，真正要比较的，是自己会用多久。便宜得让人立刻动手，不一定最合适；贵一点但能用很长时间，有时反而更省。", "p": ["shāng", "chǎng", "yì", "jǔ", "bàn", "cù", "xiāo", "", "jià", "gé", "jiù", "huì", "jiàng", "dī", "yì", "xiē", "", "zhè", "shéi", "dōu", "zhī", "dào", "", "kě", "gè", "jiā", "de", "qíng", "kuàng", "bìng", "bù", "yí", "yàng", "", "lì", "rú", "shàng", "zhōu", "xiào", "yuán", "chāo", "shì", "jiǎn", "jià", "", "wǒ", "kàn", "dào", "liǎng", "zhǒng", "wài", "guān", "chà", "bu", "duō", "de", "bǐ", "jì", "běn", "", "yì", "zhǒng", "hěn", "pián", "yi", "", "xiě", "liǎng", "tiān", "zhǐ", "jiù", "qǐ", "máo", "", "lìng", "yì", "zhǒng", "guì", "yì", "diǎn", "", "què", "néng", "yòng", "yí", "gè", "xué", "qī", "", "hòu", "lái", "wǒ", "cái", "míng", "bái", "", "jiǎn", "jià", "shì", "ràng", "rén", "zǒu", "jìn", "huò", "jià", "", "zhēn", "zhèng", "yào", "bǐ", "jiào", "de", "", "shì", "zì", "jǐ", "huì", "yòng", "duō", "jiǔ", "", "pián", "yi", "de", "ràng", "rén", "lì", "kè", "dòng", "shǒu", "", "bù", "yí", "dìng", "zuì", "hé", "shì", "", "guì", "yì", "diǎn", "dàn", "néng", "yòng", "hěn", "cháng", "shí", "jiān", "", "yǒu", "shí", "fǎn", "ér", "gèng", "shěng", ""], "vi": "Trung tâm một tổ chức khuyến mãi là giá sẽ giảm đôi chút, ai cũng biết. Nhưng tình hình mỗi nơi không giống nhau. Ví dụ tuần trước siêu thị trong trường giảm giá, tôi thấy hai loại vở trông gần như nhau: một loại rất rẻ, viết hai ngày giấy đã xơ; loại kia đắt hơn một chút, nhưng dùng được cả học kỳ. Sau tôi mới hiểu, giảm giá là để người ta lại gần kệ, điều thật sự cần so là mình dùng được bao lâu. Rẻ đến mức khiến người ta sờ ngay, chưa chắc đã hợp nhất; đắt hơn một chút nhưng dùng lâu, đôi khi lại tiết kiệm hơn.", "en": "Everyone knows that as soon as a shopping centre holds a promotion, prices will drop a little. But the situation is not the same at every shop. For example, when the campus supermarket reduced prices last week, I saw two kinds of notebook that looked almost alike: one was very cheap, but after two days of writing the paper began to fluff; the other cost a little more, yet it could last a whole term. Only later did I understand that a sale is what brings you to the shelf, and what you really have to compare is how long you will use the thing. Something so cheap that you reach for it at once is not necessarily the best fit; something a little dearer that lasts a long time can, in fact, save you more."}]}]}, {"l": 7, "texts": [{"n": 1, "zh": "对话：换季的时候阿玲咳嗽了", "vi": "Hội thoại: Đổi mùa, A Linh bị ho", "en": "Dialogue: A Linh has a cough when the season changes", "kw": ["窗户", "估计", "咳嗽", "空气", "气候", "严重", "擦"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你的声音怎么哑了？是不是又咳嗽了？", "p": ["nǐ", "de", "shēng", "yīn", "zěn", "me", "yǎ", "le", "", "shì", "bú", "shì", "yòu", "ké", "sou", "le", ""], "vi": "Giọng cậu sao khàn thế? Lại ho rồi à?", "en": "Why is your voice so hoarse? Have you got a cough again?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "这两天气候一下子变冷，我晚上忘了关窗户，早上起来就咳。还好不太严重。", "p": ["zhè", "liǎng", "tiān", "qì", "hòu", "yí", "xià", "zi", "biàn", "lěng", "", "wǒ", "wǎn", "shàng", "wàng", "le", "guān", "chuāng", "hu", "", "zǎo", "shàng", "qǐ", "lái", "jiù", "ké", "", "hái", "hǎo", "bú", "tài", "yán", "zhòng", ""], "vi": "Mấy hôm nay khí hậu lạnh đột ngột, tối mình quên đóng cửa sổ, sáng dậy là ho. May mà không nghiêm trọng lắm.", "en": "The climate turned cold all of a sudden these past two days. I forgot to close the window at night, and I was coughing when I got up. Luckily it isn't too serious."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "我估计是风灌进来了。你把窗边擦一擦，别让灰和冷空气一起进来。", "p": ["wǒ", "gū", "jì", "shì", "fēng", "guàn", "jìn", "lái", "le", "", "nǐ", "bǎ", "chuāng", "biān", "cā", "yì", "cā", "", "bié", "ràng", "huī", "hé", "lěng", "kōng", "qì", "yì", "qǐ", "jìn", "lái", ""], "vi": "Mình đoán gió lùa vào. Cậu lau mép cửa sổ một chút, đừng để bụi và không khí lạnh cùng vào.", "en": "I would estimate the wind blew in. Wipe around the window a bit, so the dust and the cold air don't come in together."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "好。我再泡杯热的。你那边呢？还习惯这儿春天的气候吗？", "p": ["hǎo", "", "wǒ", "zài", "pào", "bēi", "rè", "de", "", "nǐ", "nà", "biān", "ne", "", "hái", "xí", "guàn", "zhè", "r", "chūn", "tiān", "de", "qì", "hòu", "ma", ""], "vi": "Được. Mình pha thêm chén nóng. Còn phía cậu? Đã quen khí hậu mùa xuân ở đây chưa?", "en": "All right. I'll also make a cup of something hot. What about you? Have you got used to the spring climate here yet?"}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "比我家那边湿一点儿，不过开窗换空气，人会舒服些。", "p": ["bǐ", "wǒ", "jiā", "nà", "biān", "shī", "yì", "diǎn", "r", "", "bú", "guò", "kāi", "chuāng", "huàn", "kōng", "qì", "", "rén", "huì", "shū", "fú", "xiē", ""], "vi": "Ẩm hơn nhà mình một chút, nhưng mở cửa đổi không khí thì người dễ chịu hơn.", "en": "It's a bit damper than at home, but if you open the window and change the air, you feel more comfortable."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "那我白天把窗户打开一阵，晚上再关上。", "p": ["nà", "wǒ", "bái", "tiān", "bǎ", "chuāng", "hu", "dǎ", "kāi", "yí", "zhèn", "", "wǎn", "shàng", "zài", "guān", "shàng", ""], "vi": "Vậy ban ngày mình mở cửa sổ một lúc, tối đóng lại.", "en": "Then I'll open the window for a while in the daytime, and close it again at night."}]}, {"n": 2, "zh": "对话：小雪劝表哥少抽烟", "vi": "Hội thoại: Tiểu Tuyết khuyên anh họ ít hút thuốc", "en": "Dialogue: Xiaoxue urges her cousin to smoke less", "kw": ["来不及", "抽烟", "出现", "动作", "反对", "后悔", "帅"], "lines": [{"s": "阿玲", "sp": ["ā", "líng"], "t": "你一接完电话就皱眉，谁啊？", "p": ["nǐ", "yì", "jiē", "wán", "diàn", "huà", "jiù", "zhòu", "méi", "", "shuí", "a", ""], "vi": "Vừa gác máy cậu đã nhíu mày, ai thế?", "en": "You frowned as soon as you hung up. Who was it?"}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "我表哥。他一抽烟，家里就反对，可他还是停不下来。", "p": ["wǒ", "biǎo", "gē", "", "tā", "yì", "chōu", "yān", "", "jiā", "lǐ", "jiù", "fǎn", "duì", "", "kě", "tā", "hái", "shì", "tíng", "bú", "xià", "lái", ""], "vi": "Anh họ mình. Hễ anh ấy hút thuốc là nhà phản đối, nhưng anh ấy vẫn không dừng được.", "en": "My cousin. Whenever he smokes, the family is against it, but he still can't stop."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "你怎么劝的？", "p": ["nǐ", "zěn", "me", "quàn", "de", ""], "vi": "Cậu khuyên thế nào?", "en": "What did you say to him?"}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "我说，你看起来挺帅的，可一出现烟味，别人就会往旁边让。他听了只是笑。", "p": ["wǒ", "shuō", "", "nǐ", "kàn", "qǐ", "lái", "tǐng", "shuài", "de", "", "kě", "yì", "chū", "xiàn", "yān", "wèi", "", "bié", "rén", "jiù", "huì", "wǎng", "páng", "biān", "ràng", "", "tā", "tīng", "le", "zhǐ", "shì", "xiào", ""], "vi": "Mình nói, trông anh cũng khá đẹp trai, nhưng hễ mùi thuốc xuất hiện là người khác tránh sang bên. Anh ấy nghe xong chỉ cười.", "en": "I said, \"You look quite handsome, but as soon as the smell of smoke appears, people step aside.\" He only laughed when he heard that."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "他后悔过吗？", "p": ["tā", "hòu", "huǐ", "guò", "ma", ""], "vi": "Anh ấy đã từng hối chưa?", "en": "Has he ever regretted it?"}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "后悔过。有一次要赶车，他在站里找打火机，动作一慢，车就开走了，来不及追。他说那次真不该把时间耗在烟上。", "p": ["hòu", "huǐ", "guò", "", "yǒu", "yí", "cì", "yào", "gǎn", "chē", "", "tā", "zài", "zhàn", "lǐ", "zhǎo", "dǎ", "huǒ", "jī", "", "dòng", "zuò", "yí", "màn", "", "chē", "jiù", "kāi", "zǒu", "le", "", "lái", "bu", "jí", "zhuī", "", "tā", "shuō", "nà", "cì", "zhēn", "bù", "gāi", "bǎ", "shí", "jiān", "hào", "zài", "yān", "shàng", ""], "vi": "Đã hối. Có lần phải bắt xe, anh ấy tìm bật lửa trong bến, động tác chậm một cái là xe chạy mất, không kịp đuổi. Anh ấy bảo lần ấy thật không nên bỏ thời gian vào thuốc.", "en": "He has. Once he had to catch a bus. He was looking for a lighter at the stop, his movements were just a little slow, and the bus left — he had no time to run after it. He said he really shouldn't have spent that time on a cigarette."}]}, {"n": 3, "zh": "对话：陈晓坐太久，大夫让他多走走", "vi": "Hội thoại: Trần Hiểu ngồi quá lâu, bác sĩ bảo đi bộ nhiều hơn", "en": "Dialogue: Chen Xiao sat too long, and the doctor told him to walk more", "kw": ["超过", "大夫", "散步", "研究", "植物"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "陈晓最近怎么总揉肩膀？", "p": ["chén", "xiǎo", "zuì", "jìn", "zěn", "me", "zǒng", "róu", "jiān", "bǎng", ""], "vi": "Dạo này Trần Hiểu sao cứ xoa vai?", "en": "Why has Chen Xiao been rubbing his shoulders so much lately?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "他写论文，一天坐在电脑前超过八个小时。上周去看大夫，大夫说先别吃药，每天出去散步。", "p": ["tā", "xiě", "lùn", "wén", "", "yì", "tiān", "zuò", "zài", "diàn", "nǎo", "qián", "chāo", "guò", "bā", "gè", "xiǎo", "shí", "", "shàng", "zhōu", "qù", "kàn", "dài", "fu", "", "dài", "fu", "shuō", "xiān", "bié", "chī", "yào", "", "měi", "tiān", "chū", "qù", "sàn", "bù", ""], "vi": "Cậu ấy viết luận văn, một ngày ngồi trước máy tính hơn tám tiếng. Tuần trước đi khám, bác sĩ bảo đừng uống thuốc vội, mỗi ngày ra ngoài đi dạo.", "en": "He's writing his thesis and sits in front of the computer for more than eight hours a day. He went to see the doctor last week. The doctor said not to take medicine first, and to go out for a walk every day."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "光散步够吗？", "p": ["guāng", "sàn", "bù", "gòu", "ma", ""], "vi": "Chỉ đi dạo đã đủ chưa?", "en": "Is walking enough on its own?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "大夫还让他在桌上放两盆植物，研究里说，看看绿色，眼睛会轻松一些。", "p": ["dài", "fu", "hái", "ràng", "tā", "zài", "zhuō", "shàng", "fàng", "liǎng", "pén", "zhí", "wù", "", "yán", "jiū", "lǐ", "shuō", "", "kàn", "kàn", "lǜ", "sè", "", "yǎn", "jīng", "huì", "qīng", "sōng", "yì", "xiē", ""], "vi": "Bác sĩ còn bảo đặt hai chậu cây trên bàn, trong nghiên cứu nói nhìn màu xanh thì mắt dễ chịu hơn.", "en": "The doctor also told him to put two pots of plants on the desk. Research says that looking at something green makes the eyes a little more at ease."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "那倒简单。我下午去市场，顺便帮他买一盆。", "p": ["nà", "dào", "jiǎn", "dān", "", "wǒ", "xià", "wǔ", "qù", "shì", "chǎng", "", "shùn", "biàn", "bāng", "tā", "mǎi", "yì", "pén", ""], "vi": "Thế thì đơn giản. Chiều mình ra chợ, tiện thể mua giúp một chậu.", "en": "That's easy enough. I'll go to the market this afternoon and get a pot for him while I'm there."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "你跟他说一声就行。他已经开始晚饭后围着楼散步了。", "p": ["nǐ", "gēn", "tā", "shuō", "yì", "shēng", "jiù", "xíng", "", "tā", "yǐ", "jīng", "kāi", "shǐ", "wǎn", "fàn", "hòu", "wéi", "zhe", "lóu", "sàn", "bù", "le", ""], "vi": "Cậu nói với anh ấy một tiếng là được. Anh ấy đã bắt đầu sau bữa tối đi dạo quanh nhà rồi.", "en": "Just mention it to him. He has already started walking around the building after dinner."}]}, {"n": 4, "zh": "短文：教授指给我看的一组数字", "vi": "Đoạn văn: Một nhóm số giáo sư chỉ cho tôi xem", "en": "Passage: A set of numbers a professor pointed out to me", "kw": ["教授", "数字", "说明", "要是", "指"], "lines": [{"s": "", "sp": [], "t": "健康课上，教授在黑板上写下几组数字，又用粉笔指着其中一行说：“你们看，坐着的时间一年比一年长。”这些数字说明，很多同学不是不知道运动，而是把运动一直往后放。要是每天能抽出二十分钟走一走，情况就会不一样。下课后我把那一行数字抄在本子上，贴在书桌前面。不是为了吓自己，只是希望一抬头就能看见：身体的事，拖不得。", "p": ["jiàn", "kāng", "kè", "shàng", "", "jiào", "shòu", "zài", "hēi", "bǎn", "shàng", "xiě", "xià", "jǐ", "zǔ", "shù", "zì", "", "yòu", "yòng", "fěn", "bǐ", "zhǐ", "zhe", "qí", "zhōng", "yì", "xíng", "shuō", "", "", "nǐ", "men", "kàn", "", "zuò", "zhe", "de", "shí", "jiān", "yì", "nián", "bǐ", "yì", "nián", "zhǎng", "", "", "zhè", "xiē", "shù", "zì", "shuō", "míng", "", "hěn", "duō", "tóng", "xué", "bú", "shì", "bù", "zhī", "dào", "yùn", "dòng", "", "ér", "shì", "bǎ", "yùn", "dòng", "yì", "zhí", "wǎng", "hòu", "fàng", "", "yào", "shi", "měi", "tiān", "néng", "chōu", "chū", "èr", "shí", "fēn", "zhōng", "zǒu", "yì", "zǒu", "", "qíng", "kuàng", "jiù", "huì", "bù", "yí", "yàng", "", "xià", "kè", "hòu", "wǒ", "bǎ", "nà", "yì", "xíng", "shù", "zì", "chāo", "zài", "běn", "zi", "shàng", "", "tiē", "zài", "shū", "zhuō", "qián", "miàn", "", "bú", "shì", "wèi", "le", "xià", "zì", "jǐ", "", "zhǐ", "shì", "xī", "wàng", "yì", "tái", "tóu", "jiù", "néng", "kàn", "jiàn", "", "shēn", "tǐ", "de", "shì", "", "tuō", "bù", "de", ""], "vi": "Trên giờ sức khỏe, giáo sư viết vài nhóm số lên bảng, rồi dùng phấn chỉ một hàng nói: «Các em nhìn, thời gian ngồi năm sau dài hơn năm trước.» Những con số ấy cho thấy nhiều bạn không phải không biết vận động, mà cứ để việc ấy về sau. Nếu mỗi ngày dành được hai mươi phút đi bộ, tình hình sẽ khác. Tan học tôi chép hàng số đó vào sổ, dán trước bàn. Không phải để tự dọa, chỉ mong ngẩng lên là thấy: việc của cơ thể không thể trì.", "en": "In the health class, the professor wrote a few sets of numbers on the blackboard, then pointed to one line with the chalk and said, \"Look: the time spent sitting is getting longer year by year.\" These numbers show that many students are not unaware of exercise; they just keep putting it off. If they could take twenty minutes every day to walk a little, the situation would be different. After class I copied that line of numbers into my notebook and stuck it in front of my desk. It was not to frighten myself, only in the hope that I would see it as soon as I looked up: you cannot put off matters of the body."}]}, {"n": 5, "zh": "短文：掉下去的不是只是体重", "vi": "Đoạn văn: Cái rơi đi không chỉ là cân nặng", "en": "Passage: It is not only the weight that drops", "kw": ["肚子", "烦恼", "感情", "减肥", "辛苦", "掉"], "lines": [{"s": "", "sp": [], "t": "我有个朋友为减肥烦了很久。她一看到肚子上的肉，烦恼就来了，连晚饭都吃不安心。后来她不再只看秤上的数字，而是每天走一段路，再少喝一杯甜的。过程当然辛苦，有一回晚上她差点放弃。可坚持了两个月，掉下去的不只是体重，还有那种一看镜子就不开心的感情。她说，身材会变，但更让她高兴的是，自己终于能跟身体好好相处。", "p": ["wǒ", "yǒu", "gè", "péng", "you", "wèi", "jiǎn", "féi", "fán", "le", "hěn", "jiǔ", "", "tā", "yí", "kàn", "dào", "dǔ", "zi", "shàng", "de", "ròu", "", "fán", "nǎo", "jiù", "lái", "le", "", "lián", "wǎn", "fàn", "dōu", "chī", "bù", "ān", "xīn", "", "hòu", "lái", "tā", "bú", "zài", "zhǐ", "kàn", "chèng", "shàng", "de", "shù", "zì", "", "ér", "shì", "měi", "tiān", "zǒu", "yí", "duàn", "lù", "", "zài", "shǎo", "hē", "yì", "bēi", "tián", "de", "", "guò", "chéng", "dāng", "rán", "xīn", "kǔ", "", "yǒu", "yì", "huí", "wǎn", "shàng", "tā", "chà", "diǎn", "fàng", "qì", "", "kě", "jiān", "chí", "le", "liǎng", "gè", "yuè", "", "diào", "xià", "qù", "de", "bù", "zhǐ", "shì", "tǐ", "zhòng", "", "hái", "yǒu", "nà", "zhǒng", "yí", "kàn", "jìng", "zi", "jiù", "bù", "kāi", "xīn", "de", "gǎn", "qíng", "", "tā", "shuō", "", "shēn", "cái", "huì", "biàn", "", "dàn", "gèng", "ràng", "tā", "gāo", "xìng", "de", "shì", "", "zì", "jǐ", "zhōng", "yú", "néng", "gēn", "shēn", "tǐ", "hǎo", "hǎo", "xiāng", "chǔ", ""], "vi": "Tôi có người bạn đã lo chuyện giảm cân rất lâu. Hễ thấy lớp mỡ trên bụng là phiền não kéo đến, cơm tối cũng không yên. Sau cô ấy không chỉ nhìn con số trên cân, mà mỗi ngày đi một đoạn, rồi bớt một ly đồ ngọt. Quá trình tất nhiên vất vả, có tối cô suýt bỏ cuộc. Nhưng kiên trì hai tháng, cái rơi đi không chỉ là cân nặng, mà cả cảm xúc khó chịu mỗi khi nhìn gương. Cô nói, dáng sẽ thay đổi, nhưng điều khiến cô vui hơn là cuối cùng mình sống được tử tế với cơ thể.", "en": "I have a friend who was troubled about losing weight for a long time. As soon as she saw the fat on her stomach, the worry arrived, and she could not even eat dinner in peace. Later she stopped looking only at the number on the scale, and instead walked a stretch every day and also drank one less sweet cup. The process was hard work, of course, and one evening she almost gave up. But after she kept it up for two months, what had dropped was not only her weight, but also that unhappy feeling she used to get as soon as she looked in the mirror. She said her figure would change, but what pleased her more was that she could finally get along properly with her own body."}]}]}, {"l": 8, "texts": [{"n": 1, "zh": "对话：阿玲买巧克力走亲戚", "vi": "Hội thoại: A Linh mua sô-cô-la đi thăm họ hàng", "en": "Dialogue: A Linh buys chocolate to visit relatives", "kw": ["巧克力", "亲戚", "伤心", "心情", "愉快", "使"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你提着这么一大盒，要去哪儿？", "p": ["nǐ", "tí", "zhe", "zhè", "me", "yí", "dà", "hé", "", "yào", "qù", "nǎ", "r", ""], "vi": "Cậu xách hộp to thế, định đi đâu?", "en": "You're carrying such a big box — where are you going?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "去看林阿姨那边的亲戚。我买了巧克力，想使他们高兴一点儿。", "p": ["qù", "kàn", "lín", "ā", "yí", "nà", "biān", "de", "qīn", "qi", "", "wǒ", "mǎi", "le", "qiǎo", "kè", "lì", "", "xiǎng", "shǐ", "tā", "men", "gāo", "xìng", "yì", "diǎn", "r", ""], "vi": "Đi thăm họ hàng bên thím Lâm. Mình mua sô-cô-la, muốn làm họ vui hơn một chút.", "en": "To see some relatives on Aunt Lin's side. I bought chocolate, hoping to make them a little happier."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "听说吃甜的能让人心情变好，是真的吗？", "p": ["tīng", "shuō", "chī", "tián", "de", "néng", "ràng", "rén", "xīn", "qíng", "biàn", "hǎo", "", "shì", "zhēn", "de", "ma", ""], "vi": "Nghe nói ăn đồ ngọt có thể khiến tâm trạng khá hơn, có thật không?", "en": "People say eating something sweet can improve your mood — is that true?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "我也不敢说每次都行。不过林阿姨前阵子有点儿伤心，我见她拆开包装，脸色倒是愉快了不少。", "p": ["wǒ", "yě", "bù", "gǎn", "shuō", "měi", "cì", "dōu", "xíng", "", "bú", "guò", "lín", "ā", "yí", "qián", "zhèn", "zi", "yǒu", "diǎn", "r", "shāng", "xīn", "", "wǒ", "jiàn", "tā", "chāi", "kāi", "bāo", "zhuāng", "", "liǎn", "sè", "dào", "shì", "yú", "kuài", "le", "bù", "shǎo", ""], "vi": "Mình cũng không dám nói lần nào cũng được. Nhưng thím Lâm vừa rồi hơi buồn, mình thấy thím mở gói ra, nét mặt vui hơn hẳn.", "en": "I wouldn't dare say it works every time. But Aunt Lin was a little sad a while ago, and when I saw her unwrap it, her face did become a good deal more cheerful."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "那就好。你代我问她一声好。", "p": ["nà", "jiù", "hǎo", "", "nǐ", "dài", "wǒ", "wèn", "tā", "yì", "shēng", "hǎo", ""], "vi": "Thế thì tốt. Cậu hỏi thăm thím giúp mình một tiếng.", "en": "That's good. Please say hello to her for me."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "一定。我还买了一小袋给她孙子，免得他看见大人吃，自己没份。", "p": ["yī", "dìng", "", "wǒ", "hái", "mǎi", "le", "yì", "xiǎo", "dài", "gěi", "tā", "sūn", "zi", "", "miǎn", "de", "tā", "kàn", "jiàn", "dà", "rén", "chī", "", "zì", "jǐ", "méi", "fèn", ""], "vi": "Chắc rồi. Mình còn mua một túi nhỏ cho cháu trai thím, kẻo cháu thấy người lớn ăn mà mình không có phần.", "en": "I will. I also bought a small bag for her grandson, so he wouldn't watch the adults eat and have none himself."}]}, {"n": 2, "zh": "对话：周末在山上踢球以后", "vi": "Hội thoại: Sau trận bóng trên núi cuối tuần", "en": "Dialogue: After a game of football in the hills at the weekend", "kw": ["成为", "发生", "放松", "回忆", "景色", "压力", "只要"], "lines": [{"s": "周南", "sp": ["zhōu", "nán"], "t": "上周日那场合球，踢完你还愿意再去吗？", "p": ["shàng", "zhōu", "rì", "nà", "chǎng", "hé", "qiú", "", "tī", "wán", "nǐ", "huán", "yuàn", "yì", "zài", "qù", "ma", ""], "vi": "Chủ nhật tuần trước trận bóng ấy, đá xong cậu còn muốn đi nữa không?", "en": "After that football game last Sunday, would you still go again?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "愿意。一到山上，城市里的压力好像都放下了。只要天气还行，我都想去。", "p": ["yuàn", "yì", "", "yí", "dào", "shān", "shàng", "", "chéng", "shì", "lǐ", "de", "yā", "lì", "hǎo", "xiàng", "dōu", "fàng", "xià", "le", "", "zhǐ", "yào", "tiān", "qì", "hái", "xíng", "", "wǒ", "dōu", "xiǎng", "qù", ""], "vi": "Muốn chứ. Vừa lên núi, áp lực trong thành phố như buông hết. Chỉ cần thời tiết còn ổn là mình muốn đi.", "en": "Yes. As soon as we got up into the hills, the pressure of the city seemed to fall away. As long as the weather is all right, I'll want to go."}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "中途还发生了一件有意思的事：球滚进草里，我们找了半天，结果旁边的景色倒成了最好看的一段。", "p": ["zhōng", "tú", "hái", "fā", "shēng", "le", "yí", "jiàn", "yǒu", "yì", "si", "de", "shì", "", "qiú", "gǔn", "jìn", "cǎo", "lǐ", "", "wǒ", "men", "zhǎo", "le", "bàn", "tiān", "", "jié", "guǒ", "páng", "biān", "de", "jǐng", "sè", "dào", "chéng", "le", "zuì", "hǎo", "kàn", "de", "yí", "duàn", ""], "vi": "Giữa chừng còn xảy ra một chuyện thú vị: bóng lăn vào cỏ, mình tìm mãi, hóa ra cảnh bên cạnh lại thành đoạn đẹp nhất.", "en": "Something interesting happened halfway through: the ball rolled into the grass, and we looked for it for a long time. In the end the scenery next to us turned out to be the best part."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "我现在一回忆，先想起的不是比分，是大家坐在石头上喝水、放松的样子。", "p": ["wǒ", "xiàn", "zài", "yì", "huí", "yì", "", "xiān", "xiǎng", "qǐ", "de", "bú", "shì", "bǐ", "fēn", "", "shì", "dà", "jiā", "zuò", "zài", "shí", "tou", "shàng", "hē", "shuǐ", "", "fàng", "sōng", "de", "yàng", "zi", ""], "vi": "Giờ mình vừa hồi tưởng, điều nhớ trước không phải tỉ số, mà là mọi người ngồi trên đá uống nước, thư giãn.", "en": "When I look back now, the first thing I recall is not the score, but everyone sitting on the rocks, drinking water and relaxing."}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "那就这么说定：下次还去。谁输了，谁买饮料。", "p": ["nà", "jiù", "zhè", "me", "shuō", "dìng", "", "xià", "cì", "hái", "qù", "", "shuí", "shū", "le", "", "shuí", "mǎi", "yǐn", "liào", ""], "vi": "Vậy chốt vậy: lần sau vẫn đi. Ai thua thì người ấy mua nước.", "en": "Then it's settled: we'll go again next time. Whoever loses buys the drinks."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "好。能成为每周一次的活动，也不错。", "p": ["hǎo", "", "néng", "chéng", "wéi", "měi", "zhōu", "yí", "cì", "de", "huó", "dòng", "", "yě", "bú", "cuò", ""], "vi": "Được. Trở thành hoạt động mỗi tuần một lần cũng hay.", "en": "All right. It wouldn't be bad if it became a once-a-week activity."}]}, {"n": 3, "zh": "对话：程师傅送阿玲去办事", "vi": "Hội thoại: Bác Trình đưa A Linh đi làm việc", "en": "Dialogue: Master Cheng drives A Linh on an errand", "kw": ["大使馆", "堵车", "距离", "耐心", "师傅"], "lines": [{"s": "程师傅", "sp": ["chéng", "shī", "fu"], "t": "姑娘，今天路上堵车，可能要比平时多花二十分钟。", "p": ["gū", "niáng", "", "jīn", "tiān", "lù", "shàng", "dǔ", "chē", "", "kě", "néng", "yào", "bǐ", "píng", "shí", "duō", "huā", "èr", "shí", "fēn", "zhōng", ""], "vi": "Cô gái, hôm nay đường tắc, có lẽ mất hơn bình thường hai mươi phút.", "en": "Miss, the traffic is jammed today. It may take twenty minutes more than usual."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "没关系，师傅。我去大使馆交材料，时间还来得及。", "p": ["méi", "guān", "xì", "", "shī", "fu", "", "wǒ", "qù", "dà", "shǐ", "guǎn", "jiāo", "cái", "liào", "", "shí", "jiān", "hái", "lái", "de", "jí", ""], "vi": "Không sao, bác. Em đến đại sứ quán nộp hồ sơ, thời gian vẫn kịp.", "en": "That's all right, Master. I'm going to the embassy to hand in some papers, and there's still time."}, {"s": "程师傅", "sp": ["chéng", "shī", "fu"], "t": "从这儿到大使馆距离不远，就是这几盏灯特别慢。您再耐心等一等。", "p": ["cóng", "zhè", "r", "dào", "dà", "shǐ", "guǎn", "jù", "lí", "bù", "yuǎn", "", "jiù", "shì", "zhè", "jǐ", "zhǎn", "dēng", "tè", "bié", "màn", "", "nín", "zài", "nài", "xīn", "děng", "yì", "děng", ""], "vi": "Từ đây tới đại sứ quán khoảng cách không xa, chỉ mấy đèn này chậm đặc biệt. Cô kiên nhẫn đợi thêm.", "en": "The distance from here to the embassy isn't far; it's just that these lights are especially slow. Please be patient a little longer."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "我就坐着看窗外。您开这么稳，我倒不着急了。", "p": ["wǒ", "jiù", "zuò", "zhe", "kàn", "chuāng", "wài", "", "nín", "kāi", "zhè", "me", "wěn", "", "wǒ", "dào", "bù", "zháo", "jí", "le", ""], "vi": "Em ngồi nhìn ra cửa sổ. Bác lái vững thế, em lại không nóng ruột nữa.", "en": "I'll just sit and look out of the window. You drive so steadily that I'm not in a hurry any more."}, {"s": "程师傅", "sp": ["chéng", "shī", "fu"], "t": "前头车一动，我们就走。您把材料放好，别掉了。", "p": ["qián", "tou", "chē", "yí", "dòng", "", "wǒ", "men", "jiù", "zǒu", "", "nín", "bǎ", "cái", "liào", "fàng", "hǎo", "", "bié", "diào", "le", ""], "vi": "Xe phía trước vừa nhúc, mình đi. Cô để hồ sơ cho chắc, đừng rơi.", "en": "As soon as the car in front moves, we'll go. Keep those papers safe so they don't fall."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "已经放进包里了。谢谢师傅。", "p": ["yǐ", "jīng", "fàng", "jìn", "bāo", "lǐ", "le", "", "xiè", "xiè", "shī", "fu", ""], "vi": "Để vào túi rồi. Cảm ơn bác.", "en": "They're already in my bag. Thank you, Master."}]}, {"n": 4, "zh": "短文：路边也能看见的东西", "vi": "Đoạn văn: Thứ cũng thấy được bên đường", "en": "Passage: Things you can also see by the roadside", "kw": ["到处", "缺少", "生命", "态度", "因此"], "lines": [{"s": "", "sp": [], "t": "以前我觉得美只在风景区里，后来才发现，它到处都是。楼下的老树，公交站那盆花，甚至雨后地上的一小摊水，都有自己的样子。生活并不缺少可看的东西，缺少的常常是停一下的态度。因此我现在出门会走得慢一些。不是每条路都有名，可每一条路上都有正在进行的生命。只要愿意看，平凡的早晨也能让人觉得不普通。", "p": ["yǐ", "qián", "wǒ", "jué", "de", "měi", "zhǐ", "zài", "fēng", "jǐng", "qū", "lǐ", "", "hòu", "lái", "cái", "fā", "xiàn", "", "tā", "dào", "chù", "dōu", "shì", "", "lóu", "xià", "de", "lǎo", "shù", "", "gōng", "jiāo", "zhàn", "nà", "pén", "huā", "", "shèn", "zhì", "yǔ", "hòu", "dì", "shàng", "de", "yì", "xiǎo", "tān", "shuǐ", "", "dōu", "yǒu", "zì", "jǐ", "de", "yàng", "zi", "", "shēng", "huó", "bìng", "bù", "quē", "shǎo", "kě", "kàn", "de", "dōng", "xi", "", "quē", "shǎo", "de", "cháng", "cháng", "shì", "tíng", "yí", "xià", "de", "tài", "dù", "", "yīn", "cǐ", "wǒ", "xiàn", "zài", "chū", "mén", "huì", "zǒu", "de", "màn", "yì", "xiē", "", "bú", "shì", "měi", "tiáo", "lù", "dōu", "yǒu", "míng", "", "kě", "měi", "yì", "tiáo", "lù", "shàng", "dōu", "yǒu", "zhèng", "zài", "jìn", "xíng", "de", "shēng", "mìng", "", "zhǐ", "yào", "yuàn", "yì", "kàn", "", "píng", "fán", "de", "zǎo", "chén", "yě", "néng", "ràng", "rén", "jué", "de", "bù", "pǔ", "tōng", ""], "vi": "Trước tôi nghĩ cái đẹp chỉ ở khu thắng cảnh, sau mới thấy nó ở khắp nơi. Cây già dưới nhà, chậu hoa ở trạm xe, thậm chí một vũng nước nhỏ trên đất sau cơn mưa, đều có dáng của mình. Cuộc sống không thiếu thứ đáng nhìn, cái thường thiếu là thái độ dừng lại một chút. Vì thế giờ tôi ra khỏi cửa đi chậm hơn. Không phải con đường nào cũng nổi tiếng, nhưng đường nào cũng có sự sống đang diễn ra. Chỉ cần muốn nhìn, một sáng bình thường cũng có thể khiến người ta thấy không tầm thường.", "en": "I used to feel that beauty existed only in scenic spots. Later I found that it is everywhere. The old tree downstairs, the pot of flowers at the bus stop, even a small puddle on the ground after rain, each has a look of its own. Life does not lack things worth looking at; what is often lacking is the attitude of pausing for a moment. Therefore I now walk a little more slowly when I go out. Not every road is famous, but on every road there is life going on. If you are willing to look, an ordinary morning can also feel uncommon."}]}, {"n": 5, "zh": "短文：阳光下的好心情，也要自己找", "vi": "Đoạn văn: Tâm trạng tốt dưới ánh nắng cũng cần tự tìm", "en": "Passage: A good mood in the sunshine is also something you find for yourself", "kw": ["积极", "科学", "特点", "往往", "阳光", "证明"], "lines": [{"s": "", "sp": [], "t": "有人说，心情好不好，要看当天有没有阳光。这话只说对了一半。科学研究并不能证明每一个晴天都会让人愉快，它只能说明：阳光往往使人更想出门。真正起作用的，是你出不出去、跟谁说话、用什么样的态度对待麻烦。积极的人有一个特点，不是从不遇到烦事，而是遇到了还肯再试一次。心情不会从天上掉下来，可它会在你迈出门的那一步里慢慢出现。", "p": ["yǒu", "rén", "shuō", "", "xīn", "qíng", "hǎo", "bù", "hǎo", "", "yào", "kàn", "dàng", "tiān", "yǒu", "méi", "yǒu", "yáng", "guāng", "", "zhè", "huà", "zhǐ", "shuō", "duì", "le", "yí", "bàn", "", "kē", "xué", "yán", "jiū", "bìng", "bù", "néng", "zhèng", "míng", "měi", "yí", "gè", "qíng", "tiān", "dōu", "huì", "ràng", "rén", "yú", "kuài", "", "tā", "zhǐ", "néng", "shuō", "míng", "", "yáng", "guāng", "wǎng", "wǎng", "shǐ", "rén", "gèng", "xiǎng", "chū", "mén", "", "zhēn", "zhèng", "qǐ", "zuò", "yòng", "de", "", "shì", "nǐ", "chū", "bù", "chū", "qù", "", "gēn", "shuí", "shuō", "huà", "", "yòng", "shén", "me", "yàng", "de", "tài", "dù", "duì", "dài", "má", "fan", "", "jī", "jí", "de", "rén", "yǒu", "yí", "gè", "tè", "diǎn", "", "bú", "shì", "cóng", "bú", "yù", "dào", "fán", "shì", "", "ér", "shì", "yù", "dào", "le", "hái", "kěn", "zài", "shì", "yí", "cì", "", "xīn", "qíng", "bú", "huì", "cóng", "tiān", "shàng", "diào", "xià", "lái", "", "kě", "tā", "huì", "zài", "nǐ", "mài", "chū", "mén", "de", "nà", "yí", "bù", "lǐ", "màn", "màn", "chū", "xiàn", ""], "vi": "Có người nói tâm trạng tốt hay không là nhìn hôm ấy có ánh nắng hay không. Câu ấy đúng có một nửa. Nghiên cứu khoa học không thể chứng minh ngày nắng nào cũng làm người ta vui, nó chỉ cho thấy: ánh nắng thường khiến người ta muốn ra khỏi cửa hơn. Điều thật sự có tác dụng là bạn có ra ngoài không, nói với ai, lấy thái độ thế nào trước chuyện phiền. Người tích cực có một đặc điểm, không phải không gặp chuyện buồn, mà gặp rồi vẫn chịu thử thêm lần nữa. Tâm trạng không rơi từ trên trời, nhưng nó sẽ dần xuất hiện trong bước bạn bước ra cửa.", "en": "Some people say whether you are in a good mood depends on whether there is sunshine that day. That is only half right. Scientific research cannot prove that every clear day will make a person cheerful; it can only show that sunshine often makes people more inclined to go out. What really makes a difference is whether you go out, who you talk to, and what attitude you take toward trouble. A positive person has one characteristic: it is not that they never meet anything annoying, but that when they do, they are still willing to try once more. A mood will not fall from the sky, but it will slowly appear in the step you take out of the door."}]}]}, {"l": 9, "texts": [{"n": 1, "zh": "对话：小雪又为零食发愁", "vi": "Hội thoại: Tiểu Tuyết lại lo vì đồ ăn vặt", "en": "Dialogue: Xiaoxue is worried about snacks again", "kw": ["饼干", "放弃", "坚持", "难道", "主意", "得"], "lines": [{"s": "阿玲", "sp": ["ā", "líng"], "t": "你怎么把饼干放到柜子最上面了？", "p": ["nǐ", "zěn", "me", "bǎ", "bǐng", "gān", "fàng", "dào", "guì", "zi", "zuì", "shàng", "miàn", "le", ""], "vi": "Sao cậu để bánh quy lên tầng cao nhất của tủ?", "en": "Why have you put the biscuits on the very top shelf of the cupboard?"}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "我得少吃点儿。一打开包装就停不下来，我难道还要每周都后悔一次吗？", "p": ["wǒ", "děi", "shǎo", "chī", "diǎn", "r", "", "yì", "dǎ", "kāi", "bāo", "zhuāng", "jiù", "tíng", "bú", "xià", "lái", "", "wǒ", "nán", "dào", "hái", "yào", "měi", "zhōu", "dōu", "hòu", "huǐ", "yí", "cì", "ma", ""], "vi": "Mình phải ăn ít thôi. Hễ mở gói là không dừng được, chẳng lẽ tuần nào cũng phải hối một lần sao?", "en": "I have to eat a little less. Once I open a pack I can't stop. Do I really have to regret it every week?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "那你就一下子放弃所有零食？怕是坚持不了几天。", "p": ["nà", "nǐ", "jiù", "yí", "xià", "zi", "fàng", "qì", "suǒ", "yǒu", "líng", "shí", "", "pà", "shì", "jiān", "chí", "bù", "liǎo", "jǐ", "tiān", ""], "vi": "Vậy cậu bỏ hết mọi món vặt một lúc? E không kiên trì được vài ngày.", "en": "So you're going to give up all snacks in one go? I'm afraid you won't last more than a few days."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "我也这么想。你有没有更好的主意？", "p": ["wǒ", "yě", "zhè", "me", "xiǎng", "", "nǐ", "yǒu", "méi", "yǒu", "gèng", "hǎo", "de", "zhǔ", "yi", ""], "vi": "Mình cũng nghĩ vậy. Cậu có ý hay hơn không?", "en": "I think so too. Have you got a better idea?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "每天只留两块饼干，其余的先不买。想吃的时候先喝杯水，再决定还要不要打开柜子。", "p": ["měi", "tiān", "zhǐ", "liú", "liǎng", "kuài", "bǐng", "gān", "", "qí", "yú", "de", "xiān", "bù", "mǎi", "", "xiǎng", "chī", "de", "shí", "hòu", "xiān", "hē", "bēi", "shuǐ", "", "zài", "jué", "dìng", "hái", "yào", "bú", "yào", "dǎ", "kāi", "guì", "zi", ""], "vi": "Mỗi ngày chỉ để lại hai cái bánh, còn lại đừng mua vội. Lúc muốn ăn thì uống một ly nước đã, rồi mới quyết có mở tủ hay không.", "en": "Keep only two biscuits each day, and don't buy the rest for now. When you want some, drink a glass of water first, and then decide whether to open the cupboard."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "这主意我可以试试。从今天开始，我得坚持两周看看。", "p": ["zhè", "zhǔ", "yi", "wǒ", "kě", "yǐ", "shì", "shì", "", "cóng", "jīn", "tiān", "kāi", "shǐ", "", "wǒ", "děi", "jiān", "chí", "liǎng", "zhōu", "kàn", "kàn", ""], "vi": "Ý này mình thử được. Từ hôm nay, mình phải kiên trì hai tuần xem sao.", "en": "I can try that idea. Starting today, I have to keep it up for two weeks and see."}]}, {"n": 2, "zh": "对话：周南的网球又赢了", "vi": "Hội thoại: Châu Nam lại thắng trận quần vợt", "en": "Dialogue: Zhou Nan has won at tennis again", "kw": ["国际", "轻松", "随便", "通过", "网球", "汗", "赢"], "lines": [{"s": "阿玲", "sp": ["ā", "líng"], "t": "看你衬衫都湿了，刚打完网球？", "p": ["kàn", "nǐ", "chèn", "shān", "dōu", "shī", "le", "", "gāng", "dǎ", "wán", "wǎng", "qiú", ""], "vi": "Áo cậu ướt hết, vừa đánh quần vợt xong à?", "en": "Your shirt is soaked — have you just finished tennis?"}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "对。今天赢了两局，汗都来不及擦。不过真不轻松，对方也是校队的。", "p": ["duì", "", "jīn", "tiān", "yíng", "le", "liǎng", "jú", "", "hàn", "dōu", "lái", "bu", "jí", "cā", "", "bú", "guò", "zhēn", "bù", "qīng", "sōng", "", "duì", "fāng", "yě", "shì", "xiào", "duì", "de", ""], "vi": "Đúng. Hôm nay thắng hai ván, mồ hôi còn chưa kịp lau. Nhưng chẳng thoải mái gì, đối phương cũng là đội trường.", "en": "Yes. I won two sets today, and I had no time to wipe the sweat. But it was really not easy. The other player is on the school team too."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "你怎么进步这么快？是不是有什么特别的方法？", "p": ["nǐ", "zěn", "me", "jìn", "bù", "zhè", "me", "kuài", "", "shì", "bú", "shì", "yǒu", "shén", "me", "tè", "bié", "de", "fāng", "fǎ", ""], "vi": "Sao cậu tiến bộ nhanh thế? Có cách gì đặc biệt không?", "en": "How have you improved so quickly? Is there some special method?"}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "没有什么随便就能赢的办法。我每周通过三次训练，把基本动作练熟，再看一些国际比赛的录像。", "p": ["méi", "yǒu", "shén", "me", "suí", "biàn", "jiù", "néng", "yíng", "de", "bàn", "fǎ", "", "wǒ", "měi", "zhōu", "tōng", "guò", "sān", "cì", "xùn", "liàn", "", "bǎ", "jī", "běn", "dòng", "zuò", "liàn", "shú", "", "zài", "kàn", "yì", "xiē", "guó", "jì", "bǐ", "sài", "de", "lù", "xiàng", ""], "vi": "Không có cách nào tùy tiện là thắng. Mỗi tuần mình trải ba buổi tập, luyện thuần động tác cơ bản, rồi xem vài băng giải quốc tế.", "en": "There is no way to win just casually. I get through three training sessions a week, practise the basic movements until they're familiar, and also watch some recordings of international matches."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "听着就累。你下次练习，我可不可以去看看？", "p": ["tīng", "zhe", "jiù", "lèi", "", "nǐ", "xià", "cì", "liàn", "xí", "", "wǒ", "kě", "bù", "kě", "yǐ", "qù", "kàn", "kàn", ""], "vi": "Nghe đã thấy mệt. Lần sau cậu tập, mình có thể đến xem được không?", "en": "It sounds tiring already. May I come and watch next time you practise?"}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "可以。你要是也想试试，我借你一副球拍。", "p": ["kě", "yǐ", "", "nǐ", "yào", "shi", "yě", "xiǎng", "shì", "shì", "", "wǒ", "jiè", "nǐ", "yí", "fù", "qiú", "pāi", ""], "vi": "Được. Nếu cậu cũng muốn thử, mình cho mượn một vợt.", "en": "Yes. If you'd like to try as well, I'll lend you a racket."}]}, {"n": 3, "zh": "对话：陈晓想当作家", "vi": "Hội thoại: Trần Hiểu muốn làm nhà văn", "en": "Dialogue: Chen Xiao wants to be a writer", "kw": ["当时", "可是", "理想", "正确", "作家", "篇"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "陈晓又在本子上写什么？都这么晚了。", "p": ["chén", "xiǎo", "yòu", "zài", "běn", "zi", "shàng", "xiě", "shén", "me", "", "dōu", "zhè", "me", "wǎn", "le", ""], "vi": "Trần Hiểu lại viết gì trong sổ thế? Muộn vậy rồi.", "en": "What's Chen Xiao writing in his notebook again? It's so late."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "一篇短故事。他的理想是以后做作家，可是现在写得很慢，一篇要改很多遍。", "p": ["yī", "piān", "duǎn", "gù", "shì", "", "tā", "de", "lǐ", "xiǎng", "shì", "yǐ", "hòu", "zuò", "zuò", "jiā", "", "kě", "shì", "xiàn", "zài", "xiě", "de", "hěn", "màn", "", "yì", "piān", "yào", "gǎi", "hěn", "duō", "biàn", ""], "vi": "Một truyện ngắn. Lý tưởng của anh ấy là sau này làm nhà văn, nhưng giờ viết rất chậm, một bài phải sửa rất nhiều lần.", "en": "A short story. His ideal is to become a writer one day, but he writes very slowly now, and a single piece has to be revised many times."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "当时他不是说先找一份稳定的工作吗？", "p": ["dāng", "shí", "tā", "bú", "shì", "shuō", "xiān", "zhǎo", "yí", "fèn", "wěn", "dìng", "de", "gōng", "zuò", "ma", ""], "vi": "Lúc ấy chẳng phải anh ấy nói tìm một việc ổn định trước sao?", "en": "Didn't he say at the time that he would find a steady job first?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "他说那也正确，晚上和周末仍然可以写。这样生活和理想都能顾上。", "p": ["tā", "shuō", "nà", "yě", "zhèng", "què", "", "wǎn", "shàng", "hé", "zhōu", "mò", "réng", "rán", "kě", "yǐ", "xiě", "", "zhè", "yàng", "shēng", "huó", "hé", "lǐ", "xiǎng", "dōu", "néng", "gù", "shàng", ""], "vi": "Anh ấy bảo điều đó cũng đúng, tối và cuối tuần vẫn viết được. Như vậy đời sống và lý tưởng đều giữ được.", "en": "He said that was correct too, and that he could still write in the evenings and at weekends. That way he can look after both his life and his ideal."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "那倒实在。等他写完这篇，我们帮忙看看。", "p": ["nà", "dào", "shí", "zài", "", "děng", "tā", "xiě", "wán", "zhè", "piān", "", "wǒ", "men", "bāng", "máng", "kàn", "kàn", ""], "vi": "Thế thì thực tế. Đợi anh ấy viết xong bài này, mình xem giúp.", "en": "That's practical. When he finishes this piece, we can help by reading it."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "他已经答应了。他说最怕写完没人读。", "p": ["tā", "yǐ", "jīng", "dā", "yìng", "le", "", "tā", "shuō", "zuì", "pà", "xiě", "wán", "méi", "rén", "dú", ""], "vi": "Anh ấy đã đồng ý. Anh ấy bảo sợ nhất là viết xong chẳng ai đọc.", "en": "He's already agreed. He said what he fears most is finishing a piece and having no one read it."}]}, {"n": 4, "zh": "短文：一次陶艺课给我的总结", "vi": "Đoạn văn: Một bài tổng kết từ giờ gốm", "en": "Passage: A summary a pottery class gave me", "kw": ["过程", "结果", "失败", "勇敢", "至少", "总结"], "lines": [{"s": "", "sp": [], "t": "第一次上陶艺课，我满心想做出一只漂亮的杯子。结果杯子歪了，还裂了一道。我当时觉得这就是失败。老师却让我把过程再走一遍：土要揉匀，手要稳，火也不能太急。第二次仍然不完美，可至少不再裂开。后来我给自己做了一个总结：结果当然重要，可真正让人进步的，是你敢在失败以后再勇敢地坐回去，把每一步重新做认真。那只歪杯子我还留着，为的是记得那一课。", "p": ["dì", "yī", "cì", "shàng", "táo", "yì", "kè", "", "wǒ", "mǎn", "xīn", "xiǎng", "zuò", "chū", "yì", "zhī", "piào", "liàng", "de", "bēi", "zi", "", "jié", "guǒ", "bēi", "zi", "wāi", "le", "", "hái", "liè", "le", "yí", "dào", "", "wǒ", "dāng", "shí", "jué", "de", "zhè", "jiù", "shì", "shī", "bài", "", "lǎo", "shī", "què", "ràng", "wǒ", "bǎ", "guò", "chéng", "zài", "zǒu", "yí", "biàn", "", "tǔ", "yào", "róu", "yún", "", "shǒu", "yào", "wěn", "", "huǒ", "yě", "bù", "néng", "tài", "jí", "", "dì", "èr", "cì", "réng", "rán", "bù", "wán", "měi", "", "kě", "zhì", "shǎo", "bú", "zài", "liè", "kāi", "", "hòu", "lái", "wǒ", "gěi", "zì", "jǐ", "zuò", "le", "yí", "gè", "zǒng", "jié", "", "jié", "guǒ", "dāng", "rán", "zhòng", "yào", "", "kě", "zhēn", "zhèng", "ràng", "rén", "jìn", "bù", "de", "", "shì", "nǐ", "gǎn", "zài", "shī", "bài", "yǐ", "hòu", "zài", "yǒng", "gǎn", "dì", "zuò", "huí", "qù", "", "bǎ", "měi", "yí", "bù", "chóng", "xīn", "zuò", "rèn", "zhēn", "", "nà", "zhǐ", "wāi", "bēi", "zi", "wǒ", "hái", "liú", "zhe", "", "wèi", "de", "shì", "jì", "de", "nà", "yí", "kè", ""], "vi": "Lần đầu học gốm, tôi chỉ nghĩ làm cho được một cái cốc đẹp. Kết quả cốc lệch, lại nứt một đường. Lúc ấy tôi thấy đó là thất bại. Giáo viên lại bảo tôi đi lại quá trình: đất phải nhào đều, tay phải vững, lửa cũng đừng vội. Lần hai vẫn chưa hoàn hảo, nhưng ít nhất không nứt nữa. Sau tôi tự viết một bài tổng kết: kết quả cố nhiên quan trọng, nhưng điều thật sự giúp người ta tiến bộ là dám, sau thất bại, dũng cảm ngồi lại, làm lại từng bước cho tử tế. Cái cốc lệch ấy tôi vẫn giữ, để nhớ buổi học đó.", "en": "The first time I went to a pottery class, all I wanted was to make a handsome cup. The result was that the cup came out crooked and also cracked along one line. At the time I felt that this was failure. The teacher, however, had me go through the process again: the clay had to be kneaded evenly, the hands had to be steady, and the fire could not be too hasty. The second try was still not perfect, but at least it no longer cracked. Later I wrote a summary for myself: the result is important, of course, but what really helps you improve is daring, after a failure, to sit back down bravely and do each step carefully once more. I still keep that crooked cup, so that I will remember the lesson."}]}, {"n": 5, "zh": "短文：暂时落后的时候", "vi": "Đoạn văn: Lúc tạm thời bị tụt lại", "en": "Passage: When you are temporarily behind", "kw": ["经历", "区别", "许多", "暂时", "取"], "lines": [{"s": "", "sp": [], "t": "比赛或考试里，暂时落后是许多人都会有的经历。有人一看见分数不高就停手，有人却会先看别人好在哪里，再取其中对自己有用的一点。这两种态度的区别，不在聪不聪明，而在你还肯不肯再看一眼自己的练习。我以前也急着跟前面的人比，后来才发现，许多弯路都是自己走出来的。把别人的方法取来试一试，再把不适合的放下，路会安静得多。", "p": ["bǐ", "sài", "huò", "kǎo", "shì", "lǐ", "", "zàn", "shí", "luò", "hòu", "shì", "xǔ", "duō", "rén", "dōu", "huì", "yǒu", "de", "jīng", "lì", "", "yǒu", "rén", "yí", "kàn", "jiàn", "fēn", "shù", "bù", "gāo", "jiù", "tíng", "shǒu", "", "yǒu", "rén", "què", "huì", "xiān", "kàn", "bié", "rén", "hǎo", "zài", "nǎ", "lǐ", "", "zài", "qǔ", "qí", "zhōng", "duì", "zì", "jǐ", "yǒu", "yòng", "de", "yì", "diǎn", "", "zhè", "liǎng", "zhǒng", "tài", "dù", "de", "qū", "bié", "", "bú", "zài", "cōng", "bù", "cōng", "míng", "", "ér", "zài", "nǐ", "hái", "kěn", "bù", "kěn", "zài", "kàn", "yì", "yǎn", "zì", "jǐ", "de", "liàn", "xí", "", "wǒ", "yǐ", "qián", "yě", "jí", "zhe", "gēn", "qián", "miàn", "de", "rén", "bǐ", "", "hòu", "lái", "cái", "fā", "xiàn", "", "xǔ", "duō", "wān", "lù", "dōu", "shì", "zì", "jǐ", "zǒu", "chū", "lái", "de", "", "bǎ", "bié", "rén", "de", "fāng", "fǎ", "qǔ", "lái", "shì", "yí", "shì", "", "zài", "bǎ", "bú", "shì", "hé", "de", "fàng", "xià", "", "lù", "huì", "ān", "jìng", "de", "duō", ""], "vi": "Trong thi đấu hay kỳ thi, việc tạm thời bị tụt lại là trải nghiệm nhiều người đều có. Có người vừa thấy điểm không cao đã dừng tay, có người lại nhìn người khác hay ở chỗ nào, rồi lấy một điểm hữu ích cho mình. Sự khác nhau của hai thái độ ấy không ở thông minh hay không, mà ở chỗ bạn còn chịu nhìn lại bài tập của mình hay không. Trước tôi cũng sốt ruột so với người đi trước, sau mới thấy nhiều đoạn vòng là tự mình đi ra. Lấy cách của người khác về thử, rồi đặt xuống những gì không hợp, đường sẽ yên hơn nhiều.", "en": "In a contest or an exam, being temporarily behind is an experience many people have. Some people stop as soon as they see a low score; others first look at what someone else does well, and then take from it one point that is useful to themselves. The difference between these two attitudes is not about how clever you are, but about whether you are still willing to look at your own practice once more. I used to be in a hurry to compare myself with the people in front; only later did I find that many of the detours were ones I had taken myself. If you take other people's methods and try them, and then put down what does not suit you, the road becomes much quieter."}]}]}, {"l": 10, "texts": [{"n": 1, "zh": "对话：礼拜天阿玲陪母亲出门", "vi": "Hội thoại: Ngày chủ nhật A Linh đi cùng mẹ", "en": "Dialogue: On Sunday A Linh goes out with her mother", "kw": ["礼拜天", "不过", "方向", "空儿", "母亲", "永远"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "今天礼拜天，你怎么起得这么早？", "p": ["jīn", "tiān", "lǐ", "bài", "tiān", "", "nǐ", "zěn", "me", "qǐ", "de", "zhè", "me", "zǎo", ""], "vi": "Hôm nay chủ nhật, sao cậu dậy sớm thế?", "en": "It's Sunday today — why did you get up so early?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "我陪母亲去公园。她说平时没什么空儿，只有这一天走得比较慢。", "p": ["wǒ", "péi", "mǔ", "qin", "qù", "gōng", "yuán", "", "tā", "shuō", "píng", "shí", "méi", "shén", "me", "kòng", "r", "", "zhǐ", "yǒu", "zhè", "yì", "tiān", "zǒu", "de", "bǐ", "jiào", "màn", ""], "vi": "Mình đi công viên với mẹ. Mẹ bảo bình thường chẳng có chút thì giờ nào, chỉ ngày này đi chậm hơn được.", "en": "I'm going to the park with my mother. She says she doesn't usually have a spare moment, and only on this day can she walk a little more slowly."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "那挺好。你们还去别的地方吗？", "p": ["nà", "tǐng", "hǎo", "", "nǐ", "men", "hái", "qù", "bié", "de", "dì", "fāng", "ma", ""], "vi": "Thế thì hay. Hai mẹ con còn đi chỗ khác nữa không?", "en": "That's nice. Are you going anywhere else as well?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "先往湖那边走。不过要是太阳太大，我们就换个方向，去有树荫的那条路。", "p": ["xiān", "wǎng", "hú", "nà", "biān", "zǒu", "", "bú", "guò", "yào", "shi", "tài", "yáng", "tài", "dà", "", "wǒ", "men", "jiù", "huàn", "gè", "fāng", "xiàng", "", "qù", "yǒu", "shù", "yīn", "de", "nà", "tiáo", "lù", ""], "vi": "Đi về phía hồ trước. Nhưng nếu nắng quá thì mình đổi hướng, sang con đường có bóng cây.", "en": "We'll head toward the lake first. But if the sun is too strong, we'll change direction and take the path with the tree shade."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "替我问阿姨好。她做的汤，我永远都记得。", "p": ["tì", "wǒ", "wèn", "ā", "yí", "hǎo", "", "tā", "zuò", "de", "tāng", "", "wǒ", "yǒng", "yuǎn", "dōu", "jì", "de", ""], "vi": "Nhờ cậu hỏi thăm thím. Món canh thím nấu, mình nhớ mãi.", "en": "Please say hello to your mother for me. I'll always remember the soup she makes."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "一定。晚上要是你有空儿，来家里喝一碗。", "p": ["yī", "dìng", "", "wǎn", "shàng", "yào", "shi", "nǐ", "yǒu", "kòng", "r", "", "lái", "jiā", "lǐ", "hē", "yì", "wǎn", ""], "vi": "Chắc rồi. Tối nếu cậu rảnh, đến nhà uống một bát.", "en": "I will. If you have a moment this evening, come over to the house for a bowl."}]}, {"n": 2, "zh": "对话：两位老师谈同事的新消息", "vi": "Hội thoại: Hai giáo viên nói về tin mới của đồng nghiệp", "en": "Dialogue: Two teachers talk about a colleague's news", "kw": ["翻译", "确实", "硕士", "兴奋", "优秀", "拉"], "lines": [{"s": "赵老师", "sp": ["zhào", "lǎo", "shī"], "t": "林老师，您听说了吗？王老师的硕士论文通过了。", "p": ["lín", "lǎo", "shī", "", "nín", "tīng", "shuō", "le", "ma", "", "wáng", "lǎo", "shī", "de", "shuò", "shì", "lùn", "wén", "tōng", "guò", "le", ""], "vi": "Thầy Lâm, thầy nghe tin chưa? Cô Vương đã bảo vệ xong luận văn thạc sĩ.", "en": "Mr. Lin, have you heard? Ms. Wang's master's thesis has been passed."}, {"s": "林老师", "sp": ["lín", "lǎo", "shī"], "t": "听说了。她研究的是翻译，课又上得好，确实优秀。", "p": ["tīng", "shuō", "le", "", "tā", "yán", "jiū", "de", "shì", "fān", "yì", "", "kè", "yòu", "shàng", "de", "hǎo", "", "què", "shí", "yōu", "xiù", ""], "vi": "Nghe rồi. Cô ấy nghiên cứu biên dịch, dạy cũng giỏi, quả thật xuất sắc.", "en": "I have. She works on translation, and she teaches well too. She is excellent, she really is."}, {"s": "赵老师", "sp": ["zhào", "lǎo", "shī"], "t": "消息一传开，办公室里都兴奋起来。下午她还要拉一段小提琴给大家听。", "p": ["xiāo", "xi", "yì", "chuán", "kāi", "", "bàn", "gōng", "shì", "lǐ", "dōu", "xīng", "fèn", "qǐ", "lái", "", "xià", "wǔ", "tā", "hái", "yào", "lā", "yí", "duàn", "xiǎo", "tí", "qín", "gěi", "dà", "jiā", "tīng", ""], "vi": "Tin vừa loan, cả phòng đều hào hứng. Chiều cô ấy còn kéo một khúc vĩ cầm cho mọi người nghe.", "en": "As soon as the news spread, the whole office got excited. This afternoon she is even going to play a piece on the violin for everyone."}, {"s": "林老师", "sp": ["lín", "lǎo", "shī"], "t": "那我一定去。她一拉琴，整个楼道都安静了。", "p": ["nà", "wǒ", "yí", "dìng", "qù", "", "tā", "yì", "lā", "qín", "", "zhěng", "gè", "lóu", "dào", "dōu", "ān", "jìng", "le", ""], "vi": "Thế thì tôi nhất định đến. Cô ấy vừa kéo đàn là cả hành lang im hết.", "en": "Then I shall certainly go. As soon as she starts to play, the whole corridor goes quiet."}, {"s": "赵老师", "sp": ["zhào", "lǎo", "shī"], "t": "是啊。能把课、论文和琴都照顾好，真不容易。", "p": ["shì", "a", "", "néng", "bǎ", "kè", "", "lùn", "wén", "hé", "qín", "dōu", "zhào", "gù", "hǎo", "", "zhēn", "bù", "róng", "yì", ""], "vi": "Phải. Giữ được cả giờ dạy, luận văn lẫn đàn, thật không dễ.", "en": "Yes. Managing to look after her classes, her thesis and the violin is really not easy."}, {"s": "林老师", "sp": ["lín", "lǎo", "shī"], "t": "我们准备一束花吧，让她一进门就能看见。", "p": ["wǒ", "men", "zhǔn", "bèi", "yí", "shù", "huā", "ba", "", "ràng", "tā", "yí", "jìn", "mén", "jiù", "néng", "kàn", "jiàn", ""], "vi": "Mình chuẩn bị một bó hoa, để cô ấy vừa vào cửa đã thấy.", "en": "Let's get a bunch of flowers ready, so she can see them as soon as she comes in."}]}, {"n": 3, "zh": "对话：陈晓为将来的工作发愁", "vi": "Hội thoại: Trần Hiểu lo việc làm cho tương lai", "en": "Dialogue: Chen Xiao worries about a job for the future", "kw": ["发展", "关键", "建议", "将来", "职业", "困", "躺"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "陈晓中午怎么不吃饭，躺在宿舍里？", "p": ["chén", "xiǎo", "zhōng", "wǔ", "zěn", "me", "bù", "chī", "fàn", "", "tǎng", "zài", "sù", "shè", "lǐ", ""], "vi": "Buổi trưa Trần Hiểu sao không ăn, nằm trong ký túc xá?", "en": "Why didn't Chen Xiao have lunch? Why is he lying in the dorm?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "他昨晚想将来的职业，想得太困了，今早又爬起来改简历。", "p": ["tā", "zuó", "wǎn", "xiǎng", "jiāng", "lái", "de", "zhí", "yè", "", "xiǎng", "de", "tài", "kùn", "le", "", "jīn", "zǎo", "yòu", "pá", "qǐ", "lái", "gǎi", "jiǎn", "lì", ""], "vi": "Tối qua cậu ấy nghĩ về nghề nghiệp tương lai, nghĩ đến mệt rũ, sáng lại dậy sửa sơ yếu lý lịch.", "en": "Last night he was thinking about a future career until he was too sleepy, and this morning he got up again to revise his CV."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "他有没有方向？", "p": ["tā", "yǒu", "méi", "yǒu", "fāng", "xiàng", ""], "vi": "Cậu ấy đã có hướng chưa?", "en": "Does he have a direction?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "有两个选择，一个偏研究，一个偏语言。我建议他先问清楚，这两个方向以后怎么发展。", "p": ["yǒu", "liǎng", "gè", "xuǎn", "zé", "", "yí", "gè", "piān", "yán", "jiū", "", "yí", "gè", "piān", "yǔ", "yán", "", "wǒ", "jiàn", "yì", "tā", "xiān", "wèn", "qīng", "chǔ", "", "zhè", "liǎng", "gè", "fāng", "xiàng", "yǐ", "hòu", "zěn", "me", "fā", "zhǎn", ""], "vi": "Có hai lựa chọn, một thiên về nghiên cứu, một thiên về ngôn ngữ. Mình khuyên cậu ấy hỏi rõ hai hướng ấy sau này phát triển thế nào.", "en": "There are two options, one more toward research and one more toward language. I suggested he first find out clearly how those two directions might develop later on."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "关键是他自己喜欢哪一种，别只看工资。", "p": ["guān", "jiàn", "shì", "tā", "zì", "jǐ", "xǐ", "huān", "nǎ", "yì", "zhǒng", "", "bié", "zhǐ", "kàn", "gōng", "zī", ""], "vi": "Điều then chốt là bản thân cậu ấy thích loại nào, đừng chỉ nhìn lương.", "en": "The key is which kind he himself likes, not to look only at the pay."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "对。等他起来，我们再一起帮他看看那两份介绍。", "p": ["duì", "", "děng", "tā", "qǐ", "lái", "", "wǒ", "men", "zài", "yì", "qǐ", "bāng", "tā", "kàn", "kàn", "nà", "liǎng", "fèn", "jiè", "shào", ""], "vi": "Đúng. Đợi cậu ấy dậy, mình cùng xem giúp hai bản giới thiệu ấy.", "en": "That's right. When he gets up, we'll go through those two descriptions with him."}]}, {"n": 4, "zh": "短文：小店门口的一句话", "vi": "Đoạn văn: Một câu trước cửa tiệm nhỏ", "en": "Passage: A sentence at the door of a little shop", "kw": ["经济", "条件", "由于", "等", "富", "穷"], "lines": [{"s": "", "sp": [], "t": "社区口有一家小文具店。老板并不富，也不觉得自己穷。由于店面不大，纸、笔、本子等常用的东西他都会进，但不进太贵的。有学生问他：“现在经济条件好的人很多，您不着急扩大吗？”他笑着说：“我得先让到这儿的人买得安心。条件会变，急着变富，容易把该做的事放下。”我听完在门口站了一下。钱当然重要，可把眼前的事做稳，也是一种踏实。", "p": ["shè", "qū", "kǒu", "yǒu", "yì", "jiā", "xiǎo", "wén", "jù", "diàn", "", "lǎo", "bǎn", "bìng", "bú", "fù", "", "yě", "bù", "jué", "de", "zì", "jǐ", "qióng", "", "yóu", "yú", "diàn", "miàn", "bú", "dà", "", "zhǐ", "", "bǐ", "", "běn", "zi", "děng", "cháng", "yòng", "de", "dōng", "xi", "tā", "dōu", "huì", "jìn", "", "dàn", "bú", "jìn", "tài", "guì", "de", "", "yǒu", "xué", "shēng", "wèn", "tā", "", "", "xiàn", "zài", "jīng", "jì", "tiáo", "jiàn", "hǎo", "de", "rén", "hěn", "duō", "", "nín", "bù", "zháo", "jí", "kuò", "dà", "ma", "", "", "tā", "xiào", "zhe", "shuō", "", "", "wǒ", "děi", "xiān", "ràng", "dào", "zhè", "r", "de", "rén", "mǎi", "de", "ān", "xīn", "", "tiáo", "jiàn", "huì", "biàn", "", "jí", "zhe", "biàn", "fù", "", "róng", "yì", "bǎ", "gāi", "zuò", "de", "shì", "fàng", "xià", "", "", "wǒ", "tīng", "wán", "zài", "mén", "kǒu", "zhàn", "le", "yí", "xià", "", "qián", "dāng", "rán", "zhòng", "yào", "", "kě", "bǎ", "yǎn", "qián", "de", "shì", "zuò", "wěn", "", "yě", "shì", "yì", "zhǒng", "tā", "shi", ""], "vi": "Ở cửa khu có một tiệm văn phòng phẩm nhỏ. Ông chủ không giàu, cũng không thấy mình nghèo. Vì cửa tiệm không lớn, giấy, bút, vở và những thứ dùng thường ông đều nhập, nhưng không nhập đồ quá đắt. Có học sinh hỏi: «Giờ nhiều người điều kiện kinh tế tốt, bác không sốt ruột mở rộng sao?» Ông cười: «Tôi phải để người đến đây mua cho yên đã. Điều kiện sẽ đổi, vội giàu thì dễ đặt xuống việc phải làm.» Tôi nghe xong đứng trước cửa một chút. Tiền cố nhiên quan trọng, nhưng làm vững việc trước mắt cũng là một sự chắc chắn.", "en": "There is a little stationery shop at the entrance to the neighbourhood. The owner is not rich, and he does not feel poor either. Because the shop is not large, he stocks paper, pens, notebooks and other everyday things, but he does not stock anything too expensive. A student once asked him, \"Plenty of people have good economic conditions now. Aren't you in a hurry to expand?\" He smiled and said, \"I have to make sure the people who come here can buy with peace of mind first. Conditions will change, and if you rush to get rich, it is easy to put down the work you ought to be doing.\" I stood at the door for a moment after I heard that. Money is important, of course, but doing the work in front of you steadily is also a kind of firmness."}]}, {"n": 5, "zh": "短文：黑板上的几种答案", "vi": "Đoạn văn: Vài lời đáp trên bảng", "en": "Passage: A few answers on the blackboard", "kw": ["比如", "答案", "橡皮", "低", "糖"], "lines": [{"s": "", "sp": [], "t": "语文老师在黑板上写下“什么是幸福”，让大家用一句话回答。答案各不相同。比如有人写“周末能睡到自然醒”，有人写“妈妈泡的、糖放得很低的那杯茶”。一个同学写完又用橡皮轻轻擦掉几个字，改成“和家人一起吃饭”。老师没有说哪一句最对，只说：幸福不一定很响，也不一定很贵。能说出来的答案，往往就在这些很小、很日常的事情里。", "p": ["yǔ", "wén", "lǎo", "shī", "zài", "hēi", "bǎn", "shàng", "xiě", "xià", "", "shén", "me", "shì", "xìng", "fú", "", "", "ràng", "dà", "jiā", "yòng", "yí", "jù", "huà", "huí", "dá", "", "dá", "àn", "gè", "bù", "xiāng", "tóng", "", "bǐ", "rú", "yǒu", "rén", "xiě", "", "zhōu", "mò", "néng", "shuì", "dào", "zì", "rán", "xǐng", "", "", "yǒu", "rén", "xiě", "", "mā", "mā", "pào", "de", "", "táng", "fàng", "de", "hěn", "dī", "de", "nà", "bēi", "chá", "", "", "yí", "gè", "tóng", "xué", "xiě", "wán", "yòu", "yòng", "xiàng", "pí", "qīng", "qīng", "cā", "diào", "jǐ", "gè", "zì", "", "gǎi", "chéng", "", "hé", "jiā", "rén", "yì", "qǐ", "chī", "fàn", "", "", "lǎo", "shī", "méi", "yǒu", "shuō", "nǎ", "yí", "jù", "zuì", "duì", "", "zhǐ", "shuō", "", "xìng", "fú", "bù", "yí", "dìng", "hěn", "xiǎng", "", "yě", "bù", "yí", "dìng", "hěn", "guì", "", "néng", "shuō", "chū", "lái", "de", "dá", "àn", "", "wǎng", "wǎng", "jiù", "zài", "zhè", "xiē", "hěn", "xiǎo", "", "hěn", "rì", "cháng", "de", "shì", "qíng", "lǐ", ""], "vi": "Cô ngữ văn viết lên bảng «Hạnh phúc là gì», bảo cả lớp trả lời bằng một câu. Câu trả lời mỗi người một khác. Chẳng hạn có bạn viết «cuối tuần ngủ đến khi nào tỉnh thì tỉnh», có bạn viết «chén trà mẹ pha, đường để rất thấp». Một bạn viết xong lại dùng tẩy xóa nhẹ vài chữ, sửa thành «ăn cơm cùng gia đình». Cô không nói câu nào đúng nhất, chỉ bảo: hạnh phúc không nhất thiết phải ồn, cũng không nhất thiết phải đắt. Những câu trả lời nói ra được, thường nằm trong những việc rất nhỏ, rất thường ngày ấy.", "en": "The Chinese teacher wrote \"What is happiness?\" on the blackboard and asked everyone to answer in one sentence. The answers were all different. For example, one person wrote \"Being able to sleep until I wake naturally at the weekend\", and another wrote \"The cup of tea my mother makes, with the sugar kept very low\". One classmate finished writing, then gently erased a few characters with an eraser and changed the line to \"Eating with my family\". The teacher did not say which sentence was the most correct, only that happiness does not have to be loud, and does not have to be expensive. The answers you can put into words are often found in these very small, everyday things."}]}]}, {"l": 11, "texts": [{"n": 1, "zh": "对话：林安说他的汉语是怎么练的", "vi": "Hội thoại: Lâm An kể cách anh luyện tiếng Trung", "en": "Dialogue: Lin An talks about how he practises Chinese", "kw": ["词语", "厉害", "流利", "语法", "准确", "连"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "林安，你汉语说得这么流利，是不是有什么特别的办法？", "p": ["lín", "ān", "", "nǐ", "hàn", "yǔ", "shuō", "de", "zhè", "me", "liú", "lì", "", "shì", "bú", "shì", "yǒu", "shén", "me", "tè", "bié", "de", "bàn", "fǎ", ""], "vi": "Lâm An, tiếng Trung cậu nói lưu loát thế, có cách gì đặc biệt không?", "en": "Lin An, you speak Chinese so fluently — is there some special method?"}, {"s": "林安", "sp": ["lín", "ān"], "t": "也没有特别厉害的办法。我每天把新词语抄一遍，再用每个词造两个句子。", "p": ["yě", "méi", "yǒu", "tè", "bié", "lì", "hai", "de", "bàn", "fǎ", "", "wǒ", "měi", "tiān", "bǎ", "xīn", "cí", "yǔ", "chāo", "yí", "biàn", "", "zài", "yòng", "měi", "gè", "cí", "zào", "liǎng", "gè", "jù", "zi", ""], "vi": "Cũng chẳng có cách gì đặc biệt giỏi. Mỗi ngày mình chép lại từ mới một lượt, rồi dùng mỗi từ đặt hai câu.", "en": "There isn't any especially amazing method. Every day I copy the new words once, then make two sentences with each word."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "那语法呢？会不会写的时候还是错？", "p": ["nà", "yǔ", "fǎ", "ne", "", "huì", "bú", "huì", "xiě", "de", "shí", "hòu", "hái", "shì", "cuò", ""], "vi": "Còn ngữ pháp? Lúc viết vẫn sai chứ?", "en": "What about grammar? Do you still make mistakes when you write?"}, {"s": "林安", "sp": ["lín", "ān"], "t": "语法我专门找老师改。他说先求准确，再求快。连发音不好的那个音，我也一天读二十遍。", "p": ["yǔ", "fǎ", "wǒ", "zhuān", "mén", "zhǎo", "lǎo", "shī", "gǎi", "", "tā", "shuō", "xiān", "qiú", "zhǔn", "què", "", "zài", "qiú", "kuài", "", "lián", "fā", "yīn", "bù", "hǎo", "de", "nà", "ge", "yīn", "", "wǒ", "yě", "yì", "tiān", "dú", "èr", "shí", "biàn", ""], "vi": "Ngữ pháp mình nhờ giáo viên sửa riêng. Thầy bảo trước hãy chính xác, rồi hãy nhanh. Ngay cả âm phát âm chưa tốt, mình cũng đọc hai mươi lần một ngày.", "en": "I have a teacher correct my grammar specially. He says aim for accuracy first, then for speed. Even the sound I still can't pronounce well, I read twenty times a day."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "听着就认真。我以后也试着每天造句。", "p": ["tīng", "zhe", "jiù", "rèn", "zhēn", "", "wǒ", "yǐ", "hòu", "yě", "shì", "zhe", "měi", "tiān", "zào", "jù", ""], "vi": "Nghe đã thấy nghiêm túc. Sau mình cũng thử mỗi ngày đặt câu.", "en": "It sounds very conscientious. I'll try making sentences every day too from now on."}, {"s": "林安", "sp": ["lín", "ān"], "t": "一起练就更好。有人听，才知道哪儿还不准确。", "p": ["yì", "qǐ", "liàn", "jiù", "gèng", "hǎo", "", "yǒu", "rén", "tīng", "", "cái", "zhī", "dào", "nǎ", "r", "hái", "bù", "zhǔn", "què", ""], "vi": "Cùng luyện thì càng tốt. Có người nghe mới biết chỗ nào còn chưa chính xác.", "en": "It's even better if we practise together. Only when someone listens do you know where you're still not accurate."}]}, {"n": 2, "zh": "对话：小雪考试前有点儿来不及", "vi": "Hội thoại: Trước kỳ thi Tiểu Tuyết hơi không kịp", "en": "Dialogue: Xiaoxue is a little short of time before the exam", "kw": ["来得及", "否则", "复杂", "填空", "阅读", "只好", "猜"], "lines": [{"s": "阿玲", "sp": ["ā", "líng"], "t": "明天就考试了，你复习得怎么样？", "p": ["míng", "tiān", "jiù", "kǎo", "shì", "le", "", "nǐ", "fù", "xí", "de", "zěn", "me", "yàng", ""], "vi": "Ngày mai đã thi rồi, cậu ôn thế nào?", "en": "The exam is tomorrow. How is your revision going?"}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "阅读还行，可是后面的填空有点儿复杂。有几题我只好先猜。", "p": ["yuè", "dú", "hái", "xíng", "", "kě", "shì", "hòu", "miàn", "de", "tián", "kòng", "yǒu", "diǎn", "r", "fù", "zá", "", "yǒu", "jǐ", "tí", "wǒ", "zhǐ", "hǎo", "xiān", "cāi", ""], "vi": "Đọc hiểu còn ổn, nhưng phần điền chỗ trống phía sau hơi phức tạp. Có vài câu mình đành đoán trước.", "en": "The reading is all right, but the gap-filling at the back is a bit complicated. For a few items I have no choice but to guess first."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "现在开始看，还来得及。否则明天一紧张，更容易空着。", "p": ["xiàn", "zài", "kāi", "shǐ", "kàn", "", "hái", "lái", "de", "jí", "", "fǒu", "zé", "míng", "tiān", "yì", "jǐn", "zhāng", "", "gèng", "róng", "yì", "kōng", "zhe", ""], "vi": "Bây giờ bắt đầu xem vẫn còn kịp. Nếu không, ngày mai vừa hồi hộp lại càng dễ để trống.", "en": "If you start looking through it now, there's still time. Otherwise, once you're nervous tomorrow, it's even easier to leave them blank."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "那我今晚先把填空做完。阅读要是剩下十分钟，再检查一遍。", "p": ["nà", "wǒ", "jīn", "wǎn", "xiān", "bǎ", "tián", "kòng", "zuò", "wán", "", "yuè", "dú", "yào", "shi", "shèng", "xià", "shí", "fēn", "zhōng", "", "zài", "jiǎn", "chá", "yí", "biàn", ""], "vi": "Vậy tối nay mình làm xong phần điền đã. Nếu phần đọc còn mười phút thì kiểm tra lại một lượt.", "en": "Then I'll finish the gap-filling tonight. If I have ten minutes left for the reading, I'll check it through once more."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "对。不会的别空太久，先猜一个，做完再改。", "p": ["duì", "", "bú", "huì", "de", "bié", "kōng", "tài", "jiǔ", "", "xiān", "cāi", "yí", "gè", "", "zuò", "wán", "zài", "gǎi", ""], "vi": "Đúng. Câu không làm được đừng để trống lâu, đoán một đáp án trước, làm xong hãy sửa.", "en": "That's right. Don't leave the ones you can't do blank for too long. Guess one first, and change it after you finish."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "好。你也早点儿歇，明天我们都来得及发挥好。", "p": ["hǎo", "", "nǐ", "yě", "zǎo", "diǎn", "r", "xiē", "", "míng", "tiān", "wǒ", "men", "dōu", "lái", "de", "jí", "fā", "huī", "hǎo", ""], "vi": "Được. Cậu cũng nghỉ sớm, ngày mai cả hai mình vẫn kịp làm tốt.", "en": "All right. You should rest a little earlier too, so tomorrow we both still have time to do ourselves justice."}]}, {"n": 3, "zh": "对话：阿玲家客厅里的杂志", "vi": "Hội thoại: Tạp chí trong phòng khách nhà A Linh", "en": "Dialogue: The magazines in A Linh's living room", "kw": ["客厅", "无论", "杂志", "增加", "著名", "页"], "lines": [{"s": "周南", "sp": ["zhōu", "nán"], "t": "你们家客厅怎么堆了这么多杂志？", "p": ["nǐ", "men", "jiā", "kè", "tīng", "zěn", "me", "duī", "le", "zhè", "me", "duō", "zá", "zhì", ""], "vi": "Phòng khách nhà cậu sao chất nhiều tạp chí thế?", "en": "Why are there so many magazines piled up in your living room?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "我妈妈说，无论多忙，每天也要读几页。她还订了两份著名的文化杂志。", "p": ["wǒ", "mā", "mā", "shuō", "", "wú", "lùn", "duō", "máng", "", "měi", "tiān", "yě", "yào", "dú", "jǐ", "yè", "", "tā", "hái", "dìng", "le", "liǎng", "fèn", "zhù", "míng", "de", "wén", "huà", "zá", "zhì", ""], "vi": "Mẹ mình bảo, dù bận đến mấy, mỗi ngày cũng phải đọc vài trang. Mẹ còn đặt hai tạp chí văn hóa nổi tiếng.", "en": "My mother says that no matter how busy she is, she still reads a few pages every day. She also subscribes to two well-known cultural magazines."}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "那你也看吗？", "p": ["nà", "nǐ", "yě", "kàn", "ma", ""], "vi": "Vậy cậu cũng xem chứ?", "en": "Do you read them too?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "看。我发现，读得多了，自己会写的句子也增加了。有时候一页里就有好几个有用的说法。", "p": ["kàn", "", "wǒ", "fā", "xiàn", "", "dú", "de", "duō", "le", "", "zì", "jǐ", "huì", "xiě", "de", "jù", "zi", "yě", "zēng", "jiā", "le", "", "yǒu", "shí", "hòu", "yí", "yè", "lǐ", "jiù", "yǒu", "hǎo", "jǐ", "gè", "yǒu", "yòng", "de", "shuō", "fǎ", ""], "vi": "Có. Mình thấy đọc nhiều thì câu mình viết được cũng tăng lên. Có lúc trong một trang đã có vài cách nói hữu ích.", "en": "Yes. I've found that the more I read, the more sentences I can write also increase. Sometimes there are several useful expressions on a single page."}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "我以后来，能借一本吗？", "p": ["wǒ", "yǐ", "hòu", "lái", "", "néng", "jiè", "yì", "běn", "ma", ""], "vi": "Lần sau mình đến, mượn một cuốn được không?", "en": "Next time I come, may I borrow one?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "可以。你先坐在客厅里翻翻，喜欢哪本就拿走。", "p": ["kě", "yǐ", "", "nǐ", "xiān", "zuò", "zài", "kè", "tīng", "lǐ", "fān", "fān", "", "xǐ", "huān", "nǎ", "běn", "jiù", "ná", "zǒu", ""], "vi": "Được. Cậu ngồi ở phòng khách mà lật trước, thích cuốn nào thì mang đi.", "en": "Of course. Sit in the living room and leaf through them first, and take whichever you like."}]}, {"n": 4, "zh": "短文：我慢慢有了自己的看法", "vi": "Đoạn văn: Tôi dần có cách nhìn của riêng mình", "en": "Passage: I slowly formed views of my own", "kw": ["看法", "内容", "然而", "文章", "之"], "lines": [{"s": "", "sp": [], "t": "以前读文章，我只问写了什么内容，很少问自己同不同意。后来老师让我们读完写三句话：我看到了什么，我想到了什么，我的看法是什么。然而真要写下看法，才发现并不容易。有的文章之中，作者说得很有道理；有的地方我却想问一句：“一定是这样吗？”就在这一问里，阅读不再只是把字看完，而成为一次认真的对话。", "p": ["yǐ", "qián", "dú", "wén", "zhāng", "", "wǒ", "zhǐ", "wèn", "xiě", "le", "shén", "me", "nèi", "róng", "", "hěn", "shǎo", "wèn", "zì", "jǐ", "tóng", "bù", "tóng", "yì", "", "hòu", "lái", "lǎo", "shī", "ràng", "wǒ", "men", "dú", "wán", "xiě", "sān", "jù", "huà", "", "wǒ", "kàn", "dào", "le", "shén", "me", "", "wǒ", "xiǎng", "dào", "le", "shén", "me", "", "wǒ", "de", "kàn", "fǎ", "shì", "shén", "me", "", "rán", "ér", "zhēn", "yào", "xiě", "xià", "kàn", "fǎ", "", "cái", "fā", "xiàn", "bìng", "bù", "róng", "yì", "", "yǒu", "de", "wén", "zhāng", "zhī", "zhōng", "", "zuò", "zhě", "shuō", "de", "hěn", "yǒu", "dào", "lǐ", "", "yǒu", "de", "dì", "fāng", "wǒ", "què", "xiǎng", "wèn", "yí", "jù", "", "", "yí", "dìng", "shì", "zhè", "yàng", "ma", "", "", "jiù", "zài", "zhè", "yí", "wèn", "lǐ", "", "yuè", "dú", "bú", "zài", "zhǐ", "shì", "bǎ", "zì", "kàn", "wán", "", "ér", "chéng", "wéi", "yí", "cì", "rèn", "zhēn", "de", "duì", "huà", ""], "vi": "Trước khi đọc bài, tôi chỉ hỏi viết nội dung gì, ít khi hỏi mình có đồng ý không. Sau cô giáo bảo đọc xong viết ba câu: tôi thấy gì, nghĩ gì, cách nhìn của tôi là gì. Thế nhưng thật sự phải viết ra cách nhìn mới thấy không dễ. Trong một số bài, tác giả nói rất có lý; có chỗ tôi lại muốn hỏi: «Nhất định phải vậy sao?» Chính trong câu hỏi ấy, việc đọc không còn chỉ là xem hết chữ, mà thành một cuộc đối thoại nghiêm túc.", "en": "When I used to read an article, I only asked what the content was, and seldom asked whether I agreed. Later the teacher had us write three sentences after reading: what I saw, what I thought, and what my view was. And yet, only when I really had to write down a view did I find it was not easy. In some articles the author sounds very reasonable; in other places I want to ask, \"Does it have to be like this?\" It is in that one question that reading is no longer just getting to the end of the words, but becomes a serious conversation."}]}, {"n": 5, "zh": "短文：把读书养成一种顺序", "vi": "Đoạn văn: Biến việc đọc thành một thứ tự", "en": "Passage: Make reading into a kind of order", "kw": ["表示", "精彩", "顺序", "同时", "相同", "养成"], "lines": [{"s": "", "sp": [], "t": "选择书的时候，我给自己定了一个小小的顺序：先看自己真正想了解的，再看别人说很精彩的。两本内容并不相同的书，同时放在桌上，反而让我更清楚自己喜欢什么。养成这个习惯以后，我不再一听到“有名”就立刻买。对我来说，读书表示愿意把一段时间安静地交给一本书，而不是匆匆忙忙地翻完。精彩的故事当然好，可适合自己的书，才会让人想再读一遍。", "p": ["xuǎn", "zé", "shū", "de", "shí", "hòu", "", "wǒ", "gěi", "zì", "jǐ", "dìng", "le", "yí", "gè", "xiǎo", "xiǎo", "de", "shùn", "xù", "", "xiān", "kàn", "zì", "jǐ", "zhēn", "zhèng", "xiǎng", "liǎo", "jiě", "de", "", "zài", "kàn", "bié", "rén", "shuō", "hěn", "jīng", "cǎi", "de", "", "liǎng", "běn", "nèi", "róng", "bìng", "bù", "xiāng", "tóng", "de", "shū", "", "tóng", "shí", "fàng", "zài", "zhuō", "shàng", "", "fǎn", "ér", "ràng", "wǒ", "gèng", "qīng", "chǔ", "zì", "jǐ", "xǐ", "huān", "shén", "me", "", "yǎng", "chéng", "zhè", "ge", "xí", "guàn", "yǐ", "hòu", "", "wǒ", "bú", "zài", "yì", "tīng", "dào", "", "yǒu", "míng", "", "jiù", "lì", "kè", "mǎi", "", "duì", "wǒ", "lái", "shuō", "", "dú", "shū", "biǎo", "shì", "yuàn", "yì", "bǎ", "yí", "duàn", "shí", "jiān", "ān", "jìng", "dì", "jiāo", "gěi", "yì", "běn", "shū", "", "ér", "bú", "shì", "cōng", "cōng", "máng", "máng", "dì", "fān", "wán", "", "jīng", "cǎi", "de", "gù", "shì", "dāng", "rán", "hǎo", "", "kě", "shì", "hé", "zì", "jǐ", "de", "shū", "", "cái", "huì", "ràng", "rén", "xiǎng", "zài", "dú", "yí", "biàn", ""], "vi": "Khi chọn sách, tôi đặt cho mình một thứ tự nhỏ: trước hãy xem điều mình thật sự muốn hiểu, rồi mới xem những cuốn người khác bảo rất hay. Hai quyển nội dung không giống nhau, để cùng lúc trên bàn, ngược lại giúp tôi rõ hơn mình thích gì. Sau khi nuôi dưỡng thói quen ấy, tôi không còn vừa nghe «nổi tiếng» là mua ngay. Với tôi, đọc sách biểu thị sẵn sàng dành một khoảng thời gian yên tĩnh cho một quyển sách, chứ không phải lật xong một cách vội. Câu chuyện hay cố nhiên tốt, nhưng cuốn hợp với mình mới khiến người ta muốn đọc lại.", "en": "When I choose a book, I have set myself a little order: first look at what I really want to understand, and only then at what other people say is wonderful. Two books whose contents are not the same, placed on the desk at the same time, actually make me clearer about what I like. After forming this habit, I no longer buy something the moment I hear it is \"famous.\" For me, reading means being willing to give a quiet stretch of time to a book, not flipping through it in a hurry. A wonderful story is good, of course, but only a book that suits you makes you want to read it again."}]}]}, {"l": 12, "texts": [{"n": 1, "zh": "对话：陈晓的小店遇到了规定", "vi": "Hội thoại: Tiệm nhỏ của Trần Hiểu gặp quy định", "en": "Dialogue: Chen Xiao's little shop runs into a rule", "kw": ["并且", "规定", "可惜", "全部", "商量", "也许", "死"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "陈晓今天怎么脸色不好？", "p": ["chén", "xiǎo", "jīn", "tiān", "zěn", "me", "liǎn", "sè", "bù", "hǎo", ""], "vi": "Hôm nay mặt Trần Hiểu sao không vui?", "en": "Why does Chen Xiao look so unhappy today?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "他帮忙的那家小店接到新规定：进货渠道全部要改，并且必须这周五前改完。他都快急死了。", "p": ["tā", "bāng", "máng", "de", "nà", "jiā", "xiǎo", "diàn", "jiē", "dào", "xīn", "guī", "dìng", "", "jìn", "huò", "qú", "dào", "quán", "bù", "yào", "gǎi", "", "bìng", "qiě", "bì", "xū", "zhè", "zhōu", "wǔ", "qián", "gǎi", "wán", "", "tā", "dōu", "kuài", "jí", "sǐ", "le", ""], "vi": "Tiệm nhỏ cậu ấy phụ thì nhận quy định mới: toàn bộ kênh nhập phải đổi, và phải đổi xong trước thứ sáu tuần này. Cậu ấy gần phát điên lên.", "en": "The little shop he helps at has received a new rule: all the supply channels have to be changed, and they must be changed by this Friday. He is almost worried to death."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "这么急？来不及商量一下吗？", "p": ["zhè", "me", "jí", "", "lái", "bu", "jí", "shāng", "liang", "yí", "xià", "ma", ""], "vi": "Gấp thế? Không kịp bàn bạc một chút à?", "en": "So urgent? Is there no time to talk it over a little?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "经理说规定不能改，可惜的是，原来那家供货的东西更便宜。", "p": ["jīng", "lǐ", "shuō", "guī", "dìng", "bù", "néng", "gǎi", "", "kě", "xī", "de", "shì", "", "yuán", "lái", "nà", "jiā", "gōng", "huò", "de", "dōng", "xi", "gèng", "pián", "yi", ""], "vi": "Giám đốc bảo quy định không đổi được, đáng tiếc là đồ bên cung cấp cũ rẻ hơn.", "en": "The manager says the rule cannot be changed. The pity is that the old supplier's goods were cheaper."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "也许先改一部分，其余的下周再补？你让他再去商量一次。", "p": ["yě", "xǔ", "xiān", "gǎi", "yí", "bù", "fen", "", "qí", "yú", "de", "xià", "zhōu", "zài", "bǔ", "", "nǐ", "ràng", "tā", "zài", "qù", "shāng", "liang", "yí", "cì", ""], "vi": "Có lẽ đổi một phần trước, phần còn lại tuần sau bù? Cậu bảo cậu ấy bàn thêm lần nữa.", "en": "Perhaps they could change part of it first, and make up the rest next week? Tell him to go and discuss it once more."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "我今晚就跟他说。全部一下子改，真的太赶了。", "p": ["wǒ", "jīn", "wǎn", "jiù", "gēn", "tā", "shuō", "", "quán", "bù", "yí", "xià", "zi", "gǎi", "", "zhēn", "de", "tài", "gǎn", "le", ""], "vi": "Tối nay mình nói với cậu ấy. Đổi hết một lúc thật sự quá gấp.", "en": "I'll talk to him tonight. Changing everything all at once is really too rushed."}]}, {"n": 2, "zh": "对话：吴姐教阿玲护一护深色衣服", "vi": "Hội thoại: Chị Ngô dạy A Linh giữ áo màu tối", "en": "Dialogue: Sister Wu teaches A Linh how to look after dark clothes", "kw": ["保护", "无法", "作用", "无", "盐", "勺子"], "lines": [{"s": "阿玲", "sp": ["ā", "líng"], "t": "吴姐，这件新衬衣我能和浅色的一起洗吗？", "p": ["wú", "jiě", "", "zhè", "jiàn", "xīn", "chèn", "yī", "wǒ", "néng", "hé", "qiǎn", "sè", "de", "yì", "qǐ", "xǐ", "ma", ""], "vi": "Chị Ngô, áo sơ mi mới này em giặt chung với đồ màu sáng được không?", "en": "Sister Wu, can I wash this new shirt together with the light-coloured things?"}, {"s": "吴姐", "sp": ["wú", "jiě"], "t": "最好别。深色的要是掉色，浅色的就无法再变回来了。", "p": ["zuì", "hǎo", "bié", "", "shēn", "sè", "de", "yào", "shi", "diào", "sè", "", "qiǎn", "sè", "de", "jiù", "wú", "fǎ", "zài", "biàn", "huí", "lái", "le", ""], "vi": "Tốt nhất đừng. Đồ tối nếu phai màu thì đồ sáng không cách nào trở lại được nữa.", "en": "Better not. If the dark one loses colour, the light ones cannot be made as they were before."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "那怎么保护它？", "p": ["nà", "zěn", "me", "bǎo", "hù", "tā", ""], "vi": "Vậy bảo vệ nó thế nào?", "en": "Then how can I protect it?"}, {"s": "吴姐", "sp": ["wú", "jiě"], "t": "第一次洗，在水里放一小勺子盐，有固色的作用。水要凉，也别泡太久。", "p": ["dì", "yī", "cì", "xǐ", "", "zài", "shuǐ", "lǐ", "fàng", "yì", "xiǎo", "sháo", "zi", "yán", "", "yǒu", "gù", "sè", "de", "zuò", "yòng", "", "shuǐ", "yào", "liáng", "", "yě", "bié", "pào", "tài", "jiǔ", ""], "vi": "Lần đầu giặt, cho vào nước một thìa muối nhỏ, có tác dụng giữ màu. Nước phải mát, cũng đừng ngâm lâu.", "en": "The first time you wash it, put a small spoon of salt in the water. It has the effect of fixing the colour. The water should be cool, and don't soak it too long either."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "没有盐呢？", "p": ["méi", "yǒu", "yán", "ne", ""], "vi": "Không có muối thì sao?", "en": "What if there's no salt?"}, {"s": "吴姐", "sp": ["wú", "jiě"], "t": "没有盐就单独洗。无盐也没关系，只是作用会差一点。", "p": ["méi", "yǒu", "yán", "jiù", "dān", "dú", "xǐ", "", "wú", "yán", "yě", "méi", "guān", "xì", "", "zhǐ", "shì", "zuò", "yòng", "huì", "chà", "yì", "diǎn", ""], "vi": "Không có muối thì giặt riêng. Không muối cũng không sao, chỉ là tác dụng kém hơn một chút.", "en": "Then wash it on its own. It's all right to be without salt, only the effect will be a little weaker."}]}, {"n": 3, "zh": "对话：程老师的一节自然课", "vi": "Hội thoại: Một tiết tự nhiên của cô Trình", "en": "Dialogue: A nature lesson of Teacher Cheng's", "kw": ["对于", "教育", "解释", "详细", "叶子", "节"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你们今天第几节是自然课？我看程老师抱了好多叶子进来。", "p": ["nǐ", "men", "jīn", "tiān", "dì", "jǐ", "jié", "shì", "zì", "rán", "kè", "", "wǒ", "kàn", "chéng", "lǎo", "shī", "bào", "le", "hǎo", "duō", "yè", "zi", "jìn", "lái", ""], "vi": "Hôm nay tiết thứ mấy là giờ tự nhiên? Mình thấy cô Trình ôm rất nhiều lá vào.", "en": "Which period is nature class for you today? I saw Teacher Cheng come in carrying a lot of leaves."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "第三节。她对于怎么引起我们的兴趣，真的很用心。", "p": ["dì", "sān", "jié", "", "tā", "duì", "yú", "zěn", "me", "yǐn", "qǐ", "wǒ", "men", "de", "xìng", "qù", "", "zhēn", "de", "hěn", "yòng", "xīn", ""], "vi": "Tiết ba. Cô ấy đối với việc khơi sự thích thú của bọn mình, thật sự rất dụng tâm.", "en": "The third period. When it comes to getting us interested, she really puts her heart into it."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "她怎么上？", "p": ["tā", "zěn", "me", "shàng", ""], "vi": "Cô ấy dạy thế nào?", "en": "How does she teach it?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "先让我们摸一摸不同的叶子，再详细解释它们为什么形状不一样。一节课下来，大家都不想走。", "p": ["xiān", "ràng", "wǒ", "men", "mō", "yì", "mō", "bù", "tóng", "de", "yè", "zi", "", "zài", "xiáng", "xì", "jiě", "shì", "tā", "men", "wèi", "shén", "me", "xíng", "zhuàng", "bù", "yí", "yàng", "", "yì", "jié", "kè", "xià", "lái", "", "dà", "jiā", "dōu", "bù", "xiǎng", "zǒu", ""], "vi": "Trước để mình sờ những lá khác nhau, rồi giải thích rất kỹ vì sao hình dạng chúng không giống nhau. Hết một tiết, ai cũng chẳng muốn ra.", "en": "First she has us feel different leaves, then she explains in detail why their shapes are not the same. By the end of the period, nobody wants to leave."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "这种教育方法我喜欢。不是只听，还能动手。", "p": ["zhè", "zhǒng", "jiào", "yù", "fāng", "fǎ", "wǒ", "xǐ", "huān", "", "bú", "shì", "zhǐ", "tīng", "", "hái", "néng", "dòng", "shǒu", ""], "vi": "Cách giáo dục ấy mình thích. Không phải chỉ nghe, còn được làm.", "en": "I like that kind of education. You don't only listen; you can also use your hands."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "对。她还说，下节课会带我们去楼下的花园看真的树。", "p": ["duì", "", "tā", "hái", "shuō", "", "xià", "jié", "kè", "huì", "dài", "wǒ", "men", "qù", "lóu", "xià", "de", "huā", "yuán", "kàn", "zhēn", "de", "shù", ""], "vi": "Đúng. Cô còn nói tiết sau sẽ đưa mình ra vườn dưới nhà xem cây thật.", "en": "Yes. She also said that next period she will take us down to the garden to look at real trees."}]}, {"n": 4, "zh": "短文：一句话引起的误会", "vi": "Đoạn văn: Sự hiểu lầm do một câu nói", "en": "Passage: A misunderstanding caused by one sentence", "kw": ["使用", "误会", "引起", "友好", "语言", "直接"], "lines": [{"s": "", "sp": [], "t": "语言使用得不小心，很容易引起误会。有一次我在宿舍想直接问同学：“你的灯还开着吗？”话说快了，听起来倒像在抱怨。她当时没说话，后来才告诉我，她以为我在嫌她。我这才明白，友好的意思，有时不在内容本身，而在快慢和口气。后来再需要提醒别人，我会先叫一声名字，再慢慢把句子说完。直接不是错，可直接也需要温度。", "p": ["yǔ", "yán", "shǐ", "yòng", "de", "bù", "xiǎo", "xīn", "", "hěn", "róng", "yì", "yǐn", "qǐ", "wù", "huì", "", "yǒu", "yí", "cì", "wǒ", "zài", "sù", "shè", "xiǎng", "zhí", "jiē", "wèn", "tóng", "xué", "", "", "nǐ", "de", "dēng", "hái", "kāi", "zhe", "ma", "", "", "huà", "shuō", "kuài", "le", "", "tīng", "qǐ", "lái", "dào", "xiàng", "zài", "bào", "yuàn", "", "tā", "dāng", "shí", "méi", "shuō", "huà", "", "hòu", "lái", "cái", "gào", "sù", "wǒ", "", "tā", "yǐ", "wéi", "wǒ", "zài", "xián", "tā", "", "wǒ", "zhè", "cái", "míng", "bái", "", "yǒu", "hǎo", "de", "yì", "si", "", "yǒu", "shí", "bú", "zài", "nèi", "róng", "běn", "shēn", "", "ér", "zài", "kuài", "màn", "hé", "kǒu", "qì", "", "hòu", "lái", "zài", "xū", "yào", "tí", "xǐng", "bié", "rén", "", "wǒ", "huì", "xiān", "jiào", "yì", "shēng", "míng", "zì", "", "zài", "màn", "màn", "bǎ", "jù", "zi", "shuō", "wán", "", "zhí", "jiē", "bú", "shì", "cuò", "", "kě", "zhí", "jiē", "yě", "xū", "yào", "wēn", "dù", ""], "vi": "Ngôn ngữ dùng không cẩn thận rất dễ gây hiểu lầm. Có lần ở ký túc xá tôi muốn hỏi thẳng bạn: «Đèn cậu vẫn mở à?» Nói nhanh quá, nghe lại giống như phàn nàn. Lúc ấy cô ấy không nói, sau mới bảo tưởng tôi chê. Tôi mới hiểu, ý thân thiện đôi khi không nằm ở bản thân nội dung, mà ở nhanh chậm và giọng. Về sau cần nhắc người khác, tôi gọi tên trước, rồi nói hết câu một cách chậm rãi. Thẳng thắn không sai, nhưng thẳng thắn cũng cần hơi ấm.", "en": "If language is used carelessly, it can easily cause a misunderstanding. Once in the dorm I wanted to ask a classmate directly, \"Is your light still on?\" I said it too quickly, and it sounded rather like a complaint. She said nothing at the time, and only later told me she had thought I was finding fault with her. Only then did I understand that a friendly meaning sometimes lies not in the content itself, but in the speed and the tone. Later, when I need to remind someone of something, I call their name first, then finish the sentence slowly. Being direct is not wrong, but being direct also needs a little warmth."}]}, {"n": 5, "zh": "短文：力气要花在该花的地方", "vi": "Đoạn văn: Sức lực hãy dùng vào chỗ đáng dùng", "en": "Passage: Spend your strength where it ought to be spent", "kw": ["节约", "力气", "任务", "相反", "意见", "仔细"], "lines": [{"s": "", "sp": [], "t": "完成一项任务，并不总是花的力气越多越好。有人一得到任务就埋头做很久，相反，有人先仔细看要求，再决定先做什么。第二种看起来慢，常常却更节约时间。对我来说，别人的意见也可以帮我少走弯路，可我不会不看就全听。先听，再想，最后才动手：力气花在该花的地方，事情才会轻一点。", "p": ["wán", "chéng", "yí", "xiàng", "rèn", "wu", "", "bìng", "bù", "zǒng", "shì", "huā", "de", "lì", "qi", "yuè", "duō", "yuè", "hǎo", "", "yǒu", "rén", "yì", "de", "dào", "rèn", "wù", "jiù", "mái", "tóu", "zuò", "hěn", "jiǔ", "", "xiāng", "fǎn", "", "yǒu", "rén", "xiān", "zǐ", "xì", "kàn", "yāo", "qiú", "", "zài", "jué", "dìng", "xiān", "zuò", "shén", "me", "", "dì", "èr", "zhǒng", "kàn", "qǐ", "lái", "màn", "", "cháng", "cháng", "què", "gèng", "jié", "yuē", "shí", "jiān", "", "duì", "wǒ", "lái", "shuō", "", "bié", "rén", "de", "yì", "jiàn", "yě", "kě", "yǐ", "bāng", "wǒ", "shǎo", "zǒu", "wān", "lù", "", "kě", "wǒ", "bú", "huì", "bú", "kàn", "jiù", "quán", "tīng", "", "xiān", "tīng", "", "zài", "xiǎng", "", "zuì", "hòu", "cái", "dòng", "shǒu", "", "lì", "qi", "huā", "zài", "gāi", "huā", "de", "dì", "fāng", "", "shì", "qíng", "cái", "huì", "qīng", "yì", "diǎn", ""], "vi": "Hoàn thành một nhiệm vụ không phải lúc nào cũng càng bỏ nhiều sức càng tốt. Có người vừa nhận việc đã cắm đầu làm rất lâu, ngược lại có người xem kỹ yêu cầu trước, rồi mới quyết làm gì trước. Cách thứ hai trông chậm, thường lại tiết kiệm thời gian hơn. Với tôi, ý kiến người khác cũng có thể giúp bớt đường vòng, nhưng tôi sẽ không nghe hết mà không xem. Nghe trước, nghĩ đã, cuối cùng mới bắt tay: sức dùng đúng chỗ thì việc mới nhẹ hơn.", "en": "When you finish a task, more strength is not always better. Some people bury themselves in the work for a long time as soon as they get a task; on the contrary, others first look carefully at what is required, and only then decide what to do first. The second way looks slow, but it often saves more time. For me, other people's opinions can also help me take fewer detours, but I will not follow them all without looking for myself. Listen first, think, and only then start: when your strength is spent where it ought to be spent, the work becomes a little lighter."}]}]}, {"l": 13, "texts": [{"n": 1, "zh": "对话：陈叔叔要在社区演京剧", "vi": "Hội thoại: Chú Trần sắp diễn Kinh kịch trong khu", "en": "Dialogue: Uncle Chen is going to perform Peking opera in the neighbourhood", "kw": ["大概", "观众", "京剧", "演出", "演员", "厚"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "周末社区有演出？海报上那个人是谁？", "p": ["zhōu", "mò", "shè", "qū", "yǒu", "yǎn", "chū", "", "hǎi", "bào", "shàng", "nà", "ge", "rén", "shì", "shuí", ""], "vi": "Cuối tuần khu phố có buổi diễn à? Người trên áp phích là ai?", "en": "Is there a performance in the neighbourhood at the weekend? Who is that person on the poster?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "是陈晓的叔叔。他是业余京剧演员，这次要唱一段。", "p": ["shì", "chén", "xiǎo", "de", "shū", "shu", "", "tā", "shì", "yè", "yú", "jīng", "jù", "yǎn", "yuán", "", "zhè", "cì", "yào", "chàng", "yí", "duàn", ""], "vi": "Là chú của Trần Hiểu. Chú ấy là diễn viên Kinh kịch nghiệp dư, lần này sẽ hát một đoạn.", "en": "That's Chen Xiao's uncle. He's an amateur Peking opera actor, and this time he's going to sing a scene."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "京剧的衣服那么厚，夏天穿热不热？", "p": ["jīng", "jù", "de", "yī", "fú", "nà", "me", "hòu", "", "xià", "tiān", "chuān", "rè", "bú", "rè", ""], "vi": "Áo Kinh kịch dày vậy, mùa hè mặc có nóng không?", "en": "Peking opera costumes are so thick — isn't it hot to wear them in summer?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "他说大概会有些热，可一想到台下有观众，就顾不上了。", "p": ["tā", "shuō", "dà", "gài", "huì", "yǒu", "xiē", "rè", "", "kě", "yì", "xiǎng", "dào", "tái", "xià", "yǒu", "guān", "zhòng", "", "jiù", "gù", "bú", "shàng", "le", ""], "vi": "Chú ấy bảo đại khái sẽ hơi nóng, nhưng nghĩ đến dưới sân khấu có khán giả thì chẳng kịp để ý nữa.", "en": "He said it will probably be a bit hot, but as soon as he thinks of the audience below the stage, he no longer notices."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "那我们去看吧。我还没现场听过。", "p": ["nà", "wǒ", "men", "qù", "kàn", "ba", "", "wǒ", "hái", "méi", "xiàn", "chǎng", "tīng", "guò", ""], "vi": "Vậy mình đi xem đi. Mình chưa nghe trực tiếp bao giờ.", "en": "Then let's go and watch. I've never heard it live."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "好。陈晓说演完还可以问演员几个问题。", "p": ["hǎo", "", "chén", "xiǎo", "shuō", "yǎn", "wán", "hái", "kě", "yǐ", "wèn", "yǎn", "yuán", "jǐ", "gè", "wèn", "tí", ""], "vi": "Được. Trần Hiểu bảo diễn xong còn có thể hỏi diễn viên vài câu.", "en": "All right. Chen Xiao said that after the performance we can also ask the actors a few questions."}]}, {"n": 2, "zh": "对话：周南跟着视频学了一段京剧", "vi": "Hội thoại: Châu Nam học một đoạn Kinh kịch theo video", "en": "Dialogue: Zhou Nan has learned a bit of Peking opera from a video", "kw": ["表演", "吃惊", "基础", "来自", "偶尔", "遍"], "lines": [{"s": "阿玲", "sp": ["ā", "líng"], "t": "你刚才在房间里唱什么？我听了都吃惊。", "p": ["nǐ", "gāng", "cái", "zài", "fáng", "jiān", "lǐ", "chàng", "shén", "me", "", "wǒ", "tīng", "le", "dōu", "chī", "jīng", ""], "vi": "Lúc nãy cậu hát gì trong phòng thế? Mình nghe đã giật mình.", "en": "What were you singing in the room just now? I was startled when I heard it."}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "一段很短的京剧。我跟着网上的视频学，同一段听了十几遍，偶尔还比划两下。", "p": ["yī", "duàn", "hěn", "duǎn", "de", "jīng", "jù", "", "wǒ", "gēn", "zhe", "wǎng", "shàng", "de", "shì", "pín", "xué", "", "tóng", "yí", "duàn", "tīng", "le", "shí", "jǐ", "biàn", "", "ǒu", "ěr", "hái", "bǐ", "huà", "liǎng", "xià", ""], "vi": "Một đoạn Kinh kịch rất ngắn. Mình học theo video trên mạng, cùng một đoạn nghe hơn mười lượt, thỉnh thoảng còn ra điệu một chút.", "en": "A very short piece of Peking opera. I learned it from a video online, listened to the same passage a dozen times, and occasionally even made a few movements."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "你以前有基础吗？", "p": ["nǐ", "yǐ", "qián", "yǒu", "jī", "chǔ", "ma", ""], "vi": "Trước cậu có nền tảng không?", "en": "Did you have any foundation in it before?"}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "没有。这兴趣来自上周那场演出。我觉得那种表演很特别，想试试。", "p": ["méi", "yǒu", "", "zhè", "xìng", "qù", "lái", "zì", "shàng", "zhōu", "nà", "chǎng", "yǎn", "chū", "", "wǒ", "jué", "de", "nà", "zhǒng", "biǎo", "yǎn", "hěn", "tè", "bié", "", "xiǎng", "shì", "shì", ""], "vi": "Không. Hứng thú này đến từ buổi diễn tuần trước. Mình thấy cách biểu diễn ấy rất đặc biệt, muốn thử.", "en": "No. This interest comes from that performance last week. I thought that kind of performance was very special, and I wanted to try it."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "那你唱一段给我听？", "p": ["nà", "nǐ", "chàng", "yí", "duàn", "gěi", "wǒ", "tīng", ""], "vi": "Vậy cậu hát một đoạn cho mình nghe được không?", "en": "Then will you sing a bit for me?"}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "行。不过你可别笑，我还只是刚刚开始。", "p": ["xíng", "", "bú", "guò", "nǐ", "kě", "bié", "xiào", "", "wǒ", "hái", "zhǐ", "shì", "gāng", "gāng", "kāi", "shǐ", ""], "vi": "Được. Nhưng cậu đừng cười, mình mới chỉ vừa bắt đầu.", "en": "All right. But don't you laugh — I'm still only just beginning."}]}, {"n": 3, "zh": "对话：程老师向校长申请一个小活动", "vi": "Hội thoại: Cô Trình xin hiệu trưởng một hoạt động nhỏ", "en": "Dialogue: Teacher Cheng applies to the principal for a small event", "kw": ["继续", "开心", "申请", "讨论", "有趣", "正常", "由"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "程老师今天怎么这么开心？", "p": ["chéng", "lǎo", "shī", "jīn", "tiān", "zěn", "me", "zhè", "me", "kāi", "xīn", ""], "vi": "Hôm nay cô Trình sao vui thế?", "en": "Why is Teacher Cheng so happy today?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "她向校长申请在下个月办一场小小的文化活动，校长说可以继续往下准备。", "p": ["tā", "xiàng", "xiào", "zhǎng", "shēn", "qǐng", "zài", "xià", "gè", "yuè", "bàn", "yì", "cháng", "xiǎo", "xiǎo", "de", "wén", "huà", "huó", "dòng", "", "xiào", "zhǎng", "shuō", "kě", "yǐ", "jì", "xù", "wǎng", "xià", "zhǔn", "bèi", ""], "vi": "Cô ấy xin hiệu trưởng tháng sau tổ chức một hoạt động văn hóa nhỏ, thầy hiệu trưởng bảo có thể tiếp tục chuẩn bị.", "en": "She applied to the principal to hold a small cultural event next month, and the principal said she could continue preparing it."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "都有什么？", "p": ["dōu", "yǒu", "shén", "me", ""], "vi": "Có những gì?", "en": "What's it going to include?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "由学生表演短剧、写毛笔字，还讨论怎么把活动做得有趣一点儿。时间就放在正常上课的周五下午。", "p": ["yóu", "xué", "shēng", "biǎo", "yǎn", "duǎn", "jù", "", "xiě", "máo", "bǐ", "zì", "", "hái", "tǎo", "lùn", "zěn", "me", "bǎ", "huó", "dòng", "zuò", "de", "yǒu", "qù", "yì", "diǎn", "r", "", "shí", "jiān", "jiù", "fàng", "zài", "zhèng", "cháng", "shàng", "kè", "de", "zhōu", "wǔ", "xià", "wǔ", ""], "vi": "Do học sinh diễn kịch ngắn, viết chữ bút lông, còn thảo luận cách làm hoạt động thú vị hơn một chút. Thời gian để vào chiều thứ sáu giờ học bình thường.", "en": "The students will put on a short play and practise brush writing, and they'll also discuss how to make the event a little more interesting. It will be at the normal time, on Friday afternoon."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "那我们班能参加吗？", "p": ["nà", "wǒ", "men", "bān", "néng", "cān", "jiā", "ma", ""], "vi": "Vậy lớp mình tham gia được không?", "en": "Can our class take part?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "能。程老师说先交一份简单的申请，再报名。", "p": ["néng", "", "chéng", "lǎo", "shī", "shuō", "xiān", "jiāo", "yí", "fèn", "jiǎn", "dān", "de", "shēn", "qǐng", "", "zài", "bào", "míng", ""], "vi": "Được. Cô Trình bảo nộp một đơn xin đơn giản trước, rồi mới đăng ký.", "en": "Yes. Teacher Cheng said to hand in a simple application first, and then sign up."}]}, {"n": 4, "zh": "短文：餐厅里的一张小说明", "vi": "Đoạn văn: Một tờ hướng dẫn nhỏ trong nhà hàng", "en": "Passage: A little notice in a restaurant", "kw": ["互联网", "餐厅", "错误", "大约", "进行", "纸袋"], "lines": [{"s": "", "sp": [], "t": "附近新开了一家中餐厅。店不大，可桌子上放着一张用中文和越南文写的说明：怎么用筷子，怎么把剩菜装进纸袋。老板说，说明是在互联网上请人一起改的，为的是少出错误。第一次去的人大约都要看一两分钟，才开始点菜。点完以后，服务进行得并不慢。我喜欢这种做法：不是假设人人都会，而是先把可能不清楚的地方写明白。", "p": ["fù", "jìn", "xīn", "kāi", "le", "yì", "jiā", "zhōng", "cān", "tīng", "", "diàn", "bú", "dà", "", "kě", "zhuō", "zi", "shàng", "fàng", "zhe", "yì", "zhāng", "yòng", "zhōng", "wén", "hé", "yuè", "nán", "wén", "xiě", "de", "shuō", "míng", "", "zěn", "me", "yòng", "kuài", "zi", "", "zěn", "me", "bǎ", "shèng", "cài", "zhuāng", "jìn", "zhǐ", "dài", "", "lǎo", "bǎn", "shuō", "", "shuō", "míng", "shì", "zài", "hù", "lián", "wǎng", "shàng", "qǐng", "rén", "yì", "qǐ", "gǎi", "de", "", "wèi", "de", "shì", "shǎo", "chū", "cuò", "wù", "", "dì", "yī", "cì", "qù", "de", "rén", "dà", "yuē", "dōu", "yào", "kàn", "yì", "liǎng", "fēn", "zhōng", "", "cái", "kāi", "shǐ", "diǎn", "cài", "", "diǎn", "wán", "yǐ", "hòu", "", "fú", "wù", "jìn", "xíng", "de", "bìng", "bú", "màn", "", "wǒ", "xǐ", "huān", "zhè", "zhǒng", "zuò", "fǎ", "", "bú", "shì", "jiǎ", "shè", "rén", "rén", "dōu", "huì", "", "ér", "shì", "xiān", "bǎ", "kě", "néng", "bù", "qīng", "chǔ", "de", "dì", "fāng", "xiě", "míng", "bái", ""], "vi": "Gần đây mới mở một nhà hàng Trung. Tiệm không lớn, nhưng trên bàn có một tờ hướng dẫn viết bằng tiếng Trung và tiếng Việt: dùng đũa thế nào, thức ăn thừa cho vào túi giấy ra sao. Ông chủ nói tờ ấy được nhờ người sửa cùng trên internet, để bớt sai sót. Người đến lần đầu đại khái đều xem một hai phút rồi mới gọi món. Gọi xong, việc phục vụ tiến hành cũng không chậm. Tôi thích cách ấy: không giả định ai cũng biết, mà viết rõ những chỗ có thể chưa rõ trước.", "en": "A Chinese restaurant has just opened nearby. The shop is not large, but on the tables there is a notice written in Chinese and Vietnamese: how to use chopsticks, and how to put leftover dishes into a paper bag. The owner said the notice had been revised together with people on the internet, so as to make fewer mistakes. People coming for the first time spend about one or two minutes reading it before they start to order. After they have ordered, the service is carried out at a pace that is not slow. I like this way of doing things: it does not assume that everyone already knows, but first writes down clearly the places that might not be clear."}]}, {"n": 5, "zh": "短文：老家那碗稍微有点儿苦的汤", "vi": "Đoạn văn: Bát canh hơi đắng một chút ở quê", "en": "Passage: That slightly bitter soup from home", "kw": ["部分", "普遍", "稍微", "十分", "随着", "苦", "省"], "lines": [{"s": "", "sp": [], "t": "我的老家在一个南方的省。那里有一种汤，味道稍微有点儿苦，可十分清爽。以前只有部分上了年纪的人爱喝。随着年轻人回家的次数增加，这种汤也慢慢变得普遍起来。有人往里放一点甜的，有人坚持原味。我每次回去，还是先喝一碗不放糖的。苦过后的那一点儿甜，像是把一路上的灰尘都洗掉了。", "p": ["wǒ", "de", "lǎo", "jiā", "zài", "yí", "gè", "nán", "fāng", "de", "shěng", "", "nà", "lǐ", "yǒu", "yì", "zhǒng", "tāng", "", "wèi", "dao", "shāo", "wēi", "yǒu", "diǎn", "r", "kǔ", "", "kě", "shí", "fēn", "qīng", "shuǎng", "", "yǐ", "qián", "zhǐ", "yǒu", "bù", "fen", "shàng", "le", "nián", "jì", "de", "rén", "ài", "hē", "", "suí", "zhe", "nián", "qīng", "rén", "huí", "jiā", "de", "cì", "shù", "zēng", "jiā", "", "zhè", "zhǒng", "tāng", "yě", "màn", "màn", "biàn", "de", "pǔ", "biàn", "qǐ", "lái", "", "yǒu", "rén", "wǎng", "lǐ", "fàng", "yì", "diǎn", "tián", "de", "", "yǒu", "rén", "jiān", "chí", "yuán", "wèi", "", "wǒ", "měi", "cì", "huí", "qù", "", "hái", "shì", "xiān", "hē", "yì", "wǎn", "bú", "fàng", "táng", "de", "", "kǔ", "guò", "hòu", "de", "nà", "yì", "diǎn", "r", "tián", "", "xiàng", "shì", "bǎ", "yí", "lù", "shàng", "de", "huī", "chén", "dōu", "xǐ", "diào", "le", ""], "vi": "Quê tôi ở một tỉnh phía nam. Ở đó có một món canh, vị hơi đắng một chút, nhưng rất thanh. Trước chỉ một phần người lớn tuổi thích uống. Theo những lần người trẻ về nhà tăng lên, món canh ấy cũng dần trở nên phổ biến. Có người cho vào một chút ngọt, có người giữ nguyên vị. Mỗi lần về, tôi vẫn uống trước một bát không đường. Chút ngọt sau vị đắng như rửa sạch bụi dọc đường.", "en": "My hometown is in a province in the south. There is a kind of soup there whose taste is slightly bitter, but which is extremely refreshing. In the past only part of the older people liked to drink it. As the number of times young people go home has increased, this soup has also slowly become common. Some people add a little something sweet; some insist on the original taste. Each time I go back, I still first have a bowl with no sugar. The little sweetness after the bitterness feels as if it has washed off the dust of the whole journey."}]}]}, {"l": 14, "texts": [{"n": 1, "zh": "对话：阿玲出差前整理箱子", "vi": "Hội thoại: A Linh sắp xếp vali trước khi đi công tác", "en": "Dialogue: A Linh packs her suitcase before a business trip", "kw": ["出差", "毛巾", "污染", "牙膏", "空", "省", "行", "重"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你明天出差，箱子整理好了吗？", "p": ["nǐ", "míng", "tiān", "chū", "chāi", "", "xiāng", "zi", "zhěng", "lǐ", "hǎo", "le", "ma", ""], "vi": "Ngày mai cậu đi công tác, vali sắp xong chưa?", "en": "You're going away on business tomorrow. Have you finished packing the suitcase?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "还没有。毛巾和牙膏放进去了，可还是有点儿重。你帮我看看，这样行不行？", "p": ["hái", "méi", "yǒu", "", "máo", "jīn", "hé", "yá", "gāo", "fàng", "jìn", "qù", "le", "", "kě", "hái", "shì", "yǒu", "diǎn", "r", "zhòng", "", "nǐ", "bāng", "wǒ", "kàn", "kàn", "", "zhè", "yàng", "xíng", "bù", "xíng", ""], "vi": "Chưa. Khăn và kem đánh răng đã để vào, nhưng vẫn hơi nặng. Cậu xem giúp, như thế có ổn không?", "en": "Not yet. The towel and the toothpaste are in, but it's still a bit heavy. Help me have a look — is this all right?"}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "那两瓶水可以拿出来。路上再买，也能少一点儿包装污染。而且箱子里还能空出一些地方。", "p": ["nà", "liǎng", "píng", "shuǐ", "kě", "yǐ", "ná", "chū", "lái", "", "lù", "shàng", "zài", "mǎi", "", "yě", "néng", "shǎo", "yì", "diǎn", "r", "bāo", "zhuāng", "wū", "rǎn", "", "ér", "qiě", "xiāng", "zi", "lǐ", "hái", "néng", "kòng", "chū", "yì", "xiē", "dì", "fāng", ""], "vi": "Hai chai nước ấy có thể lấy ra. Dọc đường mua thêm, cũng bớt một chút ô nhiễm bao bì. Và trong vali còn để trống được một ít chỗ.", "en": "You can take those two bottles of water out. Buying more on the way will also mean a little less packaging pollution. And there will still be some empty space left in the suitcase."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "说得对。这样能省一点分量，提起来也轻松。", "p": ["shuō", "de", "duì", "", "zhè", "yàng", "néng", "shěng", "yì", "diǎn", "fèn", "liàng", "", "tí", "qǐ", "lái", "yě", "qīng", "sōng", ""], "vi": "Đúng đó. Như vậy tiết kiệm được một chút sức, xách cũng nhẹ hơn.", "en": "That's right. This way I can save a little weight, and it will also be easier to lift."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "证件放在最上面了吗？", "p": ["zhèng", "jiàn", "fàng", "zài", "zuì", "shàng", "miàn", "le", "ma", ""], "vi": "Giấy tờ để trên cùng chưa?", "en": "Are your documents on the very top?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "放了。现在这样应该就行。", "p": ["fàng", "le", "", "xiàn", "zài", "zhè", "yàng", "yīng", "gāi", "jiù", "xíng", ""], "vi": "Để rồi. Giờ như thế chắc được.", "en": "They're in. It should be all right like this now."}]}, {"n": 2, "zh": "对话：店长请小雪先把卫生间收拾一下", "vi": "Hội thoại: Quản lý nhờ Tiểu Tuyết dọn nhà vệ sinh trước", "en": "Dialogue: The shop manager asks Xiaoxue to tidy the bathroom first", "kw": ["卫生间", "抱歉", "盒子", "速度", "扔", "以", "脏"], "lines": [{"s": "店长", "sp": ["diàn", "zhǎng"], "t": "小雪，抱歉，开门前还想请你先看一下卫生间。", "p": ["xiǎo", "xuě", "", "bào", "qiàn", "", "kāi", "mén", "qián", "hái", "xiǎng", "qǐng", "nǐ", "xiān", "kàn", "yí", "xià", "wèi", "shēng", "jiān", ""], "vi": "Tiểu Tuyết, xin lỗi, trước khi mở cửa chị muốn nhờ em xem nhà vệ sinh trước.", "en": "Xiaoxue, I'm sorry, but before we open I'd like you to look at the bathroom first."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "好。我刚才看见洗手台有点脏，还有两个空盒子扔在角落里。", "p": ["hǎo", "", "wǒ", "gāng", "cái", "kàn", "jiàn", "xǐ", "shǒu", "tái", "yǒu", "diǎn", "zàng", "", "hái", "yǒu", "liǎng", "gè", "kōng", "hé", "zi", "rēng", "zài", "jiǎo", "luò", "lǐ", ""], "vi": "Được. Lúc nãy em thấy bồn rửa hơi bẩn, còn hai hộp rỗng bị bỏ ở góc.", "en": "All right. I just saw that the washbasin is a bit dirty, and there are also two empty boxes thrown in the corner."}, {"s": "店长", "sp": ["diàn", "zhǎng"], "t": "那就先把脏的擦掉，盒子收起来。今天客人来得早，速度得快一点。", "p": ["nà", "jiù", "xiān", "bǎ", "zàng", "de", "cā", "diào", "", "hé", "zi", "shōu", "qǐ", "lái", "", "jīn", "tiān", "kè", "rén", "lái", "děi", "zǎo", "", "sù", "dù", "de", "kuài", "yì", "diǎn", ""], "vi": "Vậy hãy lau chỗ bẩn trước, thu các hộp lại. Hôm nay khách đến sớm, tốc độ phải nhanh hơn một chút.", "en": "Then wipe the dirty places first, and put the boxes away. The customers will come early today, so the speed needs to be a little quicker."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "我以最快的速度做。垃圾桶也一起换了吧？", "p": ["wǒ", "yǐ", "zuì", "kuài", "de", "sù", "dù", "zuò", "", "lā", "jī", "tǒng", "yě", "yì", "qǐ", "huàn", "le", "ba", ""], "vi": "Em sẽ làm với tốc độ nhanh nhất. Thùng rác cũng đổi luôn chứ ạ?", "en": "I'll do it at the fastest speed I can. Shall I change the bin as well?"}, {"s": "店长", "sp": ["diàn", "zhǎng"], "t": "换了。做完跟我说一声，我们再开灯开门。", "p": ["huàn", "le", "", "zuò", "wán", "gēn", "wǒ", "shuō", "yì", "shēng", "", "wǒ", "men", "zài", "kāi", "dēng", "kāi", "mén", ""], "vi": "Đổi đi. Xong thì nói chị một tiếng, mình mới bật đèn mở cửa.", "en": "Yes, change it. Tell me when you've finished, and then we'll turn on the lights and open the door."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "好，我现在就去。", "p": ["hǎo", "", "wǒ", "xiàn", "zài", "jiù", "qù", ""], "vi": "Vâng, em đi ngay đây.", "en": "All right, I'll go right now."}]}, {"n": 3, "zh": "对话：周南为关灯夜做了一张海报", "vi": "Hội thoại: Châu Nam làm một tấm áp phích cho đêm tắt đèn", "en": "Dialogue: Zhou Nan has made a poster for Lights-Off Night", "kw": ["得意", "地球", "既然", "目的", "暖", "停"], "lines": [{"s": "阿玲", "sp": ["ā", "líng"], "t": "你怎么这么得意？手里那张画的是什么？", "p": ["nǐ", "zěn", "me", "zhè", "me", "dé", "yì", "", "shǒu", "lǐ", "nà", "zhāng", "huà", "de", "shì", "shén", "me", ""], "vi": "Sao cậu đắc ý thế? Tấm vẽ trên tay là gì?", "en": "Why do you look so pleased with yourself? What's that picture in your hand?"}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "下周五学校要办“关灯夜”。我画了海报。目的很简单：让灯停一小时，让地球少热一点儿。", "p": ["xià", "zhōu", "wǔ", "xué", "xiào", "yào", "bàn", "", "guān", "dēng", "yè", "", "", "wǒ", "huà", "le", "hǎi", "bào", "", "mù", "dì", "hěn", "jiǎn", "dān", "", "ràng", "dēng", "tíng", "yì", "xiǎo", "shí", "", "ràng", "dì", "qiú", "shǎo", "rè", "yì", "diǎn", "r", ""], "vi": "Thứ sáu tuần sau trường tổ chức «Đêm tắt đèn». Mình vẽ áp phích. Mục đích rất giản: để đèn dừng một giờ, để Trái Đất bớt nóng một chút.", "en": "Next Friday the school is holding Lights-Off Night. I drew the poster. The aim is simple: to let the lights stop for an hour, and to let the Earth get a little less hot."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "既然是晚上，天气还暖，关灯应该没问题。你海报上写了时间吗？", "p": ["jì", "rán", "shì", "wǎn", "shàng", "", "tiān", "qì", "hái", "nuǎn", "", "guān", "dēng", "yīng", "gāi", "méi", "wèn", "tí", "", "nǐ", "hǎi", "bào", "shàng", "xiě", "le", "shí", "jiān", "ma", ""], "vi": "Đã là buổi tối, thời tiết còn ấm, tắt đèn chắc không sao. Áp phích cậu có ghi giờ không?", "en": "Since it's in the evening and the weather is still warm, turning the lights off should be all right. Did you write the time on your poster?"}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "写了。八点开始，九点结束。教室、走廊都参加。", "p": ["xiě", "le", "", "bā", "diǎn", "kāi", "shǐ", "", "jiǔ", "diǎn", "jié", "shù", "", "jiào", "shì", "", "zǒu", "láng", "dōu", "cān", "jiā", ""], "vi": "Ghi rồi. Tám giờ bắt đầu, chín giờ kết thúc. Lớp học, hành lang đều tham gia.", "en": "I did. It starts at eight and ends at nine. The classrooms and the corridors will all take part."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "那我帮你贴到楼下。别太得意，字再写清楚一点就更好了。", "p": ["nà", "wǒ", "bāng", "nǐ", "tiē", "dào", "lóu", "xià", "", "bié", "tài", "dé", "yì", "", "zì", "zài", "xiě", "qīng", "chǔ", "yì", "diǎn", "jiù", "gèng", "hǎo", "le", ""], "vi": "Vậy mình dán giúp xuống tầng dưới. Đừng đắc ý quá, chữ viết rõ hơn nữa thì càng tốt.", "en": "Then I'll help you put it up downstairs. Don't be too pleased with yourself — it would be even better if the characters were a little clearer."}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "好，我回去改两个字。", "p": ["hǎo", "", "wǒ", "huí", "qù", "gǎi", "liǎng", "gè", "zì", ""], "vi": "Được, mình về sửa hai chữ.", "en": "All right, I'll go back and change two of the characters."}]}, {"n": 4, "zh": "短文：我开始少拿一只塑料袋", "vi": "Đoạn văn: Tôi bắt đầu cầm ít hơn một túi ni-lông", "en": "Passage: I have started taking one fewer plastic bag", "kw": ["塑料袋", "鼓励", "减少", "拒绝", "数量", "于是"], "lines": [{"s": "", "sp": [], "t": "超市的塑料袋用起来确实方便，可数量一大，就很难再看不见。有一次收银员习惯性地递过来两只，我第一次试着拒绝了一只，改用自己带的布袋。收银员没有不高兴，还轻轻点了点头，像是在鼓励我。于是后来再出门，我把布袋放进包里，能少拿就少拿。减少一只袋子，看起来是小事，可每次少拿一点，袋子就不会在家里越堆越高。", "p": ["chāo", "shì", "de", "sù", "liào", "dài", "yòng", "qǐ", "lái", "què", "shí", "fāng", "biàn", "", "kě", "shù", "liàng", "yí", "dà", "", "jiù", "hěn", "nán", "zài", "kàn", "bú", "jiàn", "", "yǒu", "yí", "cì", "shōu", "yín", "yuán", "xí", "guàn", "xìng", "dì", "dì", "guò", "lái", "liǎng", "zhǐ", "", "wǒ", "dì", "yī", "cì", "shì", "zhe", "jù", "jué", "le", "yì", "zhī", "", "gǎi", "yòng", "zì", "jǐ", "dài", "de", "bù", "dài", "", "shōu", "yín", "yuán", "méi", "yǒu", "bù", "gāo", "xìng", "", "hái", "qīng", "qīng", "diǎn", "le", "diǎn", "tóu", "", "xiàng", "shì", "zài", "gǔ", "lì", "wǒ", "", "yú", "shì", "hòu", "lái", "zài", "chū", "mén", "", "wǒ", "bǎ", "bù", "dài", "fàng", "jìn", "bāo", "lǐ", "", "néng", "shǎo", "ná", "jiù", "shǎo", "ná", "", "jiǎn", "shǎo", "yì", "zhī", "dài", "zi", "", "kàn", "qǐ", "lái", "shì", "xiǎo", "shì", "", "kě", "měi", "cì", "shǎo", "ná", "yì", "diǎn", "", "dài", "zi", "jiù", "bú", "huì", "zài", "jiā", "lǐ", "yuè", "duī", "yuè", "gāo", ""], "vi": "Túi ni-lông ở siêu thị dùng thì quả tiện, nhưng số lượng một khi đã lớn thì khó mà không nhìn thấy. Có lần nhân viên thu ngân quen tay đưa tới hai chiếc, lần đầu tôi thử từ chối một chiếc, đổi sang túi vải tự mang. Nhân viên không khó chịu, còn gật nhẹ như đang khuyến khích tôi. Thế là những lần ra khỏi cửa sau, tôi bỏ túi vải vào cặp, có thể cầm ít thì cầm ít. Giảm một chiếc túi nhìn thì là việc nhỏ, nhưng lần nào cũng cầm ít hơn một chút thì túi sẽ không chồng cao mãi trong nhà.", "en": "Plastic bags at the supermarket are certainly convenient to use, but once the number becomes large, they are hard to ignore. Once a cashier handed me two out of habit. For the first time I tried refusing one, and used a cloth bag I had brought instead. The cashier was not unhappy, and even nodded slightly, as if to encourage me. So later, when I went out again, I put the cloth bag in my backpack, and took fewer whenever I could. Reducing the count by one bag looks like a small thing, but if you take a little fewer each time, the bags will not pile higher and higher at home."}]}, {"n": 5, "zh": "短文：把丢掉的习惯也一起丢掉", "vi": "Đoạn văn: Hãy vứt luôn cả thói quen vứt đại", "en": "Passage: Throw away the habit of throwing things away, too", "kw": ["垃圾桶", "乘坐", "美丽", "温度", "丢"], "lines": [{"s": "", "sp": [], "t": "想让身边的环境美丽一点，其实不必等很大的改变。乘坐公交时，空杯子不要随手丢在座位下，下车时带去站里的垃圾桶。夏天把温度调高一度，冬天调低一度，房间一样能住。这些事谁都会，难的是每次都记得做。我现在出门会先看一看口袋里有没有要丢的东西。能少丢一点，路上就会干净一点，心情也会安静一点。", "p": ["xiǎng", "ràng", "shēn", "biān", "de", "huán", "jìng", "měi", "lì", "yì", "diǎn", "", "qí", "shí", "bú", "bì", "děng", "hěn", "dà", "de", "gǎi", "biàn", "", "chéng", "zuò", "gōng", "jiāo", "shí", "", "kōng", "bēi", "zi", "bú", "yào", "suí", "shǒu", "diū", "zài", "zuò", "wèi", "xià", "", "xià", "chē", "shí", "dài", "qù", "zhàn", "lǐ", "de", "lā", "jī", "tǒng", "", "xià", "tiān", "bǎ", "wēn", "dù", "diào", "gāo", "yí", "dù", "", "dōng", "tiān", "diào", "dī", "yí", "dù", "", "fáng", "jiān", "yí", "yàng", "néng", "zhù", "", "zhè", "xiē", "shì", "shéi", "dōu", "huì", "", "nán", "de", "shì", "měi", "cì", "dōu", "jì", "de", "zuò", "", "wǒ", "xiàn", "zài", "chū", "mén", "huì", "xiān", "kàn", "yí", "kàn", "kǒu", "dài", "lǐ", "yǒu", "méi", "yǒu", "yào", "diū", "de", "dōng", "xi", "", "néng", "shǎo", "diū", "yì", "diǎn", "", "lù", "shàng", "jiù", "huì", "gān", "jìng", "yì", "diǎn", "", "xīn", "qíng", "yě", "huì", "ān", "jìng", "yì", "diǎn", ""], "vi": "Muốn môi trường quanh mình đẹp hơn một chút, thật ra chẳng cần đợi thay đổi lớn. Khi đi xe buýt, đừng tiện tay vứt cốc không dưới ghế, lúc xuống xe hãy mang tới thùng rác ở trạm. Mùa hè chỉnh nhiệt độ lên một độ, mùa đông xuống một độ, phòng vẫn ở được. Việc ấy ai cũng biết, cái khó là lần nào cũng nhớ làm. Giờ ra khỏi cửa tôi nhìn trước trong túi còn gì phải vứt không. Vứt ít hơn một chút thì đường sạch hơn một chút, tâm trạng cũng yên hơn một chút.", "en": "If you want the surroundings to be a little more beautiful, you do not really have to wait for a big change. When you ride the bus, don't casually throw an empty cup under the seat; take it to the bin at the stop when you get off. In summer turn the temperature up one degree, in winter down one degree, and the room is still perfectly livable. Everyone can do these things; the hard part is remembering to do them every time. Now, when I go out, I first look in my pockets to see whether there is anything I need to throw away. If I can throw a little less away, the road will be a little cleaner, and my mood will also be a little quieter."}]}]}, {"l": 15, "texts": [{"n": 1, "zh": "对话：周南的父亲让孩子寒假坚持弹钢琴", "vi": "Hội thoại: Bố Châu Nam để con kiên trì đánh piano trong kỳ nghỉ đông", "en": "Dialogue: Zhou Nan's father has the child keep up the piano over the winter holiday", "kw": ["弹钢琴", "父亲", "寒假", "孙子", "棒", "假"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "周南，你弟弟寒假还去上课吗？", "p": ["zhōu", "nán", "", "nǐ", "dì", "di", "hán", "jià", "hái", "qù", "shàng", "kè", "ma", ""], "vi": "Châu Nam, em trai cậu kỳ nghỉ đông vẫn đi học chứ?", "en": "Zhou Nan, is your little brother still going to class in the winter holiday?"}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "去。我父亲说，假可以放，可弹钢琴不能停。每天半小时，由他看着。", "p": ["qù", "", "wǒ", "fù", "qin", "shuō", "", "jià", "kě", "yǐ", "fàng", "", "kě", "tán", "gāng", "qín", "bù", "néng", "tíng", "", "měi", "tiān", "bàn", "xiǎo", "shí", "", "yóu", "tā", "kàn", "zhe", ""], "vi": "Có. Bố mình bảo, nghỉ thì được nghỉ, nhưng đàn piano không được dừng. Mỗi ngày nửa tiếng, do bố trông.", "en": "Yes. My father says he can have the holiday, but the piano must not stop. Half an hour a day, and my father watches him."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "小朋友能坐得住吗？", "p": ["xiǎo", "péng", "you", "néng", "zuò", "de", "zhù", "ma", ""], "vi": "Bé ngồi yên được không?", "en": "Can the little one sit still for that?"}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "一开始不太愿意，后来弹了一首简单的，爷爷还夸他棒。他是家里最小的孙子，听了特别高兴。", "p": ["yī", "kāi", "shǐ", "bú", "tài", "yuàn", "yì", "", "hòu", "lái", "dàn", "le", "yì", "shǒu", "jiǎn", "dān", "de", "", "yé", "yé", "hái", "kuā", "tā", "bàng", "", "tā", "shì", "jiā", "lǐ", "zuì", "xiǎo", "de", "sūn", "zi", "", "tīng", "le", "tè", "bié", "gāo", "xìng", ""], "vi": "Lúc đầu không mấy muốn, sau đàn được một bài đơn giản, ông còn khen giỏi. Cậu ấy là cháu nội nhỏ nhất trong nhà, nghe vậy vui lắm.", "en": "At first he wasn't very willing. Later he played a simple piece, and Grandpa even praised him for being great. He's the youngest grandson in the family, and he was especially happy to hear that."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "那倒是个好办法。先让他觉得自己行。", "p": ["nà", "dào", "shì", "gè", "hǎo", "bàn", "fǎ", "", "xiān", "ràng", "tā", "jué", "de", "zì", "jǐ", "xíng", ""], "vi": "Thế thì là cách hay. Để cậu ấy thấy mình làm được trước.", "en": "That's a good way, actually. Let him feel first that he can do it."}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "是啊。我父亲还说，假期里养成的习惯，开学才带得走。", "p": ["shì", "a", "", "wǒ", "fù", "qin", "hái", "shuō", "", "jià", "qī", "lǐ", "yǎng", "chéng", "de", "xí", "guàn", "", "kāi", "xué", "cái", "dài", "de", "zǒu", ""], "vi": "Phải. Bố mình còn nói, thói quen nuôi trong kỳ nghỉ thì lúc khai giảng mới mang đi được.", "en": "Yes. My father also says that a habit formed in the holiday is one you can take with you when term starts."}]}, {"n": 2, "zh": "对话：小雪家早上总为出门着急", "vi": "Hội thoại: Nhà Tiểu Tuyết buổi sáng cứ vội vì ra khỏi cửa", "en": "Dialogue: Xiaoxue's house is always in a rush in the morning", "kw": ["厕所", "管理", "批评", "赶", "弄", "响", "醒"], "lines": [{"s": "阿玲", "sp": ["ā", "líng"], "t": "你今天怎么气喘吁吁的？", "p": ["nǐ", "jīn", "tiān", "zěn", "me", "qì", "chuǎn", "xū", "xū", "de", ""], "vi": "Hôm nay cậu sao thở hổn hển thế?", "en": "Why are you so out of breath today?"}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "早上闹钟响了，弟弟还不醒。等他醒了又去厕所很久，我们出门就得赶车。", "p": ["zǎo", "shàng", "nào", "zhōng", "xiǎng", "le", "", "dì", "di", "hái", "bù", "xǐng", "", "děng", "tā", "xǐng", "le", "yòu", "qù", "cè", "suǒ", "hěn", "jiǔ", "", "wǒ", "men", "chū", "mén", "jiù", "de", "gǎn", "chē", ""], "vi": "Sáng đồng hồ reo, em trai vẫn chưa thức. Đợi cậu ấy thức rồi lại vào nhà vệ sinh rất lâu, ra khỏi cửa là phải chạy cho kịp xe.", "en": "The alarm went off in the morning, and my little brother still wasn't awake. After he woke up he was in the bathroom for a long time, so when we left we had to rush for the bus."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "你妈妈没说他吗？", "p": ["nǐ", "mā", "mā", "méi", "shuō", "tā", "ma", ""], "vi": "Mẹ cậu không nói gì à?", "en": "Didn't your mother say anything to him?"}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "说了。可一批评，他就更慢。我妈现在想先教他管理时间，把衣服昨晚就弄好。", "p": ["shuō", "le", "", "kě", "yì", "pī", "píng", "", "tā", "jiù", "gèng", "màn", "", "wǒ", "mā", "xiàn", "zài", "xiǎng", "xiān", "jiào", "tā", "guǎn", "lǐ", "shí", "jiān", "", "bǎ", "yī", "fú", "zuó", "wǎn", "jiù", "nòng", "hǎo", ""], "vi": "Có. Nhưng vừa phê bình là cậu ấy càng chậm. Giờ mẹ muốn dạy cậu ấy quản lý thời gian trước, quần áo thì tối hôm trước sắp sẵn.", "en": "She did. But as soon as she's critical, he gets even slower. Now my mum wants to teach him first to manage his time, and to get his clothes ready the night before."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "这办法好。赶车的时候一着急，谁都会不高兴。", "p": ["zhè", "bàn", "fǎ", "hǎo", "", "gǎn", "chē", "de", "shí", "hòu", "yì", "zháo", "jí", "", "shéi", "dōu", "huì", "bù", "gāo", "xìng", ""], "vi": "Cách ấy hay. Lúc chạy cho kịp xe mà sốt ruột, ai cũng không vui.", "en": "That's a good idea. When you're rushing for the bus and getting anxious, nobody is in a good mood."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "对。今晚我先帮他把书包弄整齐，明天试一天。", "p": ["duì", "", "jīn", "wǎn", "wǒ", "xiān", "bāng", "tā", "bǎ", "shū", "bāo", "nòng", "zhěng", "qí", "", "míng", "tiān", "shì", "yì", "tiān", ""], "vi": "Đúng. Tối nay mình giúp cậu ấy xếp cặp cho gọn, ngày mai thử một ngày.", "en": "Yes. Tonight I'll first help him get his schoolbag straight, and we'll try it for a day tomorrow."}]}, {"n": 3, "zh": "对话：诊所里的一次小小表扬", "vi": "Hội thoại: Một lời khen nhỏ trong phòng khám", "en": "Dialogue: A little bit of praise at the clinic", "kw": ["表扬", "打针", "护士", "怀疑", "千万"], "lines": [{"s": "阿玲", "sp": ["ā", "líng"], "t": "陈晓的妹妹今天去打针，哭了吗？", "p": ["chén", "xiǎo", "de", "mèi", "mèi", "jīn", "tiān", "qù", "dǎ", "zhēn", "", "kū", "le", "ma", ""], "vi": "Em gái Trần Hiểu hôm nay đi tiêm, có khóc không?", "en": "Chen Xiao's little sister went to have an injection today. Did she cry?"}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "开始有点儿怕。护士先表扬她站得直，又说“千万别看针，数到三就好”。她还怀疑自己做不到，后来真的没哭。", "p": ["kāi", "shǐ", "yǒu", "diǎn", "r", "pà", "", "hù", "shi", "xiān", "biǎo", "yáng", "tā", "zhàn", "de", "zhí", "", "yòu", "shuō", "", "qiān", "wàn", "bié", "kàn", "zhēn", "", "shù", "dào", "sān", "jiù", "hǎo", "", "", "tā", "hái", "huái", "yí", "zì", "jǐ", "zuò", "bú", "dào", "", "hòu", "lái", "zhēn", "de", "méi", "kū", ""], "vi": "Lúc đầu hơi sợ. Cô y tá khen trước là đứng thẳng, lại nói «nhất định đừng nhìn kim, đếm đến ba là xong». Bé còn nghi mình làm không được, sau đúng là không khóc.", "en": "She was a little afraid at first. The nurse first praised her for standing up straight, and also said, \"Whatever you do, don't look at the needle; count to three and it will be over.\" She still doubted she could do it, and then she really didn't cry."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "这护士真会说话。", "p": ["zhè", "hù", "shi", "zhēn", "huì", "shuō", "huà", ""], "vi": "Cô y tá ấy biết nói thật.", "en": "That nurse really knows how to speak to a child."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "是啊。陈晓说，回家路上妹妹还问：“我今天是不是挺勇敢？”", "p": ["shì", "a", "", "chén", "xiǎo", "shuō", "", "huí", "jiā", "lù", "shàng", "mèi", "mèi", "hái", "wèn", "", "", "wǒ", "jīn", "tiān", "shì", "bú", "shì", "tǐng", "yǒng", "gǎn", "", ""], "vi": "Phải. Trần Hiểu bảo, trên đường về bé còn hỏi: «Hôm nay em có dũng cảm không?»", "en": "Yes. Chen Xiao said that on the way home she even asked, \"Was I quite brave today?\""}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "那就再表扬一次。让她记得，怕也可以把事情做完。", "p": ["nà", "jiù", "zài", "biǎo", "yáng", "yí", "cì", "", "ràng", "tā", "jì", "de", "", "pà", "yě", "kě", "yǐ", "bǎ", "shì", "qíng", "zuò", "wán", ""], "vi": "Vậy thì khen thêm lần nữa. Để bé nhớ, sợ vẫn làm xong việc được.", "en": "Then praise her once more. Let her remember that even when you're afraid, you can still finish the thing."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "我回头告诉陈晓。千万别只说“不哭就好”，要把她哪一点做好了说出来。", "p": ["wǒ", "huí", "tóu", "gào", "sù", "chén", "xiǎo", "", "qiān", "wàn", "bié", "zhǐ", "shuō", "", "bù", "kū", "jiù", "hǎo", "", "", "yào", "bǎ", "tā", "nǎ", "yì", "diǎn", "zuò", "hǎo", "le", "shuō", "chū", "lái", ""], "vi": "Lát mình nói với Trần Hiểu. Nhất định đừng chỉ nói «không khóc là được», phải nói rõ bé làm tốt chỗ nào.", "en": "I'll tell Chen Xiao later. Be sure not to say only \"It's good you didn't cry\"; say which part she did well."}]}, {"n": 4, "zh": "短文：敲门进来之前", "vi": "Đoạn văn: Trước khi gõ cửa bước vào", "en": "Passage: Before you knock and come in", "kw": ["儿童", "故意", "合适", "整理", "骗", "敲"], "lines": [{"s": "", "sp": [], "t": "有的儿童不是故意要把房间弄乱，只是还没找到合适的办法把东西放回去。也有的孩子说“作业写完了”，其实是想先去玩，这和骗人不远。与其一开口就生气，不如先敲敲他的门，进房间一起整理。把铅笔放进笔袋，把书放回桌上，再问他：下一件事打算怎么做。孩子需要的，常常不是一句重话，而是一个可以跟着做的样子。", "p": ["yǒu", "de", "ér", "tóng", "bú", "shì", "gù", "yì", "yào", "bǎ", "fáng", "jiān", "nòng", "luàn", "", "zhǐ", "shì", "hái", "méi", "zhǎo", "dào", "hé", "shì", "de", "bàn", "fǎ", "bǎ", "dōng", "xi", "fàng", "huí", "qù", "", "yě", "yǒu", "de", "hái", "zi", "shuō", "", "zuò", "yè", "xiě", "wán", "le", "", "", "qí", "shí", "shì", "xiǎng", "xiān", "qù", "wán", "", "zhè", "hé", "piàn", "rén", "bù", "yuǎn", "", "yǔ", "qí", "yì", "kāi", "kǒu", "jiù", "shēng", "qì", "", "bù", "rú", "xiān", "qiāo", "qiāo", "tā", "de", "mén", "", "jìn", "fáng", "jiān", "yì", "qǐ", "zhěng", "lǐ", "", "bǎ", "qiān", "bǐ", "fàng", "jìn", "bǐ", "dài", "", "bǎ", "shū", "fàng", "huí", "zhuō", "shàng", "", "zài", "wèn", "tā", "", "xià", "yí", "jiàn", "shì", "dǎ", "suàn", "zěn", "me", "zuò", "", "hái", "zi", "xū", "yào", "de", "", "cháng", "cháng", "bú", "shì", "yí", "jù", "zhòng", "huà", "", "ér", "shì", "yí", "gè", "kě", "yǐ", "gēn", "zhe", "zuò", "de", "yàng", "zi", ""], "vi": "Có trẻ em không phải cố ý làm loạn phòng, chỉ chưa tìm ra cách phù hợp để để đồ lại chỗ cũ. Cũng có trẻ nói «bài đã viết xong», thật ra muốn đi chơi trước, thế là gần với việc lừa. Thay vì vừa mở miệng đã giận, hãy gõ cửa phòng trước, vào cùng sắp xếp. Bỏ bút vào túi, để sách lại lên bàn, rồi hỏi: việc tiếp theo định làm thế nào. Điều trẻ cần thường không phải một câu nặng lời, mà là một gương để làm theo.", "en": "Some children do not make a mess of the room on purpose; they just have not yet found a suitable way to put things back. There are also children who say \"I've finished my homework\" when they really want to go and play first, which is not far from tricking someone. Rather than getting angry the moment you open your mouth, you might first knock on the door, go in, and tidy up together. Put the pencils in the case, put the books back on the desk, then ask: what do you plan to do next? What a child often needs is not a heavy sentence, but an example they can follow."}]}, {"n": 5, "zh": "短文：教室左右两边的两种孩子", "vi": "Đoạn văn: Hai kiểu trẻ ở hai bên lớp", "en": "Passage: Two kinds of children on the left and right of the classroom", "kw": ["粗心", "害羞", "骄傲", "左右", "笨", "懒"], "lines": [{"s": "", "sp": [], "t": "教儿童的老师常会看到：教室左右两边坐着完全不同的孩子。有的因为粗心把题抄错，并不等于笨；有的因为懒得问，也不等于不会。还有的孩子很害羞，一被问起就低头；有的刚刚答对，又容易骄傲。要让他们安静地学下去，先得让他们觉得自己可以被看懂。错了就慢慢改，对了也不必说得太满。孩子不是桌子上的物品，他们会看你的脸色，也会听你口气里的那一点温度。", "p": ["jiào", "ér", "tóng", "de", "lǎo", "shī", "cháng", "huì", "kàn", "dào", "", "jiào", "shì", "zuǒ", "yòu", "liǎng", "biān", "zuò", "zhe", "wán", "quán", "bù", "tóng", "de", "hái", "zi", "", "yǒu", "de", "yīn", "wèi", "cū", "xīn", "bǎ", "tí", "chāo", "cuò", "", "bìng", "bù", "děng", "yú", "bèn", "", "yǒu", "de", "yīn", "wèi", "lǎn", "de", "wèn", "", "yě", "bù", "děng", "yú", "bú", "huì", "", "hái", "yǒu", "de", "hái", "zi", "hěn", "hài", "xiū", "", "yí", "bèi", "wèn", "qǐ", "jiù", "dī", "tóu", "", "yǒu", "de", "gāng", "gāng", "dá", "duì", "", "yòu", "róng", "yì", "jiāo", "ào", "", "yào", "ràng", "tā", "men", "ān", "jìng", "dì", "xué", "xià", "qù", "", "xiān", "de", "ràng", "tā", "men", "jué", "de", "zì", "jǐ", "kě", "yǐ", "bèi", "kàn", "dǒng", "", "cuò", "le", "jiù", "màn", "màn", "gǎi", "", "duì", "le", "yě", "bú", "bì", "shuō", "de", "tài", "mǎn", "", "hái", "zi", "bú", "shì", "zhuō", "zi", "shàng", "de", "wù", "pǐn", "", "tā", "men", "huì", "kàn", "nǐ", "de", "liǎn", "sè", "", "yě", "huì", "tīng", "nǐ", "kǒu", "qì", "lǐ", "de", "nà", "yì", "diǎn", "wēn", "dù", ""], "vi": "Giáo viên dạy trẻ thường thấy: hai bên trái phải của lớp ngồi những đứa hoàn toàn khác nhau. Có em vì sơ ý chép sai đề, không có nghĩa là vụng; có em vì lười hỏi, cũng không có nghĩa là không biết. Lại có em rất nhút nhát, vừa bị hỏi đã cúi đầu; có em mới trả lời đúng đã dễ kiêu. Muốn các em học yên, trước hết phải để các em thấy mình được hiểu. Sai thì sửa từ từ, đúng cũng đừng nói quá đầy. Trẻ không phải đồ trên bàn, chúng nhìn nét mặt bạn, cũng nghe chút hơi ấm trong giọng bạn.", "en": "Teachers of children often see this: on the left and right of the classroom sit completely different children. Some copy a question wrong out of carelessness, which does not mean they are slow; some are too lazy to ask, which does not mean they cannot do it. There are also children who are very shy and look down as soon as they are asked; and some who, having just answered correctly, can easily become proud. If you want them to go on learning quietly, you first have to let them feel they can be understood. When they are wrong, change it slowly; when they are right, there is no need to say too much. Children are not objects on a desk. They watch your face, and they also hear that little bit of warmth in your tone."}]}]}, {"l": 16, "texts": [{"n": 1, "zh": "对话：林安办签证把表格填错了", "vi": "Hội thoại: Lâm An điền nhầm đơn xin visa", "en": "Dialogue: Lin An fills in the visa form wrongly", "kw": ["报名", "表格", "博士", "传真", "号码", "签证"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "林安，你不是要去报名那个交流项目吗？表格交了没有？", "p": ["lín", "ān", "", "nǐ", "bú", "shì", "yào", "qù", "bào", "míng", "nà", "ge", "jiāo", "liú", "xiàng", "mù", "ma", "", "biǎo", "gé", "jiāo", "le", "méi", "yǒu", ""], "vi": "Lâm An, chẳng phải cậu định đăng ký chương trình trao đổi đó sao? Đơn nộp chưa?", "en": "Lin An, weren't you going to sign up for that exchange programme? Have you handed in the form?"}, {"s": "林安", "sp": ["lín", "ān"], "t": "交了一次，可签证中心说博士推荐信上的号码写错了，让我重填一份表格。", "p": ["jiāo", "le", "yí", "cì", "", "kě", "qiān", "zhèng", "zhōng", "xīn", "shuō", "bó", "shì", "tuī", "jiàn", "xìn", "shàng", "de", "hào", "mǎ", "xiě", "cuò", "le", "", "ràng", "wǒ", "zhòng", "tián", "yí", "fèn", "biǎo", "gé", ""], "vi": "Nộp một lần rồi, nhưng trung tâm visa bảo số trên thư giới thiệu của tiến sĩ viết sai, bắt mình điền lại một đơn.", "en": "I handed one in, but the visa centre said the number on the doctoral supervisor's letter was wrong, and asked me to fill in the form again."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "那怎么办？还来得及吗？", "p": ["nà", "zěn", "me", "bàn", "", "hái", "lái", "de", "jí", "ma", ""], "vi": "Vậy sao bây giờ? Vẫn còn kịp chứ?", "en": "So what now? Is there still time?"}, {"s": "林安", "sp": ["lín", "ān"], "t": "老师说可以先把改好的推荐信传真过去，表格我今晚重新写。", "p": ["lǎo", "shī", "shuō", "kě", "yǐ", "xiān", "bǎ", "gǎi", "hǎo", "de", "tuī", "jiàn", "xìn", "chuán", "zhēn", "guò", "qù", "", "biǎo", "gé", "wǒ", "jīn", "wǎn", "chóng", "xīn", "xiě", ""], "vi": "Thầy bảo có thể fax thư giới thiệu đã sửa trước, đơn thì tối nay mình viết lại.", "en": "The teacher said I can fax over the corrected letter first, and I'll rewrite the form tonight."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "号码一定要再对一遍。签证这件事，马虎不得。", "p": ["hào", "mǎ", "yí", "dìng", "yào", "zài", "duì", "yí", "biàn", "", "qiān", "zhèng", "zhè", "jiàn", "shì", "", "mǎ", "hu", "bù", "de", ""], "vi": "Số nhất định phải đối lại một lượt. Việc visa không được sơ ý.", "en": "You must check the number again. You can't be careless with a visa."}, {"s": "林安", "sp": ["lín", "ān"], "t": "我知道。对好了再发给你看一眼。", "p": ["wǒ", "zhī", "dào", "", "duì", "hǎo", "le", "zài", "fā", "gěi", "nǐ", "kàn", "yì", "yǎn", ""], "vi": "Mình biết. Đối xong sẽ gửi cho cậu xem một mắt.", "en": "I know. Once I've checked it I'll send it over for you to look at."}]}, {"n": 2, "zh": "对话：一个小伙子被记者采访", "vi": "Hội thoại: Một chàng trai được phóng viên phỏng vấn", "en": "Dialogue: A young man is interviewed by a reporter", "kw": ["小伙子", "参观", "激动", "记者", "恐怕"], "lines": [{"s": "周南", "sp": ["zhōu", "nán"], "t": "你看这条新闻，一个小伙子在郊区开小书店，今天有记者去采访他。", "p": ["nǐ", "kàn", "zhè", "tiáo", "xīn", "wén", "", "yí", "gè", "xiǎo", "huǒ", "zi", "zài", "jiāo", "qū", "kāi", "xiǎo", "shū", "diàn", "", "jīn", "tiān", "yǒu", "jì", "zhě", "qù", "cǎi", "fǎng", "tā", ""], "vi": "Cậu xem tin này, một chàng trai mở hiệu sách nhỏ ở ngoại ô, hôm nay có phóng viên đến phỏng vấn.", "en": "Look at this news item: a young man opened a little bookshop in the suburbs, and a reporter went to interview him today."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "我好像参观过那家店。他开店的时候，恐怕家里并不都支持。", "p": ["wǒ", "hǎo", "xiàng", "cān", "guān", "guò", "nà", "jiā", "diàn", "", "tā", "kāi", "diàn", "de", "shí", "hòu", "", "kǒng", "pà", "jiā", "lǐ", "bìng", "bù", "dōu", "zhī", "chí", ""], "vi": "Hình như mình đã tham quan tiệm ấy. Lúc cậu ấy mở, e là nhà không phải ai cũng ủng hộ.", "en": "I think I've visited that shop. When he opened it, I'm afraid his family were not all in favour."}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "新闻里他说，第一次看到记者进来，自己都激动得说不出话。", "p": ["xīn", "wén", "lǐ", "tā", "shuō", "", "dì", "yī", "cì", "kàn", "dào", "jì", "zhě", "jìn", "lái", "", "zì", "jǐ", "dōu", "jī", "dòng", "de", "shuō", "bù", "chū", "huà", ""], "vi": "Trong tin cậu ấy nói, lần đầu thấy phóng viên bước vào, bản thân xúc động đến nói không nên lời.", "en": "In the report he said that the first time he saw the reporter come in, he was so excited he couldn't speak."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "能坚持下来，真不容易。", "p": ["néng", "jiān", "chí", "xià", "lái", "", "zhēn", "bù", "róng", "yì", ""], "vi": "Kiên trì được thật không dễ.", "en": "It's really not easy to have kept it going."}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "周末要是有空，我们再去参观一次吧。", "p": ["zhōu", "mò", "yào", "shi", "yǒu", "kòng", "", "wǒ", "men", "zài", "qù", "cān", "guān", "yí", "cì", "ba", ""], "vi": "Cuối tuần nếu rảnh, mình ghé tham quan thêm lần nữa đi.", "en": "If we're free at the weekend, shall we go and visit it again?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "好。我想听听他后来是怎么把店做稳的。", "p": ["hǎo", "", "wǒ", "xiǎng", "tīng", "tīng", "tā", "hòu", "lái", "shì", "zěn", "me", "bǎ", "diàn", "zuò", "wěn", "de", ""], "vi": "Được. Mình muốn nghe sau này cậu ấy làm tiệm vững thế nào.", "en": "Yes. I'd like to hear how he later got the shop onto a steady footing."}]}, {"n": 3, "zh": "对话：周南不好意思拒绝做导游", "vi": "Hội thoại: Châu Nam ngại từ chối làm hướng dẫn", "en": "Dialogue: Zhou Nan finds it hard to say no to being a guide", "kw": ["导游", "到底", "郊区", "礼貌", "失望", "原谅", "呀"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "周南，同学约你周末去郊区，你到底去不去？", "p": ["zhōu", "nán", "", "tóng", "xué", "yuē", "nǐ", "zhōu", "mò", "qù", "jiāo", "qū", "", "nǐ", "dào", "dǐ", "qù", "bú", "qù", ""], "vi": "Châu Nam, bạn rủ cậu cuối tuần ra ngoại ô, rốt cuộc cậu đi hay không?", "en": "Zhou Nan, your classmates asked you to the suburbs this weekend. Are you going or not, in the end?"}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "他们想让我当导游。可我这周作业很多，呀，我真不知道怎么拒绝才礼貌。", "p": ["tā", "men", "xiǎng", "ràng", "wǒ", "dāng", "dǎo", "yóu", "", "kě", "wǒ", "zhè", "zhōu", "zuò", "yè", "hěn", "duō", "", "ya", "", "wǒ", "zhēn", "bù", "zhī", "dào", "zěn", "me", "jù", "jué", "cái", "lǐ", "mào", ""], "vi": "Họ muốn mình làm hướng dẫn. Nhưng tuần này bài tập nhiều, ôi, mình thật không biết từ chối sao cho lịch sự.", "en": "They want me to be the guide. But I've got a lot of homework this week. Oh, I really don't know how to say no politely."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "直接说明情况就行。答应了做不到，他们反而会失望。", "p": ["zhí", "jiē", "shuō", "míng", "qíng", "kuàng", "jiù", "xíng", "", "dā", "yìng", "le", "zuò", "bú", "dào", "", "tā", "men", "fǎn", "ér", "huì", "shī", "wàng", ""], "vi": "Cứ nói rõ tình hình là được. Đã hứa mà làm không được, họ ngược lại sẽ thất vọng.", "en": "Just explain the situation clearly. If you say yes and then can't do it, they'll be disappointed instead."}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "要是他们不原谅我呢？", "p": ["yào", "shi", "tā", "men", "bù", "yuán", "liàng", "wǒ", "ne", ""], "vi": "Nếu họ không tha thứ cho mình thì sao?", "en": "What if they don't forgive me?"}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "真正的朋友会原谅的。你礼貌地说明白，比勉强去要好。", "p": ["zhēn", "zhèng", "de", "péng", "you", "huì", "yuán", "liàng", "de", "", "nǐ", "lǐ", "mào", "dì", "shuō", "míng", "bái", "", "bǐ", "miǎn", "qiǎng", "qù", "yào", "hǎo", ""], "vi": "Bạn thật sự sẽ tha thứ. Cậu nói rõ một cách lịch sự còn hơn là cố đi.", "en": "Real friends will forgive you. Explaining politely is better than going reluctantly."}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "那我今晚就跟他们说清楚。", "p": ["nà", "wǒ", "jīn", "wǎn", "jiù", "gēn", "tā", "men", "shuō", "qīng", "chǔ", ""], "vi": "Vậy tối nay mình nói rõ với họ.", "en": "Then I'll make it clear to them tonight."}]}, {"n": 4, "zh": "短文：把今天的事先做完", "vi": "Đoạn văn: Hãy làm xong việc của hôm nay đã", "en": "Passage: Finish today's work first", "kw": ["马虎", "同情", "预习", "重点", "自信", "挂", "推"], "lines": [{"s": "", "sp": [], "t": "有的事情一拖就会被推到明天。我以前也常这样：预习只看个大概，重点没画，电话一挂就把书合上。看起来是给自己留了余地，其实是把压力推给了后来的自己。后来老师并没有批评我，只是很平静地问：你是真的没时间，还是有点儿马虎？那句话谈不上严厉，我却一下子生出了同情——同情那个总在最后才着急的自己。从那以后，我先把当天的重点做完，再去休息。自信不是觉得自己什么都能拖，而是相信今天的自己可以把事情做完。", "p": ["yǒu", "de", "shì", "qíng", "yì", "tuō", "jiù", "huì", "bèi", "tuī", "dào", "míng", "tiān", "", "wǒ", "yǐ", "qián", "yě", "cháng", "zhè", "yàng", "", "yù", "xí", "zhǐ", "kàn", "gè", "dà", "gài", "", "zhòng", "diǎn", "méi", "huà", "", "diàn", "huà", "yí", "guà", "jiù", "bǎ", "shū", "hé", "shàng", "", "kàn", "qǐ", "lái", "shì", "gěi", "zì", "jǐ", "liú", "le", "yú", "dì", "", "qí", "shí", "shì", "bǎ", "yā", "lì", "tuī", "gěi", "le", "hòu", "lái", "de", "zì", "jǐ", "", "hòu", "lái", "lǎo", "shī", "bìng", "méi", "yǒu", "pī", "píng", "wǒ", "", "zhǐ", "shì", "hěn", "píng", "jìng", "dì", "wèn", "", "nǐ", "shì", "zhēn", "de", "méi", "shí", "jiān", "", "hái", "shì", "yǒu", "diǎn", "r", "mǎ", "hu", "", "nà", "jù", "huà", "tán", "bú", "shàng", "yán", "lì", "", "wǒ", "què", "yí", "xià", "zi", "shēng", "chū", "le", "tóng", "qíng", "", "", "tóng", "qíng", "nà", "ge", "zǒng", "zài", "zuì", "hòu", "cái", "zháo", "jí", "de", "zì", "jǐ", "", "cóng", "nà", "yǐ", "hòu", "", "wǒ", "xiān", "bǎ", "dàng", "tiān", "de", "zhòng", "diǎn", "zuò", "wán", "", "zài", "qù", "xiū", "xī", "", "zì", "xìn", "bú", "shì", "jué", "de", "zì", "jǐ", "shén", "me", "dōu", "néng", "tuō", "", "ér", "shì", "xiāng", "xìn", "jīn", "tiān", "de", "zì", "jǐ", "kě", "yǐ", "bǎ", "shì", "qíng", "zuò", "wán", ""], "vi": "Có việc một trì hoãn là bị đẩy sang ngày mai. Trước tôi cũng hay thế: xem trước chỉ lướt đại khái, chỗ trọng tâm chưa khoanh, vừa gác máy đã đóng sách. Trông như để cho mình một khoảng trống, thật ra là đẩy áp lực cho cái tôi về sau. Sau cô giáo không phê bình, chỉ hỏi rất điềm: em thật sự không có thời gian, hay là hơi sơ ý? Câu ấy chẳng gọi là nghiêm, tôi lại bỗng thấy thương — thương cái tôi luôn đến phút cuối mới sốt ruột. Từ đó, tôi làm xong trọng tâm trong ngày đã, rồi mới nghỉ. Tự tin không phải nghĩ mình cái gì cũng trì được, mà tin cái tôi hôm nay làm xong việc được.", "en": "Some things, once delayed, get pushed to tomorrow. I used to do this too: I would only skim the preview, leave the key points unmarked, and close the book as soon as I hung up the phone. It looked as if I was leaving myself some room, but in fact I was pushing the pressure onto my later self. Later the teacher did not criticise me; she only asked, very calmly, \"Is it that you really have no time, or are you being a little careless?\" That sentence was hardly harsh, yet I suddenly felt sympathy — sympathy for the self who always only grew anxious at the last moment. From then on I finish the day's key points first, and only then rest. Confidence is not thinking you can put everything off; it is trusting that today's self can get the work done."}]}, {"n": 5, "zh": "短文：输了，也要冷静", "vi": "Đoạn văn: Thua rồi, cũng phải bình tĩnh", "en": "Passage: Even if you lose, stay calm", "kw": ["冷静", "重视", "尊重", "敢", "输"], "lines": [{"s": "", "sp": [], "t": "比赛里总有人赢，也总有人输。输并不可怕，可怕的是一输就乱。我见过有的同学敢冲上去，也见过有的人一落后就放弃思考。真正该重视的，不是眼前这一局，而是你还敢不敢在输了以后仍然冷静地看自己。尊重对手，也尊重那个还在场上的自己。能把失败看清楚的人，下一次才有机会走得更稳。", "p": ["bǐ", "sài", "lǐ", "zǒng", "yǒu", "rén", "yíng", "", "yě", "zǒng", "yǒu", "rén", "shū", "", "shū", "bìng", "bù", "kě", "pà", "", "kě", "pà", "de", "shì", "yì", "shū", "jiù", "luàn", "", "wǒ", "jiàn", "guò", "yǒu", "de", "tóng", "xué", "gǎn", "chōng", "shàng", "qù", "", "yě", "jiàn", "guò", "yǒu", "de", "rén", "yí", "luò", "hòu", "jiù", "fàng", "qì", "sī", "kǎo", "", "zhēn", "zhèng", "gāi", "zhòng", "shì", "de", "", "bú", "shì", "yǎn", "qián", "zhè", "yì", "jú", "", "ér", "shì", "nǐ", "hái", "gǎn", "bù", "gǎn", "zài", "shū", "le", "yǐ", "hòu", "réng", "rán", "lěng", "jìng", "dì", "kàn", "zì", "jǐ", "", "zūn", "zhòng", "duì", "shǒu", "", "yě", "zūn", "zhòng", "nà", "ge", "hái", "zài", "chǎng", "shàng", "de", "zì", "jǐ", "", "néng", "bǎ", "shī", "bài", "kàn", "qīng", "chǔ", "de", "rén", "", "xià", "yí", "cì", "cái", "yǒu", "jī", "huì", "zǒu", "de", "gèng", "wěn", ""], "vi": "Trong thi đấu luôn có người thắng, cũng luôn có người thua. Thua không đáng sợ, đáng sợ là vừa thua đã loạn. Tôi thấy có bạn dám lao lên, cũng thấy có người vừa tụt lại đã bỏ suy nghĩ. Điều thật sự cần coi trọng không phải ván trước mắt, mà là bạn còn dám, sau khi thua, vẫn bình tĩnh nhìn mình hay không. Tôn trọng đối thủ, cũng tôn trọng cái tôi vẫn còn trên sân. Người nhìn rõ thất bại, lần sau mới có cơ hội đi vững hơn.", "en": "In a contest there are always people who win, and always people who lose. Losing is not what is frightening; what is frightening is falling to pieces as soon as you lose. I have seen classmates who dare to go forward, and I have also seen people who give up thinking as soon as they fall behind. What you really ought to take seriously is not this one game in front of you, but whether, after a loss, you still dare to look at yourself calmly. Respect your opponent, and also respect the self who is still on the field. Only those who can see a failure clearly have a chance, next time, of walking more steadily."}]}]}, {"l": 17, "texts": [{"n": 1, "zh": "对话：雨后的傍晚倒凉快了", "vi": "Hội thoại: Chiều sau mưa hóa ra lại mát", "en": "Dialogue: The evening after the rain turns out cool", "kw": ["广播", "凉快", "热闹", "倒", "云", "照"], "lines": [{"s": "阿玲", "sp": ["ā", "líng"], "t": "你听刚才的广播了吗？说今晚云会散开。", "p": ["nǐ", "tīng", "gāng", "cái", "de", "guǎng", "bō", "le", "ma", "", "shuō", "jīn", "wǎn", "yún", "huì", "sàn", "kāi", ""], "vi": "Cậu nghe bản tin lúc nãy không? Bảo tối nay mây sẽ tan.", "en": "Did you hear the broadcast just now? It said the clouds will clear this evening."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "听了。下午还挺热，现在倒凉快了，风也软。", "p": ["tīng", "le", "", "xià", "wǔ", "hái", "tǐng", "rè", "", "xiàn", "zài", "dào", "liáng", "kuai", "le", "", "fēng", "yě", "ruǎn", ""], "vi": "Nghe rồi. Chiều còn khá nóng, giờ hóa lại mát, gió cũng dịu.", "en": "I did. It was still quite hot in the afternoon, but now it's actually cool, and the wind is soft too."}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "那我们去河边走走？太阳一照出来，景色一定好看。", "p": ["nà", "wǒ", "men", "qù", "hé", "biān", "zǒu", "zǒu", "", "tài", "yáng", "yí", "zhào", "chū", "lái", "", "jǐng", "sè", "yí", "dìng", "hǎo", "kàn", ""], "vi": "Vậy mình ra bờ sông đi? Mặt trời vừa chiếu ra, cảnh chắc đẹp.", "en": "Shall we walk by the river then? As soon as the sun comes out and shines, the view is bound to be lovely."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "河边今晚恐怕很热闹。好多人都趁凉快出来了。", "p": ["hé", "biān", "jīn", "wǎn", "kǒng", "pà", "hěn", "rè", "nao", "", "hǎo", "duō", "rén", "dōu", "chèn", "liáng", "kuai", "chū", "lái", "le", ""], "vi": "Bờ sông tối nay e rất nhộn. Nhiều người nhân lúc mát đã ra rồi.", "en": "I'm afraid it will be very lively by the river tonight. A lot of people have come out to enjoy the cool."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "热闹点儿也好。我正好想照几张相。", "p": ["rè", "nao", "diǎn", "r", "yě", "hǎo", "", "wǒ", "zhèng", "hǎo", "xiǎng", "zhào", "jǐ", "zhāng", "xiāng", ""], "vi": "Nhộn một chút cũng hay. Mình đúng lúc muốn chụp vài tấm.", "en": "A bit of bustle is fine too. I was just wanting to take a few photos."}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "那走吧，趁云还没完全散，光线软一些。", "p": ["nà", "zǒu", "ba", "", "chèn", "yún", "hái", "méi", "wán", "quán", "sàn", "", "guāng", "xiàn", "ruǎn", "yì", "xiē", ""], "vi": "Vậy đi đi, nhân mây chưa tan hẳn, ánh sáng dịu hơn.", "en": "Let's go then, while the clouds have not fully cleared and the light is still a little softer."}]}, {"n": 2, "zh": "对话：隔壁的小狗把毛弄湿了", "vi": "Hội thoại: Cún nhà bên làm ướt lông", "en": "Dialogue: The dog next door has got its fur wet", "kw": ["难受", "严格", "抱", "干", "毛"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你听，隔壁的狗又在叫，是不是难受了？", "p": ["nǐ", "tīng", "", "gé", "bì", "de", "gǒu", "yòu", "zài", "jiào", "", "shì", "bú", "shì", "nán", "shòu", "le", ""], "vi": "Cậu nghe, chó nhà bên lại kêu, có phải khó chịu không?", "en": "Listen, the dog next door is barking again. Is it feeling unwell?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "刚才下雨，它的毛全湿了。吴姐正把它抱进门，用毛巾把毛擦干。", "p": ["gāng", "cái", "xià", "yǔ", "", "tā", "de", "máo", "quán", "shī", "le", "", "wú", "jiě", "zhèng", "bǎ", "tā", "bào", "jìn", "mén", "", "yòng", "máo", "jīn", "bǎ", "máo", "cā", "gān", ""], "vi": "Lúc nãy mưa, lông nó ướt hết. Chị Ngô đang bế nó vào cửa, dùng khăn lau khô lông.", "en": "It rained just now, and its fur got all wet. Sister Wu is carrying it in and drying its fur with a towel."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "她对狗可严格了，每天都按时喂、按时遛。", "p": ["tā", "duì", "gǒu", "kě", "yán", "gé", "le", "", "měi", "tiān", "dōu", "àn", "shí", "wèi", "", "àn", "shí", "liú", ""], "vi": "Chị ấy với chó rất nghiêm, ngày nào cũng cho ăn đúng giờ, dắt đi đúng giờ.", "en": "She's very strict with the dog: she feeds it and walks it on time every day."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "所以那只狗才那么听她的话。一叫它，它就过去让她抱。", "p": ["suǒ", "yǐ", "nà", "zhǐ", "gǒu", "cái", "nà", "me", "tīng", "tā", "de", "huà", "", "yí", "jiào", "tā", "", "tā", "jiù", "guò", "qù", "ràng", "tā", "bào", ""], "vi": "Nên con chó ấy mới nghe lời chị đến thế. Chỉ gọi một tiếng là nó lại để chị bế.", "en": "That's why the dog listens to her so well. As soon as she calls, it goes over and lets her hold it."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "毛干了就好。湿着坐在门口，看起来真可怜。", "p": ["máo", "gān", "le", "jiù", "hǎo", "", "shī", "zhe", "zuò", "zài", "mén", "kǒu", "", "kàn", "qǐ", "lái", "zhēn", "kě", "lián", ""], "vi": "Lông khô là được. Ngồi ướt ở cửa trông thương thật.", "en": "It'll be fine once the fur is dry. Sitting wet in the doorway, it really looked pitiful."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "吴姐说，今晚还要再给它吹一下。", "p": ["wú", "jiě", "shuō", "", "jīn", "wǎn", "hái", "yào", "zài", "gěi", "tā", "chuī", "yí", "xià", ""], "vi": "Chị Ngô bảo tối nay còn thổi cho nó thêm một lúc.", "en": "Sister Wu said she would also dry it with the dryer for a little while this evening."}]}, {"n": 3, "zh": "对话：放暑假去看老虎", "vi": "Hội thoại: Nghỉ hè đi xem hổ", "en": "Dialogue: Going to see the tigers in the summer holiday", "kw": ["放暑假", "活泼", "老虎", "排队", "入口", "趟"], "lines": [{"s": "周南", "sp": ["zhōu", "nán"], "t": "放暑假你想去哪儿？", "p": ["fàng", "shǔ", "jià", "nǐ", "xiǎng", "qù", "nǎ", "r", ""], "vi": "Nghỉ hè cậu muốn đi đâu?", "en": "Where do you want to go in the summer holiday?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "我想再去一趟野生园。上次在入口排了很久的队，里面的老虎却只远远看了一眼。", "p": ["wǒ", "xiǎng", "zài", "qù", "yí", "tàng", "yě", "shēng", "yuán", "", "shàng", "cì", "zài", "rù", "kǒu", "pái", "le", "hěn", "jiǔ", "de", "duì", "", "lǐ", "miàn", "de", "lǎo", "hǔ", "què", "zhǐ", "yuǎn", "yuǎn", "kàn", "le", "yì", "yǎn", ""], "vi": "Mình muốn đi thêm một chuyến vườn hoang dã. Lần trước ở cửa vào xếp hàng rất lâu, vậy mà con hổ bên trong chỉ thấy thoáng từ xa.", "en": "I'd like to make another trip to the wildlife park. Last time we queued for a long time at the entrance, but only saw the tigers from far away."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "听说那边新来了两只比较活泼的，白天常在近处走。", "p": ["tīng", "shuō", "nà", "biān", "xīn", "lái", "le", "liǎng", "zhǐ", "bǐ", "jiào", "huó", "po", "de", "", "bái", "tiān", "cháng", "zài", "jìn", "chù", "zǒu", ""], "vi": "Nghe nói bên đó mới về hai con khá hiếu động, ban ngày hay đi gần.", "en": "I heard two livelier ones have arrived, and they often walk nearby in the daytime."}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "那我们早一点儿到，少排会儿队。入口一开门就进去。", "p": ["nà", "wǒ", "men", "zǎo", "yì", "diǎn", "r", "dào", "", "shǎo", "pái", "huì", "r", "duì", "", "rù", "kǒu", "yì", "kāi", "mén", "jiù", "jìn", "qù", ""], "vi": "Vậy mình đến sớm một chút, xếp hàng ít thôi. Cửa vào vừa mở là vào.", "en": "Then let's arrive a bit earlier and queue less. We'll go in as soon as the entrance opens."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "好。这次要是能看清楚，就不枉跑这一趟。", "p": ["hǎo", "", "zhè", "cì", "yào", "shi", "néng", "kàn", "qīng", "chǔ", "", "jiù", "bù", "wǎng", "pǎo", "zhè", "yí", "tàng", ""], "vi": "Được. Lần này nếu nhìn rõ thì chuyến đi này không uổng.", "en": "All right. If we can see them clearly this time, the trip won't have been wasted."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "我带上望远镜。排队的时候还可以看看地图。", "p": ["wǒ", "dài", "shàng", "wàng", "yuǎn", "jìng", "", "pái", "duì", "de", "shí", "hòu", "hái", "kě", "yǐ", "kàn", "kàn", "dì", "tú", ""], "vi": "Mình mang ống nhòm. Lúc xếp hàng còn xem bản đồ được.", "en": "I'll bring binoculars. We can also look at the map while we're queuing."}]}, {"n": 4, "zh": "短文：森林里剩下的那一点儿空地", "vi": "Đoạn văn: Chút đất trống còn lại trong rừng", "en": "Passage: The little open ground left in the forest", "kw": ["竞争", "暖和", "森林", "社会", "剩"], "lines": [{"s": "", "sp": [], "t": "城外有一片小小的森林。春天一暖和，树和草都开始争阳光、争水。看上去只是安静的绿色，其实也是一种竞争。社会里的人有时也是这样：谁都想过得好一点，剩下的机会却并不多。我并不觉得竞争本身可怕，可怕的是只顾往前冲，把旁边的人忘了。那片森林里，高的树会挡住风，矮的草仍能在根边找到自己的位置。能一起留下来的，才算真的剩下来了。", "p": ["chéng", "wài", "yǒu", "yí", "piàn", "xiǎo", "xiǎo", "de", "sēn", "lín", "", "chūn", "tiān", "yì", "nuǎn", "huo", "", "shù", "hé", "cǎo", "dōu", "kāi", "shǐ", "zhēng", "yáng", "guāng", "", "zhēng", "shuǐ", "", "kàn", "shàng", "qù", "zhǐ", "shì", "ān", "jìng", "de", "lǜ", "sè", "", "qí", "shí", "yě", "shì", "yì", "zhǒng", "jìng", "zhēng", "", "shè", "huì", "lǐ", "de", "rén", "yǒu", "shí", "yě", "shì", "zhè", "yàng", "", "shéi", "dōu", "xiǎng", "guò", "de", "hǎo", "yì", "diǎn", "", "shèng", "xià", "de", "jī", "huì", "què", "bìng", "bù", "duō", "", "wǒ", "bìng", "bù", "jué", "de", "jìng", "zhēng", "běn", "shēn", "kě", "pà", "", "kě", "pà", "de", "shì", "zhǐ", "gù", "wǎng", "qián", "chōng", "", "bǎ", "páng", "biān", "de", "rén", "wàng", "le", "", "nà", "piàn", "sēn", "lín", "lǐ", "", "gāo", "de", "shù", "huì", "dǎng", "zhù", "fēng", "", "ǎi", "de", "cǎo", "réng", "néng", "zài", "gēn", "biān", "zhǎo", "dào", "zì", "jǐ", "de", "wèi", "zhì", "", "néng", "yì", "qǐ", "liú", "xià", "lái", "de", "", "cái", "suàn", "zhēn", "de", "shèng", "xià", "lái", "le", ""], "vi": "Ngoài thành có một khu rừng nhỏ. Mùa xuân vừa ấm, cây và cỏ đều bắt đầu tranh ánh nắng, tranh nước. Nhìn chỉ là màu xanh yên, thật ra cũng là một cuộc cạnh tranh. Người trong xã hội đôi khi cũng vậy: ai cũng muốn sống khá hơn một chút, cơ hội còn lại lại không nhiều. Tôi không thấy cạnh tranh tự nó đáng sợ, đáng sợ là chỉ lo lao tới, quên người bên cạnh. Trong khu rừng ấy, cây cao chắn gió, cỏ thấp vẫn tìm được chỗ bên gốc. Những gì ở lại cùng nhau, mới kể là thật sự còn lại.", "en": "Outside the town there is a small forest. As soon as spring turns warm, the trees and the grass start competing for sunlight and for water. It looks like nothing but quiet green, but it is also a kind of competition. People in society are sometimes like this too: everyone wants to live a little better, yet the chances that are left are not many. I do not think competition itself is frightening; what is frightening is only charging forward and forgetting the people beside you. In that forest the tall trees keep off the wind, and the low grass can still find a place by the roots. What can stay on together is what has truly been left."}]}, {"n": 5, "zh": "短文：船还在海的底下走", "vi": "Đoạn văn: Thuyền vẫn đi dưới mặt biển", "en": "Passage: The ship is still travelling under the sea", "kw": ["公里", "海洋", "排列", "仍然", "底", "梦"], "lines": [{"s": "", "sp": [], "t": "去年夏天，我坐船去看海洋。从港口出发，过了几十公里，水面仍然很宽，像没有边。船舱的窗下，是一层深得看不透的蓝。我忽然想起小时候的梦：自己走到海的底，看见鱼像灯一样排列着，安静地游过去。梦里的底当然不是真的，可当船身轻轻一晃，我还是觉得，那片蓝离我并不远。海洋不必把所有秘密都说完，能让人愿意再看一眼，就已经够了。", "p": ["qù", "nián", "xià", "tiān", "", "wǒ", "zuò", "chuán", "qù", "kàn", "hǎi", "yáng", "", "cóng", "gǎng", "kǒu", "chū", "fā", "", "guò", "le", "jǐ", "shí", "gōng", "lǐ", "", "shuǐ", "miàn", "réng", "rán", "hěn", "kuān", "", "xiàng", "méi", "yǒu", "biān", "", "chuán", "cāng", "de", "chuāng", "xià", "", "shì", "yì", "céng", "shēn", "de", "kàn", "bú", "tòu", "de", "lán", "", "wǒ", "hū", "rán", "xiǎng", "qǐ", "xiǎo", "shí", "hòu", "de", "mèng", "", "zì", "jǐ", "zǒu", "dào", "hǎi", "de", "dǐ", "", "kàn", "jiàn", "yú", "xiàng", "dēng", "yí", "yàng", "pái", "liè", "zhe", "", "ān", "jìng", "dì", "yóu", "guò", "qù", "", "mèng", "lǐ", "de", "dǐ", "dāng", "rán", "bú", "shì", "zhēn", "de", "", "kě", "dāng", "chuán", "shēn", "qīng", "qīng", "yì", "huǎng", "", "wǒ", "hái", "shì", "jué", "de", "", "nà", "piàn", "lán", "lí", "wǒ", "bìng", "bù", "yuǎn", "", "hǎi", "yáng", "bú", "bì", "bǎ", "suǒ", "yǒu", "mì", "mì", "dōu", "shuō", "wán", "", "néng", "ràng", "rén", "yuàn", "yì", "zài", "kàn", "yì", "yǎn", "", "jiù", "yǐ", "jīng", "gòu", "le", ""], "vi": "Hè năm ngoái, tôi đi thuyền ra xem đại dương. Từ cảng xuất phát, đi đã vài chục kilomet, mặt nước vẫn rất rộng, như không bờ. Dưới ô cửa khoang là một lớp xanh sâu nhìn không xuyên. Tôi bỗng nhớ giấc mơ thuở nhỏ: tự mình đi xuống đáy biển, thấy cá xếp hàng như đèn, lặng lẽ bơi qua. Đáy trong mơ cố nhiên không phải thật, nhưng khi thân thuyền khẽ nghiêng, tôi vẫn thấy màu xanh ấy chẳng xa. Đại dương không cần nói hết mọi bí mật, khiến người ta muốn nhìn thêm một ánh, đã là đủ.", "en": "Last summer I took a boat to see the ocean. After leaving the harbour and travelling several dozen kilometres, the water was still very wide, as if it had no edge. Below the cabin window was a layer of blue too deep to see through. I suddenly remembered a childhood dream: I had walked to the bottom of the sea and seen the fish arranged like lamps, swimming quietly past. The bottom in the dream was not real, of course, but when the hull swayed slightly I still felt that that blue was not far from me. The ocean need not tell all its secrets; if it can make you want to look once more, that is already enough."}]}]}, {"l": 18, "texts": [{"n": 1, "zh": "对话：阿玲推荐一本很火的书", "vi": "Hội thoại: A Linh giới thiệu một cuốn sách đang rất hot", "en": "Dialogue: A Linh recommends a book that has become very popular", "kw": ["技术", "降落", "交通", "是否", "作者", "火"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你手上这本什么书？最近怎么这么火？", "p": ["nǐ", "shǒu", "shàng", "zhè", "běn", "shén", "me", "shū", "", "zuì", "jìn", "zěn", "me", "zhè", "me", "huǒ", ""], "vi": "Cuốn trên tay cậu là sách gì? Dạo này sao hot thế?", "en": "What's that book in your hand? Why has it become so popular lately?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "写机场和交通的。作者以前在机场工作，书里有一段讲飞机降落时的技术细节，很清楚。", "p": ["xiě", "jī", "chǎng", "hé", "jiāo", "tōng", "de", "", "zuò", "zhě", "yǐ", "qián", "zài", "jī", "chǎng", "gōng", "zuò", "", "shū", "lǐ", "yǒu", "yí", "duàn", "jiǎng", "fēi", "jī", "jiàng", "luò", "shí", "de", "jì", "shù", "xì", "jié", "", "hěn", "qīng", "chǔ", ""], "vi": "Viết về sân bay và giao thông. Tác giả trước làm ở sân bay, trong sách có một đoạn kể chi tiết kỹ thuật lúc máy bay hạ cánh, rất rõ.", "en": "It's about airports and transport. The author used to work at an airport, and there's a passage on the technical details of a plane landing that is very clear."}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "我是否也该看看？我对飞机不大懂。", "p": ["wǒ", "shì", "fǒu", "yě", "gāi", "kàn", "kàn", "", "wǒ", "duì", "fēi", "jī", "bú", "dà", "dǒng", ""], "vi": "Mình có nên xem không? Mình không rành máy bay lắm.", "en": "Should I have a look at it too? I don't know much about planes."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "值得看。不是只讲技术，也写了路上的人怎么等、怎么走。", "p": ["zhí", "de", "kàn", "", "bú", "shì", "zhǐ", "jiǎng", "jì", "shù", "", "yě", "xiě", "le", "lù", "shàng", "de", "rén", "zěn", "me", "děng", "", "zěn", "me", "zǒu", ""], "vi": "Đáng xem. Không chỉ nói kỹ thuật, còn viết người trên đường chờ thế nào, đi thế nào.", "en": "It's worth reading. It isn't only about the technology; it also describes how people wait and how they move on the road."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "看完借我。我想知道作者后来还写了什么。", "p": ["kàn", "wán", "jiè", "wǒ", "", "wǒ", "xiǎng", "zhī", "dào", "zuò", "zhě", "hòu", "lái", "hái", "xiě", "le", "shén", "me", ""], "vi": "Xem xong cho mình mượn. Mình muốn biết tác giả sau còn viết gì.", "en": "Lend it to me when you've finished. I'd like to know what else the author wrote later."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "好。我先做几个记号，再给你。", "p": ["hǎo", "", "wǒ", "xiān", "zuò", "jǐ", "gè", "jì", "hào", "", "zài", "gěi", "nǐ", ""], "vi": "Được. Mình đánh dấu vài chỗ đã, rồi đưa cậu.", "en": "All right. I'll mark a few places first, then give it to you."}]}, {"n": 2, "zh": "对话：密码太多，陈晓有点儿受不了", "vi": "Hội thoại: Mật khẩu quá nhiều, Trần Hiểu hơi chịu hết nổi", "en": "Dialogue: There are too many passwords, and Chen Xiao is finding it hard to bear", "kw": ["受不了", "安全", "密码", "日记", "允许", "秒"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "陈晓怎么对着手机叹气？", "p": ["chén", "xiǎo", "zěn", "me", "duì", "zhuó", "shǒu", "jī", "tàn", "qì", ""], "vi": "Trần Hiểu sao cứ thở dài vào điện thoại?", "en": "Why is Chen Xiao sighing at his phone?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "他又忘了邮箱密码。为了安全，每个网站都不一样，他简直受不了。", "p": ["tā", "yòu", "wàng", "le", "yóu", "xiāng", "mì", "mǎ", "", "wèi", "le", "ān", "quán", "", "měi", "gè", "wǎng", "zhàn", "dōu", "bù", "yí", "yàng", "", "tā", "jiǎn", "zhí", "shòu", "bu", "liǎo", ""], "vi": "Cậu ấy lại quên mật khẩu thư. Vì an toàn, trang nào cũng khác, cậu ấy thật sự chịu hết nổi.", "en": "He's forgotten his email password again. For safety, each site is different, and he can hardly bear it."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "那他日记里也不许写吗？", "p": ["nà", "tā", "rì", "jì", "lǐ", "yě", "bù", "xǔ", "xiě", "ma", ""], "vi": "Vậy trong nhật ký cũng không được ghi à?", "en": "Isn't he allowed to write them in his diary?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "老师说日记可以记事情，可不要写密码。也不允许把密码发给不认识的人。", "p": ["lǎo", "shī", "shuō", "rì", "jì", "kě", "yǐ", "jì", "shì", "qíng", "", "kě", "bú", "yào", "xiě", "mì", "mǎ", "", "yě", "bù", "yǔn", "xǔ", "bǎ", "mì", "mǎ", "fā", "gěi", "bú", "rèn", "shí", "de", "rén", ""], "vi": "Cô giáo bảo nhật ký ghi việc được, nhưng đừng viết mật khẩu. Cũng không cho phép gửi mật khẩu cho người lạ.", "en": "The teacher said a diary can be used for events, but you shouldn't write passwords in it. You also aren't allowed to send a password to anyone you don't know."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "那就设一个自己看得懂、别人看不懂的提示，几秒就能想起来。", "p": ["nà", "jiù", "shè", "yí", "gè", "zì", "jǐ", "kàn", "de", "dǒng", "", "bié", "rén", "kàn", "bù", "dǒng", "de", "tí", "shì", "", "jǐ", "miǎo", "jiù", "néng", "xiǎng", "qǐ", "lái", ""], "vi": "Vậy đặt một gợi ý mình hiểu, người khác không hiểu, vài giây là nhớ ra.", "en": "Then he should set a hint that he understands and other people don't, so he can remember it in a few seconds."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "我回头跟他说。先把最常用的那个改好。", "p": ["wǒ", "huí", "tóu", "gēn", "tā", "shuō", "", "xiān", "bǎ", "zuì", "cháng", "yòng", "de", "nà", "ge", "gǎi", "hǎo", ""], "vi": "Lát mình nói với cậu ấy. Đổi cái dùng nhiều nhất trước đã.", "en": "I'll tell him later. First he should get the one he uses most in order."}]}, {"n": 3, "zh": "对话：小雪做了一个奇怪的梦", "vi": "Hội thoại: Tiểu Tuyết nằm một giấc mơ kỳ lạ", "en": "Dialogue: Xiaoxue has had a strange dream", "kw": ["矿泉水", "接着", "警察", "危险", "桥", "咸", "座"], "lines": [{"s": "阿玲", "sp": ["ā", "líng"], "t": "你怎么一早就皱眉？", "p": ["nǐ", "zěn", "me", "yì", "zǎo", "jiù", "zhòu", "méi", ""], "vi": "Sao sáng sớm cậu đã nhíu mày?", "en": "Why are you frowning so early in the morning?"}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "昨晚做了个梦。我走在一座又长又窄的桥上，下面的水看起来有点儿危险。", "p": ["zuó", "wǎn", "zuò", "le", "gè", "mèng", "", "wǒ", "zǒu", "zài", "yí", "zuò", "yòu", "zhǎng", "yòu", "zhǎi", "de", "qiáo", "shàng", "", "xià", "miàn", "de", "shuǐ", "kàn", "qǐ", "lái", "yǒu", "diǎn", "r", "wēi", "xiǎn", ""], "vi": "Tối qua nằm mơ. Mình đi trên một cây cầu vừa dài vừa hẹp, nước bên dưới trông hơi nguy hiểm.", "en": "I had a dream last night. I was walking on a long, narrow bridge, and the water below looked a little dangerous."}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "接着呢？", "p": ["jiē", "zhe", "ne", ""], "vi": "Rồi sao nữa?", "en": "And then?"}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "接着桥中间站着一位警察，递给我一瓶矿泉水。我喝了一口，竟然是咸的。", "p": ["jiē", "zhe", "qiáo", "zhōng", "jiān", "zhàn", "zhe", "yí", "wèi", "jǐng", "chá", "", "dì", "gěi", "wǒ", "yì", "píng", "kuàng", "quán", "shuǐ", "", "wǒ", "hē", "le", "yì", "kǒu", "", "jìng", "rán", "shì", "xián", "de", ""], "vi": "Rồi giữa cầu đứng một cảnh sát, đưa cho mình một chai nước khoáng. Mình uống một ngụm, hóa ra lại mặn.", "en": "Then a police officer was standing in the middle of the bridge and handed me a bottle of mineral water. I took a sip, and it was salty, unexpectedly."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "咸的矿泉水？这梦倒有意思。", "p": ["xián", "de", "kuàng", "quán", "shuǐ", "", "zhè", "mèng", "dào", "yǒu", "yì", "si", ""], "vi": "Nước khoáng mặn? Giấc mơ này ngược lại thú vị.", "en": "Salty mineral water? That's an interesting dream, actually."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "醒来我还去倒了一杯真的水。还好，是淡的。", "p": ["xǐng", "lái", "wǒ", "hái", "qù", "dào", "le", "yì", "bēi", "zhēn", "de", "shuǐ", "", "hái", "hǎo", "", "shì", "dàn", "de", ""], "vi": "Tỉnh dậy mình còn rót một ly nước thật. May mà nhạt.", "en": "When I woke up I even poured myself a glass of real water. Luckily, it was plain."}]}, {"n": 4, "zh": "短文：迷路的时候把手机举起来", "vi": "Đoạn văn: Lúc lạc đường hãy giơ điện thoại lên", "en": "Passage: When you are lost, hold your phone up", "kw": ["地点", "地址", "付款", "迷路", "举"], "lines": [{"s": "", "sp": [], "t": "第一次到这座城，我在车站迷了路。身边没有熟悉的地点，路牌上的地址我也读得慢。后来我举起手机，把地图打开，跟着箭头走，终于找到那家小店。付款的时候，老板笑着说：“外地人第一次来，多半会转两圈。”我并不觉得丢脸。会迷路并不可怕，可怕的是不敢问、也不肯把地图举起来看一眼。城市很大，可只要你肯停下来找，路总会出现。", "p": ["dì", "yī", "cì", "dào", "zhè", "zuò", "chéng", "", "wǒ", "zài", "chē", "zhàn", "mí", "le", "lù", "", "shēn", "biān", "méi", "yǒu", "shú", "xī", "de", "dì", "diǎn", "", "lù", "pái", "shàng", "de", "dì", "zhǐ", "wǒ", "yě", "dú", "de", "màn", "", "hòu", "lái", "wǒ", "jǔ", "qǐ", "shǒu", "jī", "", "bǎ", "dì", "tú", "dǎ", "kāi", "", "gēn", "zhe", "jiàn", "tóu", "zǒu", "", "zhōng", "yú", "zhǎo", "dào", "nà", "jiā", "xiǎo", "diàn", "", "fù", "kuǎn", "de", "shí", "hòu", "", "lǎo", "bǎn", "xiào", "zhe", "shuō", "", "", "wài", "dì", "rén", "dì", "yī", "cì", "lái", "", "duō", "bàn", "huì", "zhuǎn", "liǎng", "quān", "", "", "wǒ", "bìng", "bù", "jué", "de", "diū", "liǎn", "", "huì", "mí", "lù", "bìng", "bù", "kě", "pà", "", "kě", "pà", "de", "shì", "bù", "gǎn", "wèn", "", "yě", "bù", "kěn", "bǎ", "dì", "tú", "jǔ", "qǐ", "lái", "kàn", "yì", "yǎn", "", "chéng", "shì", "hěn", "dà", "", "kě", "zhǐ", "yào", "nǐ", "kěn", "tíng", "xià", "lái", "zhǎo", "", "lù", "zǒng", "huì", "chū", "xiàn", ""], "vi": "Lần đầu đến thành phố này, tôi lạc ở bến xe. Quanh mình không có địa điểm quen, địa chỉ trên biển cũng đọc chậm. Sau tôi giơ điện thoại, mở bản đồ, theo mũi tên, cuối cùng tìm ra tiệm nhỏ ấy. Lúc thanh toán, ông chủ cười: «Người tỉnh khác lần đầu đến, phần nhiều đi vòng hai vòng.» Tôi không thấy xấu hổ. Lạc đường không đáng sợ, đáng sợ là không dám hỏi, cũng không chịu giơ bản đồ lên nhìn một cái. Thành phố rất lớn, nhưng chỉ cần chịu dừng lại tìm, đường rồi sẽ hiện.", "en": "The first time I came to this city, I got lost at the station. There was no familiar place around me, and I was also slow to read the addresses on the signs. Later I held up my phone, opened the map, followed the arrow, and finally found that little shop. When I was paying, the owner smiled and said, \"People from out of town usually walk in a circle or two the first time.\" I did not feel ashamed. Getting lost is not frightening; what is frightening is not daring to ask, and not being willing to hold the map up and look. The city is large, but if you are willing to stop and look, the road will appear."}]}, {"n": 5, "zh": "短文：一封还在路上的信", "vi": "Đoạn văn: Một bức thư vẫn còn trên đường", "en": "Passage: A letter that is still on its way", "kw": ["世纪", "网站", "信封", "信息", "邮局", "收"], "lines": [{"s": "", "sp": [], "t": "这个世纪，信息走得很快。一条消息在网站上几秒就能看到，可我外婆仍然喜欢去邮局。她把信纸放进信封，写上我的名字，再问工作人员：“大概几天能收到？”我有时会觉得慢。可当那封信真的被我收到，摸着信封上她写歪的字，我会在桌边坐很久。快的信息告诉我世界在发生什么；慢的信，告诉我有人愿意为一个名字停下来。两种收法，我都想留着。", "p": ["zhè", "ge", "shì", "jì", "", "xìn", "xī", "zǒu", "de", "hěn", "kuài", "", "yì", "tiáo", "xiāo", "xi", "zài", "wǎng", "zhàn", "shàng", "jǐ", "miǎo", "jiù", "néng", "kàn", "dào", "", "kě", "wǒ", "wài", "pó", "réng", "rán", "xǐ", "huān", "qù", "yóu", "jú", "", "tā", "bǎ", "xìn", "zhǐ", "fàng", "jìn", "xìn", "fēng", "", "xiě", "shàng", "wǒ", "de", "míng", "zì", "", "zài", "wèn", "gōng", "zuò", "rén", "yuán", "", "", "dà", "gài", "jǐ", "tiān", "néng", "shōu", "dào", "", "", "wǒ", "yǒu", "shí", "huì", "jué", "de", "màn", "", "kě", "dāng", "nà", "fēng", "xìn", "zhēn", "de", "bèi", "wǒ", "shōu", "dào", "", "mō", "zhe", "xìn", "fēng", "shàng", "tā", "xiě", "wāi", "de", "zì", "", "wǒ", "huì", "zài", "zhuō", "biān", "zuò", "hěn", "jiǔ", "", "kuài", "de", "xìn", "xī", "gào", "sù", "wǒ", "shì", "jiè", "zài", "fā", "shēng", "shén", "me", "", "màn", "de", "xìn", "", "gào", "sù", "wǒ", "yǒu", "rén", "yuàn", "yì", "wèi", "yí", "gè", "míng", "zì", "tíng", "xià", "lái", "", "liǎng", "zhǒng", "shōu", "fǎ", "", "wǒ", "dōu", "xiǎng", "liú", "zhe", ""], "vi": "Thế kỷ này, thông tin đi rất nhanh. Một tin trên trang mạng vài giây đã thấy, nhưng bà ngoại tôi vẫn thích đến bưu điện. Bà bỏ giấy vào phong bì, viết tên tôi, rồi hỏi nhân viên: «Khoảng mấy ngày thì nhận được?» Đôi lúc tôi thấy chậm. Nhưng khi bức thư ấy thật sự được tôi nhận, sờ chữ bà viết lệch trên phong bì, tôi ngồi mãi bên bàn. Tin nhanh cho tôi biết thế giới đang xảy ra gì; thư chậm cho tôi biết có người chịu dừng lại vì một cái tên. Hai cách nhận, tôi đều muốn giữ.", "en": "In this century, information travels very quickly. A piece of news can be seen on a website in a few seconds, yet my grandmother still likes to go to the post office. She puts the letter paper into an envelope, writes my name on it, then asks the staff, \"About how many days before it's received?\" Sometimes I feel it is slow. But when that letter is really received by me, and I touch the crooked characters she wrote on the envelope, I sit at the desk for a long time. Fast information tells me what is happening in the world; a slow letter tells me that someone was willing to stop for a name. I want to keep both ways of receiving things."}]}]}, {"l": 19, "texts": [{"n": 1, "zh": "对话：林安补交学期申请", "vi": "Hội thoại: Lâm An nộp bổ sung đơn học kỳ", "en": "Dialogue: Lin An hands in a term application again", "kw": ["出生", "打印", "道歉", "复印", "性别", "学期"], "lines": [{"s": "阿玲", "sp": ["ā", "líng"], "t": "林安，你又去办公室了？", "p": ["lín", "ān", "", "nǐ", "yòu", "qù", "bàn", "gōng", "shì", "le", ""], "vi": "Lâm An, cậu lại ra văn phòng à?", "en": "Lin An, have you been to the office again?"}, {"s": "林安", "sp": ["lín", "ān"], "t": "下个学期的申请表，出生日期和性别我写反了，得重新打印一份。", "p": ["xià", "gè", "xué", "qī", "de", "shēn", "qǐng", "biǎo", "", "chū", "shēng", "rì", "qī", "hé", "xìng", "bié", "wǒ", "xiě", "fǎn", "le", "", "de", "chóng", "xīn", "dǎ", "yìn", "yí", "fèn", ""], "vi": "Đơn xin học kỳ sau, ngày sinh và giới tính mình viết ngược, phải in lại một bản.", "en": "On next term's application form I wrote the date of birth and the gender the wrong way round, so I have to print a new one."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "原件呢？要不要先复印一份留着？", "p": ["yuán", "jiàn", "ne", "", "yào", "bú", "yào", "xiān", "fù", "yìn", "yí", "fèn", "liú", "zhe", ""], "vi": "Bản gốc thì sao? Có cần photocopy một bản giữ lại không?", "en": "What about the original? Do you want to photocopy one to keep first?"}, {"s": "林安", "sp": ["lín", "ān"], "t": "复印好了。我还向老师道歉了，她说改清楚再交就行。", "p": ["fù", "yìn", "hǎo", "le", "", "wǒ", "hái", "xiàng", "lǎo", "shī", "dào", "qiàn", "le", "", "tā", "shuō", "gǎi", "qīng", "chǔ", "zài", "jiāo", "jiù", "xíng", ""], "vi": "Photocopy rồi. Mình còn xin lỗi cô, cô bảo sửa rõ rồi nộp là được.", "en": "I've already made a copy. I also apologised to the teacher, and she said I could just hand it in once it was corrected clearly."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "那就好。表格上的字，还是要再看一遍。", "p": ["nà", "jiù", "hǎo", "", "biǎo", "gé", "shàng", "de", "zì", "", "hái", "shì", "yào", "zài", "kàn", "yí", "biàn", ""], "vi": "Thế thì tốt. Chữ trên đơn vẫn nên xem lại một lượt.", "en": "That's good. The words on a form still need to be looked at once more."}, {"s": "林安", "sp": ["lín", "ān"], "t": "我这回对着学生证，一项一项对。", "p": ["wǒ", "zhè", "huí", "duì", "zhe", "xué", "shēng", "zhèng", "", "yí", "xiàng", "yí", "xiàng", "duì", ""], "vi": "Lần này mình đối với thẻ sinh viên, từng mục một.", "en": "This time I'll check it item by item against my student card."}]}, {"n": 2, "zh": "对话：包饺子时刀把皮划破了", "vi": "Hội thoại: Lúc gói sủi cảo, dao rách da", "en": "Dialogue: While making dumplings, the knife nicks a finger", "kw": ["包子", "饺子", "理发", "零钱", "刀", "破", "脱"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你手怎么包着？是切菜了吗？", "p": ["nǐ", "shǒu", "zěn", "me", "bāo", "zhe", "", "shì", "qiè", "cài", "le", "ma", ""], "vi": "Tay cậu băng sao? Thái rau à?", "en": "Why is your hand wrapped up? Were you cutting vegetables?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "包饺子的时候，刀把指头划破了一点。我赶紧脱了围裙去洗。", "p": ["bāo", "jiǎo", "zi", "de", "shí", "hòu", "", "dāo", "bà", "zhǐ", "tou", "huà", "pò", "le", "yì", "diǎn", "", "wǒ", "gǎn", "jǐn", "tuō", "le", "wéi", "qún", "qù", "xǐ", ""], "vi": "Lúc gói sủi cảo, dao rách đầu ngón một chút. Mình vội cởi tạp dề đi rửa.", "en": "While I was making dumplings, the knife nicked my finger a little. I quickly took off my apron and went to wash it."}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "严重吗？要不要去药店？我还有一些零钱。", "p": ["yán", "zhòng", "ma", "", "yào", "bú", "yào", "qù", "yào", "diàn", "", "wǒ", "hái", "yǒu", "yì", "xiē", "líng", "qián", ""], "vi": "Có nặng không? Có cần ra hiệu thuốc không? Mình còn ít tiền lẻ.", "en": "Is it serious? Should we go to the pharmacy? I've still got some small change."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "不严重，已经贴好了。饺子还是包完了，另外还蒸了几笼包子。", "p": ["bù", "yán", "zhòng", "", "yǐ", "jīng", "tiē", "hǎo", "le", "", "jiǎo", "zi", "hái", "shì", "bāo", "wán", "le", "", "lìng", "wài", "hái", "zhēng", "le", "jǐ", "lóng", "bāo", "zi", ""], "vi": "Không nặng, dán xong rồi. Sủi cảo vẫn gói xong, ngoài ra còn hấp thêm vài lồng bánh bao.", "en": "It's not serious; it's already been dressed. We still finished the dumplings, and we also steamed a few baskets of baozi."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你不是说下午要去理发吗？手还方便吗？", "p": ["nǐ", "bú", "shì", "shuō", "xià", "wǔ", "yào", "qù", "lǐ", "fà", "ma", "", "shǒu", "hái", "fāng", "biàn", "ma", ""], "vi": "Chẳng phải cậu bảo chiều đi cắt tóc sao? Tay còn thuận không?", "en": "Didn't you say you were going to have a haircut this afternoon? Is your hand still all right for that?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "方便。破得不深，过两天就好。", "p": ["fāng", "biàn", "", "pò", "de", "bù", "shēn", "", "guò", "liǎng", "tiān", "jiù", "hǎo", ""], "vi": "Thuận. Rách không sâu, hai hôm nữa là ổn.", "en": "It's fine. The cut isn't deep; it'll be all right in a couple of days."}]}, {"n": 3, "zh": "对话：国际交流课上练习转身", "vi": "Hội thoại: Giờ giao lưu quốc tế tập xoay người", "en": "Dialogue: Practising a turn in the international exchange class", "kw": ["打招呼", "胳膊", "国籍", "眼镜", "戴", "抬", "转"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你们交流课今天练什么了？", "p": ["nǐ", "men", "jiāo", "liú", "kè", "jīn", "tiān", "liàn", "shén", "me", "le", ""], "vi": "Giờ giao lưu hôm nay các cậu tập gì?", "en": "What did you practise in the exchange class today?"}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "一个转身的动作。老师让我们先打招呼，再慢慢抬起胳膊，转到另一边。", "p": ["yī", "gè", "zhuǎn", "shēn", "de", "dòng", "zuò", "", "lǎo", "shī", "ràng", "wǒ", "men", "xiān", "dǎ", "zhāo", "hu", "", "zài", "màn", "màn", "tái", "qǐ", "gē", "bo", "", "zhuǎn", "dào", "lìng", "yì", "biān", ""], "vi": "Một động tác xoay người. Cô bảo mình chào hỏi trước, rồi từ từ giơ cánh tay, xoay sang bên kia.", "en": "A turning movement. The teacher had us greet each other first, then slowly raise our arms and turn to the other side."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "你戴着眼镜，转的时候掉不掉？", "p": ["nǐ", "dài", "zhuó", "yǎn", "jìng", "", "zhuǎn", "de", "shí", "hòu", "diào", "bú", "diào", ""], "vi": "Cậu đeo kính, lúc xoay có rơi không?", "en": "You wear glasses — do they fall off when you turn?"}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "我用手扶了一下，没掉。班里有好几个不同国籍的同学，大家一起练，倒不怕错。", "p": ["wǒ", "yòng", "shǒu", "fú", "le", "yí", "xià", "", "méi", "diào", "", "bān", "lǐ", "yǒu", "hǎo", "jǐ", "gè", "bù", "tóng", "guó", "jí", "de", "tóng", "xué", "", "dà", "jiā", "yì", "qǐ", "liàn", "", "dào", "bú", "pà", "cuò", ""], "vi": "Mình lấy tay giữ một cái, không rơi. Trong lớp có mấy bạn khác quốc tịch, cùng tập, ngược lại không sợ sai.", "en": "I held them with my hand, and they didn't fall. There are several classmates of different nationalities in the class, and practising together we weren't actually afraid of getting it wrong."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "下次我可以去看吗？", "p": ["xià", "cì", "wǒ", "kě", "yǐ", "qù", "kàn", "ma", ""], "vi": "Lần sau mình đến xem được không?", "en": "May I come and watch next time?"}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "可以。你来了，记得先跟老师打个招呼。", "p": ["kě", "yǐ", "", "nǐ", "lái", "le", "", "jì", "děi", "xiān", "gēn", "lǎo", "shī", "dǎ", "gè", "zhāo", "hū", ""], "vi": "Được. Cậu đến thì nhớ chào cô một tiếng trước.", "en": "Yes. When you come, remember to say hello to the teacher first."}]}, {"n": 4, "zh": "短文：电话占线的那天下午", "vi": "Đoạn văn: Buổi chiều điện thoại bị chiếm mạch", "en": "Passage: The afternoon the line was busy", "kw": ["厨房", "房东", "占线", "租"], "lines": [{"s": "", "sp": [], "t": "我想换一套带厨房的房子，照片看起来还不错。按广告上的号码打给房东，却一直占线。下午我又打了三次，有一次接通了，对方说自己不是房东，只是帮着看房子。我把租房要问的事情写在纸上，准备再打。后来我明白，急着租并不等于要立刻答应。厨房朝哪、房租包不包网，这些都得问清楚。占线不可怕，可怕的是问都没问完就点头。", "p": ["wǒ", "xiǎng", "huàn", "yí", "tào", "dài", "chú", "fáng", "de", "fáng", "zi", "", "zhào", "piān", "kàn", "qǐ", "lái", "hái", "bú", "cuò", "", "àn", "guǎng", "gào", "shàng", "de", "hào", "mǎ", "dǎ", "gěi", "fáng", "dōng", "", "què", "yì", "zhí", "zhàn", "xiàn", "", "xià", "wǔ", "wǒ", "yòu", "dǎ", "le", "sān", "cì", "", "yǒu", "yí", "cì", "jiē", "tōng", "le", "", "duì", "fāng", "shuō", "zì", "jǐ", "bú", "shì", "fáng", "dōng", "", "zhǐ", "shì", "bāng", "zhe", "kàn", "fáng", "zi", "", "wǒ", "bǎ", "zū", "fáng", "yào", "wèn", "de", "shì", "qíng", "xiě", "zài", "zhǐ", "shàng", "", "zhǔn", "bèi", "zài", "dǎ", "", "hòu", "lái", "wǒ", "míng", "bái", "", "jí", "zhe", "zū", "bìng", "bù", "děng", "yú", "yào", "lì", "kè", "dā", "yìng", "", "chú", "fáng", "cháo", "nǎ", "", "fáng", "zū", "bāo", "bù", "bāo", "wǎng", "", "zhè", "xiē", "dōu", "de", "wèn", "qīng", "chǔ", "", "zhàn", "xiàn", "bù", "kě", "pà", "", "kě", "pà", "de", "shì", "wèn", "dōu", "méi", "wèn", "wán", "jiù", "diǎn", "tóu", ""], "vi": "Tôi muốn đổi một căn có bếp, ảnh trông cũng ổn. Gọi số trên quảng cáo cho chủ nhà, mãi bị bận tuyến. Chiều tôi gọi thêm ba lần, có lần bắt được, bên kia bảo mình không phải chủ, chỉ xem nhà hộ. Tôi viết những điều cần hỏi khi thuê lên giấy, định gọi nữa. Sau tôi hiểu, sốt ruột thuê không có nghĩa phải đồng ý ngay. Bếp hướng nào, tiền nhà có gồm mạng không, đều phải hỏi rõ. Máy bận không đáng sợ, đáng sợ là hỏi chưa xong đã gật.", "en": "I wanted to change to a flat with a kitchen; the photos looked all right. I rang the landlord on the number in the advertisement, but the line was busy the whole time. That afternoon I called three more times. Once I got through, and the person said they were not the landlord, only helping to show the place. I wrote down on paper the things I needed to ask about the rental, and got ready to call again. Later I understood that being in a hurry to rent does not mean you have to say yes at once. Which way the kitchen faces, and whether the rent includes the internet, all have to be asked clearly. A busy line is not frightening; what is frightening is nodding before you have finished asking."}]}, {"n": 5, "zh": "短文：球场边那条不能踩的线", "vi": "Đoạn văn: Đường kẻ bên sân không được giẫm", "en": "Passage: The line by the court that you must not step on", "kw": ["乒乓球", "羽毛球", "功夫", "禁止", "座位", "场"], "lines": [{"s": "", "sp": [], "t": "学校新开了一场活动：一边是乒乓球，一边是羽毛球。场地不大，座位也不多，可规矩写得很清楚：禁止把饮料带进场，也禁止走进画好的白线。有个同学练过几年功夫，脚很稳，仍小心翼翼地绕着线走。我看着那两条白线，忽然觉得它们不只是给球用的。把该停的地方停住，大家才都有地方跑、有地方坐。一场小小的比赛，也能把人教得更有分寸。", "p": ["xué", "xiào", "xīn", "kāi", "le", "yì", "cháng", "huó", "dòng", "", "yì", "biān", "shì", "pīng", "pāng", "qiú", "", "yì", "biān", "shì", "yǔ", "máo", "qiú", "", "chǎng", "dì", "bú", "dà", "", "zuò", "wèi", "yě", "bù", "duō", "", "kě", "guī", "jǔ", "xiě", "de", "hěn", "qīng", "chǔ", "", "jìn", "zhǐ", "bǎ", "yǐn", "liào", "dài", "jìn", "chǎng", "", "yě", "jìn", "zhǐ", "zǒu", "jìn", "huà", "hǎo", "de", "bái", "xiàn", "", "yǒu", "gè", "tóng", "xué", "liàn", "guò", "jǐ", "nián", "gōng", "fu", "", "jiǎo", "hěn", "wěn", "", "réng", "xiǎo", "xīn", "yì", "yì", "dì", "rào", "zhe", "xiàn", "zǒu", "", "wǒ", "kàn", "zhe", "nà", "liǎng", "tiáo", "bái", "xiàn", "", "hū", "rán", "jué", "de", "tā", "men", "bù", "zhǐ", "shì", "gěi", "qiú", "yòng", "de", "", "bǎ", "gāi", "tíng", "de", "dì", "fāng", "tíng", "zhù", "", "dà", "jiā", "cái", "dōu", "yǒu", "dì", "fāng", "pǎo", "", "yǒu", "dì", "fāng", "zuò", "", "yì", "cháng", "xiǎo", "xiǎo", "de", "bǐ", "sài", "", "yě", "néng", "bǎ", "rén", "jiào", "de", "gèng", "yǒu", "fēn", "cùn", ""], "vi": "Trường mới mở một hoạt động: một bên bóng bàn, một bên cầu lông. Sân không lớn, chỗ ngồi cũng không nhiều, nhưng quy củ viết rất rõ: cấm mang đồ uống vào sân, cũng cấm bước vào đường trắng đã kẻ. Có bạn từng luyện vài năm võ, chân rất vững, vẫn dè dặt đi vòng quanh đường kẻ. Tôi nhìn hai đường trắng ấy, bỗng thấy chúng không chỉ để cho bóng. Chỗ phải dừng thì dừng, mọi người mới có chỗ chạy, có chỗ ngồi. Một trận nhỏ cũng dạy người ta chừng mực hơn.", "en": "The school has started a new activity: table tennis on one side, badminton on the other. The court is not large, and there are not many seats either, but the rules are written very clearly: it is forbidden to bring drinks onto the court, and also forbidden to step inside the painted white lines. One classmate who has practised kung fu for a few years, and whose footing is very steady, still walked carefully around the line. Looking at those two white lines, I suddenly felt they were not only there for the ball. Only if you stop where you ought to stop does everyone have room to run and room to sit. Even a small match can teach people to have a better sense of limits."}]}]}, {"l": 20, "texts": [{"n": 1, "zh": "对话：送周南去机场，航班却推迟了", "vi": "Hội thoại: Tiễn Châu Nam ra sân bay, chuyến bay lại hoãn", "en": "Dialogue: Seeing Zhou Nan off at the airport, but the flight is delayed", "kw": ["高速公路", "登机牌", "加油站", "航班", "首都", "推迟"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "周南不是今天去首都吗？你们怎么还在路上？", "p": ["zhōu", "nán", "bú", "shì", "jīn", "tiān", "qù", "shǒu", "dū", "ma", "", "nǐ", "men", "zěn", "me", "hái", "zài", "lù", "shàng", ""], "vi": "Châu Nam chẳng phải hôm nay vào thủ đô sao? Sao các cậu vẫn còn trên đường?", "en": "Isn't Zhou Nan going to the capital today? Why are you still on the road?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "高速公路有点堵。刚在加油站停了一下，手机上就显示：航班推迟了一个小时。", "p": ["gāo", "sù", "gōng", "lù", "yǒu", "diǎn", "dǔ", "", "gāng", "zài", "jiā", "yóu", "zhàn", "tíng", "le", "yí", "xià", "", "shǒu", "jī", "shàng", "jiù", "xiǎn", "shì", "", "háng", "bān", "tuī", "chí", "le", "yí", "gè", "xiǎo", "shí", ""], "vi": "Cao tốc hơi tắc. Vừa dừng ở trạm xăng một chút, điện thoại đã hiện: chuyến bay hoãn một tiếng.", "en": "The expressway was a bit jammed. We had just stopped at a petrol station for a moment when the phone showed that the flight had been delayed by an hour."}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "还好登机牌已经打出来了。推迟就推迟，安全到了最重要。", "p": ["hái", "hǎo", "dēng", "jī", "pái", "yǐ", "jīng", "dǎ", "chū", "lái", "le", "", "tuī", "chí", "jiù", "tuī", "chí", "", "ān", "quán", "dào", "le", "zuì", "zhòng", "yào", ""], "vi": "May mà thẻ lên máy bay đã in xong. Hoãn thì hoãn, đến nơi an toàn là quan trọng nhất.", "en": "Luckily the boarding pass has already been printed. If it's delayed, it's delayed; arriving safely is what matters most."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "那你们在机场多等一下，别着急。", "p": ["nà", "nǐ", "men", "zài", "jī", "chǎng", "duō", "děng", "yí", "xià", "", "bié", "zháo", "jí", ""], "vi": "Vậy các cậu ở sân bay đợi thêm một lúc, đừng sốt.", "en": "Then wait a bit longer at the airport, and don't worry."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "我们正好用这段时间再检查一遍行李。", "p": ["wǒ", "men", "zhèng", "hǎo", "yòng", "zhè", "duàn", "shí", "jiān", "zài", "jiǎn", "chá", "yí", "biàn", "xíng", "li", ""], "vi": "Mình đúng lúc dùng khoảng thời gian này kiểm tra hành lý thêm một lượt.", "en": "We can use this time to check the luggage through once more."}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "到了首都我给你们发消息。", "p": ["dào", "le", "shǒu", "dū", "wǒ", "gěi", "nǐ", "men", "fā", "xiāo", "xi", ""], "vi": "Đến thủ đô mình nhắn tin cho các cậu.", "en": "I'll message you when I get to the capital."}]}, {"n": 2, "zh": "对话：祝贺一次合格的小旅行", "vi": "Hội thoại: Chúc mừng một chuyến đi nhỏ đạt yêu cầu", "en": "Dialogue: Congratulations on a small trip that went well", "kw": ["对面", "合格", "烤鸭", "可怜", "旅行", "祝贺"], "lines": [{"s": "阿玲", "sp": ["ā", "líng"], "t": "对面那家店的烤鸭，是不是就是你们旅行时吃过的？", "p": ["duì", "miàn", "nà", "jiā", "diàn", "de", "kǎo", "yā", "", "shì", "bú", "shì", "jiù", "shì", "nǐ", "men", "lǚ", "xíng", "shí", "chī", "guò", "de", ""], "vi": "Tiệm đối diện kia, vịt quay có phải các cậu đã ăn khi đi du lịch không?", "en": "Is the roast duck at the shop opposite the one you had on your trip?"}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "对。那次旅行虽然短，可行程安排得很合格，谁都没有掉队。", "p": ["duì", "", "nà", "cì", "lǚ", "xíng", "suī", "rán", "duǎn", "", "kě", "xíng", "chéng", "ān", "pái", "de", "hěn", "hé", "gé", "", "shéi", "dōu", "méi", "yǒu", "diào", "duì", ""], "vi": "Đúng. Chuyến đi ấy tuy ngắn, nhưng lịch trình sắp rất đạt, chẳng ai bị tụt lại.", "en": "That's the one. The trip was short, but the itinerary was arranged in a way that really measured up, and nobody was left behind."}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "回来的时候，陈晓还买了一只小鸭子给妹妹。她说旅馆的鸭子太可怜，想带一个回家。", "p": ["huí", "lái", "de", "shí", "hòu", "", "chén", "xiǎo", "hái", "mǎi", "le", "yì", "zhī", "xiǎo", "yā", "zi", "gěi", "mèi", "mèi", "", "tā", "shuō", "lǚ", "guǎn", "de", "yā", "zi", "tài", "kě", "lián", "", "xiǎng", "dài", "yí", "gè", "huí", "jiā", ""], "vi": "Lúc về, Trần Hiểu còn mua một con vịt nhỏ cho em gái. Bé bảo vịt trong khách sạn thương quá, muốn mang một con về.", "en": "When we came back, Chen Xiao even bought a little duck for his sister. She had said the ducks at the hotel looked so poor, and she wanted to take one home."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "那得祝贺你们，第一次自己安排就这么顺利。", "p": ["nà", "de", "zhù", "hè", "nǐ", "men", "", "dì", "yī", "cì", "zì", "jǐ", "ān", "pái", "jiù", "zhè", "me", "shùn", "lì", ""], "vi": "Vậy phải chúc mừng các cậu, lần đầu tự sắp mà thuận đến thế.", "en": "Then I must congratulate you: the first time you arranged it yourselves, and it went so smoothly."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "晚上我们就着烤鸭，再把照片翻一遍。", "p": ["wǎn", "shàng", "wǒ", "men", "jiù", "zhe", "kǎo", "yā", "", "zài", "bǎ", "zhào", "piān", "fān", "yí", "biàn", ""], "vi": "Tối mình vừa ăn vịt quay vừa lật ảnh lại một lượt.", "en": "This evening we'll go through the photos again over the roast duck."}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "下次旅行，还想再去那家对面的小店坐坐。", "p": ["xià", "cì", "lǚ", "xíng", "", "hái", "xiǎng", "zài", "qù", "nà", "jiā", "duì", "miàn", "de", "xiǎo", "diàn", "zuò", "zuò", ""], "vi": "Lần sau đi du lịch, vẫn muốn ghé ngồi tiệm đối diện ấy nữa.", "en": "On the next trip, I'd still like to sit in that little shop opposite again."}]}, {"n": 3, "zh": "对话：钥匙存前台的那晚", "vi": "Hội thoại: Đêm để chìa khóa ở quầy lễ tân", "en": "Dialogue: The night the key was left at the front desk", "kw": ["打扮", "干杯", "究竟", "民族", "笑话", "钥匙", "存"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你们去那个民族村，究竟好玩吗？", "p": ["nǐ", "men", "qù", "nà", "ge", "mín", "zú", "cūn", "", "jiū", "jìng", "hǎo", "wán", "ma", ""], "vi": "Các cậu đến thôn dân tộc ấy, rốt cuộc có vui không?", "en": "When you went to that ethnic village, was it actually fun?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "好玩。晚上大家稍微打扮了一下，还坐在一起干杯。有人讲了几个笑话，把我笑得差点把茶洒了。", "p": ["hǎo", "wán", "", "wǎn", "shàng", "dà", "jiā", "shāo", "wēi", "dǎ", "ban", "le", "yí", "xià", "", "hái", "zuò", "zài", "yì", "qǐ", "gān", "bēi", "", "yǒu", "rén", "jiǎng", "le", "jǐ", "gè", "xiào", "hua", "", "bǎ", "wǒ", "xiào", "de", "chà", "diǎn", "bǎ", "chá", "sǎ", "le", ""], "vi": "Vui. Tối mọi người sửa soạn một chút, còn ngồi cùng cụng ly. Có người kể vài chuyện cười, mình cười suýt đổ trà.", "en": "It was. In the evening everyone dressed up a little, and we also sat together and toasted. Someone told a few jokes, and I laughed so much I nearly spilled my tea."}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "后来呢？不是听说你把钥匙弄丢了？", "p": ["hòu", "lái", "ne", "", "bú", "shì", "tīng", "shuō", "nǐ", "bǎ", "yào", "shi", "nòng", "diū", "le", ""], "vi": "Sau thì sao? Chẳng phải nghe nói cậu làm mất chìa khóa sao?", "en": "And afterwards? Didn't I hear you lost the key?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "没丢。我把它存在前台了，第二天一早就取回来。", "p": ["méi", "diū", "", "wǒ", "bǎ", "tā", "cún", "zài", "qián", "tái", "le", "", "dì", "èr", "tiān", "yì", "zǎo", "jiù", "qǔ", "huí", "lái", ""], "vi": "Không mất. Mình gửi ở quầy lễ tân, sáng hôm sau lấy lại ngay.", "en": "I didn't lose it. I left it at the front desk, and collected it first thing the next morning."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "还好。要是真丢了，那一晚恐怕大家都睡不好。", "p": ["hái", "hǎo", "", "yào", "shi", "zhēn", "diū", "le", "", "nà", "yì", "wǎn", "kǒng", "pà", "dà", "jiā", "dōu", "shuì", "bù", "hǎo", ""], "vi": "May. Nếu thật sự mất, e đêm ấy ai cũng ngủ không yên.", "en": "Luckily. If it had really been lost, I'm afraid nobody would have slept well that night."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "所以现在出门，钥匙我都先问自己：究竟放哪儿了？", "p": ["suǒ", "yǐ", "xiàn", "zài", "chū", "mén", "", "yào", "shi", "wǒ", "dōu", "xiān", "wèn", "zì", "jǐ", "", "jiū", "jìng", "fàng", "nǎ", "r", "le", ""], "vi": "Nên giờ ra khỏi cửa, chìa khóa mình đều tự hỏi trước: rốt cuộc để đâu rồi?", "en": "So now, when I go out, I always first ask myself about the key: where exactly have I put it?"}]}, {"n": 4, "zh": "短文：树下那碗汤，和一句普通话", "vi": "Đoạn văn: Bát canh dưới gốc cây, và một câu tiếng phổ thông", "en": "Passage: A bowl of soup under the tree, and a sentence in Putonghua", "kw": ["普通话", "对话", "棵", "汤"], "lines": [{"s": "", "sp": [], "t": "回老家的那天，我和舅舅坐在一棵老树下面喝汤。他先用家乡话跟我说话，我听得半懂不懂，只好用普通话说：“您再说一遍，好吗？”那一轮小小的对话并不长，可我忽然明白：语言不是为了比谁说得更标准，而是为了把一碗汤、一句关心送到对方面前。后来他也慢慢用普通话跟我讲树上的鸟。汤已经凉了，话却还热着。", "p": ["huí", "lǎo", "jiā", "de", "nà", "tiān", "", "wǒ", "hé", "jiù", "jiù", "zuò", "zài", "yì", "kē", "lǎo", "shù", "xià", "miàn", "hē", "tāng", "", "tā", "xiān", "yòng", "jiā", "xiāng", "huà", "gēn", "wǒ", "shuō", "huà", "", "wǒ", "tīng", "de", "bàn", "dǒng", "bù", "dǒng", "", "zhǐ", "hǎo", "yòng", "pǔ", "tōng", "huà", "shuō", "", "", "nín", "zài", "shuō", "yí", "biàn", "", "hǎo", "ma", "", "", "nà", "yì", "lún", "xiǎo", "xiǎo", "de", "duì", "huà", "bìng", "bù", "cháng", "", "kě", "wǒ", "hū", "rán", "míng", "bái", "", "yǔ", "yán", "bú", "shì", "wèi", "le", "bǐ", "shuí", "shuō", "de", "gèng", "biāo", "zhǔn", "", "ér", "shì", "wèi", "le", "bǎ", "yì", "wǎn", "tāng", "", "yí", "jù", "guān", "xīn", "sòng", "dào", "duì", "fāng", "miàn", "qián", "", "hòu", "lái", "tā", "yě", "màn", "màn", "yòng", "pǔ", "tōng", "huà", "gēn", "wǒ", "jiǎng", "shù", "shàng", "de", "niǎo", "", "tāng", "yǐ", "jīng", "liáng", "le", "", "huà", "què", "hái", "rè", "zhe", ""], "vi": "Ngày về quê, tôi và cậu ngồi dưới một cây già uống canh. Cậu nói với tôi bằng tiếng quê trước, tôi nghe được nửa vời, đành dùng tiếng phổ thông: «Cậu nói lại một lần được không?» Vòng đối thoại nhỏ ấy không dài, nhưng tôi bỗng hiểu: ngôn ngữ không để so ai nói chuẩn hơn, mà để đưa một bát canh, một câu quan tâm đến trước mặt đối phương. Sau cậu cũng dần dùng tiếng phổ thông kể cho tôi về chim trên cây. Canh đã nguội, lời vẫn còn ấm.", "en": "The day I went back to my hometown, my uncle and I sat under an old tree and drank soup. He first spoke to me in the home dialect; I only half understood, and had to say in Putonghua, \"Would you say that again?\" That little exchange of dialogue was not long, but I suddenly understood: language is not for comparing who speaks more correctly, but for placing a bowl of soup and a sentence of care in front of the other person. Later he also slowly used Putonghua to tell me about the birds in the tree. The soup had already gone cold, but the words were still warm."}]}, {"n": 5, "zh": "短文：出发前把小吃也收拾进包里", "vi": "Đoạn văn: Trước lúc xuất phát hãy xếp cả món vặt vào túi", "en": "Passage: Before setting out, pack the snacks into the bag too", "kw": ["出发", "收拾", "小吃", "辣", "酸", "香"], "lines": [{"s": "", "sp": [], "t": "每次出发前，我都要先收拾房间，再收拾包。衣服可以少带一件，小吃却常被我放进去：一包微辣的豆，一盒微酸的果干，还有家里烤的、很香的小饼。路上不一定每顿都能遇到合口的饭，可这些熟悉的味道会让人觉得，自己并没有走得太远。辣的让人清醒，酸的让人口里有回味，香的则像一封短短的家信。把它们收好，再关上门，路就没有那么硬了。", "p": ["měi", "cì", "chū", "fā", "qián", "", "wǒ", "dōu", "yào", "xiān", "shōu", "shi", "fáng", "jiān", "", "zài", "shōu", "shi", "bāo", "", "yī", "fú", "kě", "yǐ", "shǎo", "dài", "yí", "jiàn", "", "xiǎo", "chī", "què", "cháng", "bèi", "wǒ", "fàng", "jìn", "qù", "", "yì", "bāo", "wēi", "là", "de", "dòu", "", "yì", "hé", "wēi", "suān", "de", "guǒ", "gàn", "", "hái", "yǒu", "jiā", "lǐ", "kǎo", "de", "", "hěn", "xiāng", "de", "xiǎo", "bǐng", "", "lù", "shàng", "bù", "yí", "dìng", "měi", "dùn", "dōu", "néng", "yù", "dào", "hé", "kǒu", "de", "fàn", "", "kě", "zhè", "xiē", "shú", "xī", "de", "wèi", "dao", "huì", "ràng", "rén", "jué", "de", "", "zì", "jǐ", "bìng", "méi", "yǒu", "zǒu", "de", "tài", "yuǎn", "", "là", "de", "ràng", "rén", "qīng", "xǐng", "", "suān", "de", "ràng", "rén", "kǒu", "lǐ", "yǒu", "huí", "wèi", "", "xiāng", "de", "zé", "xiàng", "yì", "fēng", "duǎn", "duǎn", "de", "jiā", "xìn", "", "bǎ", "tā", "men", "shōu", "hǎo", "", "zài", "guān", "shàng", "mén", "", "lù", "jiù", "méi", "yǒu", "nà", "me", "yìng", "le", ""], "vi": "Mỗi lần trước lúc xuất phát, tôi phải xếp phòng trước, rồi mới xếp túi. Áo có thể bớt một món, nhưng đồ ăn vặt tôi thường bỏ vào: một gói đậu hơi cay, một hộp quả khô hơi chua, và bánh nhỏ nhà nướng, rất thơm. Dọc đường chưa chắc bữa nào cũng gặp cơm hợp miệng, nhưng những vị quen ấy khiến người ta thấy mình chưa đi quá xa. Cay làm người tỉnh, chua để lại dư vị trong miệng, thơm thì như một lá thư nhà ngắn. Thu chúng cho xong, rồi đóng cửa, đường không cứng đến thế nữa.", "en": "Every time, before I set out, I first tidy the room, then pack the bag. I can take one fewer item of clothing, but I often put snacks in: a packet of slightly spicy beans, a box of slightly sour dried fruit, and some very fragrant little cakes baked at home. On the road you may not find a meal that suits you at every sitting, but these familiar flavours make you feel you have not gone too far. The spicy ones wake you up, the sour ones leave a taste in the mouth, and the fragrant ones are like a short letter from home. Once they are packed away and the door is shut, the road is not quite so hard."}]}]}];
